local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>The Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430101_2_dialog_content = "Your Honor, that is not the case!",
  ui_story_5043_50430101_3_dialog_content = "I swear to the God of Light, I have not lied to her in matters of the heart.",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50430101_5_dialog_content = "Order in court! The defendant will refrain from interrupting the plaintiff.",
  ui_story_5043_50430101_6_dialog_content = "Please continue, Judge Leyn.",
  ui_story_5043_50430101_7_dialog_content = "Miss, you just stated that the plaintiff failed to carry out his duties as your fiance during the period of your engagement. Is that correct?",
  ui_story_5043_50430101_8_dialog_content = "It is!",
  ui_story_5043_50430101_9_dialog_content = "You may make a final statement before the court commences its deliberations.",
  ui_story_5043_50430101_10_dialog_content = "Last month's Mooncrown Day was the seven-month anniversary of our engagement.",
  ui_story_5043_50430101_11_dialog_content = "But that good-for-nothing didn't even care!",
  ui_story_5043_50430101_12_dialog_content = "Oh, please. You can't expect me to celebrate our engagement every month!",
  ui_story_5043_50430101_13_dialog_content = "I might not have objected. But you managed to buy different presents for several other people!",
  ui_story_5043_50430101_14_dialog_content = "Wait a minute. I already explained, those were for business connections of my family—",
  ui_story_5043_50430101_15_dialog_content = "H-Hold on! Don't start arguing, now...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>Tina, you're a judge now. Act like one!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>Oh yes, that's right! I am. Okay, watch this. Ahem...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>Order, order!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>*Crowd mumbling*</color>",
  ui_story_5043_50430101_20_dialog_content = "(What I want to know is why I'm sitting here listening to a lovers' tiff...)",
  ui_story_5043_50430101_21_dialog_content = "Getting impatient, PlayerName? You're starting to look bored.",
  ui_story_5043_50430101_22_dialog_content = "What, me? Not at all... Oh, okay, you're right as usual, Carleen.",
  ui_story_5043_50430101_23_dialog_content = "To be honest, I feel exactly the same.",
  ui_story_5043_50430101_24_dialog_content = "But unlike you, I can't let it show. After all—",
  ui_story_5043_50430101_25_dialog_content = "I know. To some degree, it would reflect poorly on the City Lord over there.",
  ui_story_5043_50430101_26_dialog_content = "...",
  ui_story_5043_50430101_27_dialog_content = "So far, he hasn't said a thing.",
  ui_story_5043_50430101_28_dialog_content = "Sorry. I initially meant for you to come to Lumopolis Gardens to give a report on your adventures in Longzhou.",
  ui_story_5043_50430101_29_dialog_content = "But it looks like the City Lord isn't going to be able to spare the time.",
  ui_story_5043_50430101_30_dialog_content = "It's no problem. It's not as if I have anything urgent to do.",
  ui_story_5043_50430101_31_dialog_content = "<size=30>And to be honest, I don't really want to back into one of those solemn conference rooms...</size>",
  ui_story_5043_50430101_32_dialog_content = "Sorry, what?",
  ui_story_5043_50430101_33_dialog_content = "Nothing!",
  ui_story_5043_50430101_34_dialog_content = "(Now I think about it, I haven't been here since that <color=#FFB400>incident</color>...)",
  ui_story_5043_50430101_35_dialog_content = "(Irridon was sitting where she is now, reading out the Hall of Justice's verdict on Carleen.)",
  ui_story_5043_50430101_36_dialog_content = "(And Carleen... well, she's changed a lot since then.)",
  ui_story_5043_50430101_37_dialog_content = "PlayerName, are you daydreaming?",
  ui_story_5043_50430101_38_dialog_content = "Uhm, well... I was just thinking...",
  ui_story_5043_50430101_39_dialog_content = "I was just thinking about the effect Mooncrown Day has on Lumopolis!",
  ui_story_5043_50430101_40_dialog_content = "Yes, this kind of thing is common at this time of year.",
  ui_story_5043_50430101_41_dialog_content = "As young men and women enjoy the Mooncrown atmosphere, some start new romances, and sometimes cracks form in existing relationships.",
  ui_story_5043_50430101_42_dialog_content = "Then, there are the decadent nobles who have a tendency to try and think of ways to make the entertainment last as long as possible.",
  ui_story_5043_50430101_43_dialog_content = "As a result, the Hall of Justice ends up with a pile of relationship disputes to handle.",
  ui_story_5043_50430101_44_dialog_content = "The City Lord sits in to listen more often than usual, to prevent possible unprecedented situations from occurring or going out of control.",
  ui_story_5043_50430101_45_dialog_content = "Anyway, I enjoy sitting here in the audience more than sitting in the defendant's chair.",
  ui_story_5043_50430101_46_dialog_content = "Carleen...",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>Order!</size>",
  ui_story_5043_50430101_49_dialog_content = "All in all, it was mean and unforgivable!",
  ui_story_5043_50430101_50_dialog_content = "I therefore request the court to terminate our engagement!",
  ui_story_5043_50430101_51_dialog_content = "Heheh. Dear plaintiff, I certainly understand where you're coming from.",
  ui_story_5043_50430101_52_dialog_content = "As I understand it, this was a long-standing arrangement between your families. And you and the defendant were childhood sweethearts.",
  ui_story_5043_50430101_53_dialog_content = "Which makes sense. It's hard to imagine a man such as the defendant winning the heart of a fair lady such as yourself without such advantages.",
  ui_story_5043_50430101_54_dialog_content = "You're right. We did grow up together, which is why I know him better than anyone.",
  ui_story_5043_50430101_55_dialog_content = "How enviable. Why, I'm almost jealous of the defendant.",
  ui_story_5043_50430101_56_dialog_content = "(What?! This judge is a bit creepy!)",
  ui_story_5043_50430101_57_dialog_content = "J-Judge Schwab...",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50430101_59_dialog_content = "Judge Schwab, please maintain your professionalism.",
  ui_story_5043_50430101_60_dialog_content = "After all, even I and the Chief Judge have no knowledge of the defendant's character.",
  ui_story_5043_50430101_61_dialog_content = "All we can ascertain is that you must have come to your decision after a great deal of consideration based on the number of years you have known him.",
  ui_story_5043_50430101_62_dialog_content = "Er...?",
  ui_story_5043_50430101_63_dialog_content = "(Heh. She fell for it.)",
  ui_story_5043_50430101_64_dialog_content = "Uh, I...",
  ui_story_5043_50430101_65_dialog_content = "Defendant, do you have anything to say before Chief Judge Irridon delivers the verdict?",
  ui_story_5043_50430101_66_dialog_content = "<size=45>My darling! You have always been the only one for me!</size>",
  ui_story_5043_50430101_67_dialog_content = "H-How could you say such things here...",
  ui_story_5043_50430101_68_dialog_content = "Very well. And next—",
  ui_story_5043_50430101_69_dialog_content = "<size=45>Wait!</size>",
  ui_story_5043_50430101_70_dialog_content = "I'm sorry. But I have reconsidered.",
  ui_story_5043_50430101_71_dialog_content = "I wish to <color=#FFB400>withdraw</color> my case.",
  ui_story_5043_50430101_72_dialog_content = "(What, just like that?)",
  ui_story_5043_50430101_73_dialog_content = "I'm truly sorry. I failed to consider my actions fully. We should have resolved our misunderstandings ourselves.",
  ui_story_5043_50430101_74_dialog_content = "No. It's my fault for not being more loving. It's me who has wronged you.",
  ui_story_5043_50430101_75_dialog_content = "Request denied. The court processes must be respected. There are formalities to be followed both when bringing a case and when withdrawing one.",
  ui_story_5043_50430101_76_dialog_content = "But there is an easier way to handle this.",
  ui_story_5043_50430101_77_dialog_content = "I find the defendant—",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50430101_79_dialog_content = "—not guilty!",
  ui_story_5043_50430101_80_dialog_content = "Dearest!",
  ui_story_5043_50430101_81_dialog_content = "Sweetness! Come, let's go for afternoon tea...",
  ui_story_5043_50430101_82_dialog_content = "Case closed. Court is adjourned.",
  ui_story_5043_50430101_83_dialog_content = "Lord Schwab, please wait!",
  ui_story_5043_50430101_84_dialog_content = "Congratulations on a successful hearing, Lord Schwab! Please take these flowers!",
  ui_story_5043_50430101_85_dialog_content = "A-And I also have some white chocolate for you. Here...",
  ui_story_5043_50430101_86_dialog_content = "(Ugh...)",
  ui_story_5043_50430101_87_dialog_content = "One at a time, my pretties. Form an orderly queue...",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Office of the Chief Judge</color>",
  ui_story_5043_50430101_89_dialog_content = "The point of having rules is to allow us to quickly see where chaos still reigns.",
  ui_story_5043_50430101_90_dialog_content = "For how long have these ridiculous relationship cases been showing up in court?",
  ui_story_5043_50430101_91_dialog_content = "City Lord, sir, only in this past month.",
  ui_story_5043_50430101_92_dialog_content = "I see. Ah, to be young again...",
  ui_story_5043_50430101_93_dialog_content = "But the Hall of Justice is a sacred, serious place.",
  ui_story_5043_50430101_94_dialog_content = "You wish us to stop hearing these cases, my lord?",
  ui_story_5043_50430101_95_dialog_content = "No, it's not time for that yet.",
  ui_story_5043_50430101_96_dialog_content = "That would just result in the citizens directing their anger at the Hall of Justice.",
  ui_story_5043_50430101_97_dialog_content = "What would you have us do, then?",
  ui_story_5043_50430101_98_dialog_content = "Establish a temporary subordinate court to handle these romantic disputes.",
  ui_story_5043_50430101_99_dialog_content = "It'll still be part of Lumopolis Gardens, but separate from the Hall of Justice.",
  ui_story_5043_50430101_100_dialog_content = "As for staffing... send over some of the younger folk. It'll be good experience for them.",
  ui_story_5043_50430101_101_dialog_content = "A temporary court will require a temporary chief judge.",
  ui_story_5043_50430101_102_dialog_content = "May I ask if you have anyone in mind?",
  ui_story_5043_50430101_103_dialog_content = "I did happen to notice one particular young candidate earlier...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>The Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430101_105_dialog_content = "It looks like Irridon and the City Lord are discussing important business.",
  ui_story_5043_50430101_106_dialog_content = "I guess today's meeting isn't happening. If I remember correctly, the next free slot in his schedule is...",
  ui_story_5043_50430101_107_dialog_content = "Oh, sorry, PlayerName. You're going to be waiting for days.",
  ui_story_5043_50430101_108_dialog_content = "You'll get used to it. He always breaks his appointments and ignores other people's opinions.",
  ui_story_5043_50430101_109_dialog_content = "D-Don't talk like that. And we've got some free time now, right?",
  ui_story_5043_50430101_110_dialog_content = "Even just watching these judges tidy up their papers is a great way to pass the time.",
  ui_story_5043_50430101_111_dialog_content = "Indictment. Evidence. Arguments... Okay, that's everything.",
  ui_story_5043_50430101_112_dialog_content = "I'm almost finished here. Tina, how are you doing?",
  ui_story_5043_50430101_113_dialog_content = "Eh? What?",
  ui_story_5043_50430101_114_dialog_content = "Oh sorry, Leyn. That hearing went on for three hours. I'm all—yawn...",
  ui_story_5043_50430101_115_dialog_content = "Oh, it's like that, huh?",
  ui_story_5043_50430101_116_dialog_content = "What a busy day you've had. Here, my dear Tina, have a cup of comfort drink to make you feel better...",
  ui_story_5043_50430101_117_dialog_content = "Mhm, thank you, Leyn. *Gulp*",
  ui_story_5043_50430101_118_dialog_content = "Eh!?",
  ui_story_5043_50430101_119_dialog_content = "H-Hot chocolate?! I hate sweet drinks!!!",
  ui_story_5043_50430101_120_dialog_content = "Heehee, awake now, are you? I don't care if you've got narcolepsy. Work first, sleep later.",
  ui_story_5043_50430101_121_dialog_content = "And now that I think about it... I feel like you've been sleepier than usual the last couple of days.",
  ui_story_5043_50430101_122_dialog_content = "I don't think so. I make a point of being awake for four hours every day.",
  ui_story_5043_50430101_123_dialog_content = "Even today? And you started yawning before we finished work yesterday.",
  ui_story_5043_50430101_124_dialog_content = "Didn't you sleep well? I can't imagine you suffering from insomnia.",
  ui_story_5043_50430101_125_dialog_content = "What? That's ridiculous. As if...",
  ui_story_5043_50430101_126_dialog_content = "Okay, that's everything tidied away. I'm going home.",
  ui_story_5043_50430101_127_dialog_content = "See you tomorrow, everyone.",
  ui_story_5043_50430101_128_dialog_content = "Yeah, I'll be going soon.",
  ui_story_5043_50430101_129_dialog_content = "Goodbye, Lady Carleen and male companion.",
  ui_story_5043_50430101_130_dialog_content = "See you!",
  ui_story_5043_50430101_131_dialog_content = "(Is that what I've been reduced to? \"Male companion\"?)",
  ui_story_5043_50430101_132_dialog_content = "Wow! Long time no see, Lady Carleen's male companion!",
  ui_story_5043_50430101_133_dialog_content = "I know that voice...",
  ui_story_5043_50430101_134_dialog_content = "Matthieu! And Loewe. I didn't expect to see you two.",
  ui_story_5043_50430101_135_dialog_content = "Matthieu, I see you are as idle and cheeky as ever.",
  ui_story_5043_50430101_136_dialog_content = "Don't be angry, Princess. I'm not here to idle.",
  ui_story_5043_50430101_137_dialog_content = "Something interesting is afoot. Do you want in?",
  ui_story_5043_50430101_138_dialog_content = "Something \"interesting\"?",
  ui_story_5043_50430101_139_dialog_content = "Yes. I just got word myself. The commoners won't be hearing about it until tomorrow.",
  ui_story_5043_50430101_140_dialog_content = "Go on.",
  ui_story_5043_50430101_141_dialog_content = "It's like this. The court has a very unusual case to hear. Now, it hasn't been assigned yet, but...",
  ui_story_5043_50430101_142_dialog_content = "It's as good as mine.",
  ui_story_5043_50430101_143_dialog_content = "What he means is he begged and begged the Chief Judge desperately until he got it.",
  ui_story_5043_50430101_144_dialog_content = "Hey! Stop interrupting.",
  ui_story_5043_50430101_145_dialog_content = "Anyway, it's connected to Mooncrown Day...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Residential District</color>",
  ui_story_5043_50430101_147_dialog_content = "La la... lalala... la la ♪...",
  ui_story_5043_50430101_148_dialog_content = "(First thing to do when coming home: check for any letters or packages...)",
  ui_story_5043_50430101_149_dialog_content = "Oh...",
  ui_story_5043_50430101_150_dialog_content = "Still nothing.",
  ui_story_5043_50430101_151_dialog_content = "(I still have the leaves and nuts <color=#FFB400>he</color> sent me last month.)",
  ui_story_5043_50430101_152_dialog_content = "(It's time I sent something in return, but <color=#FFB400>he</color> still hasn't given me his new address.)",
  ui_story_5043_50430101_153_dialog_content = "(And now that I think about it, it's been almost a month since I heard from <color=#FFB400>him</color>.)",
  ui_story_5043_50430101_154_dialog_content = "(It's quite worrying... When will I be able to send the cookies I made for <color=#FFB400>him</color>?)",
  ui_story_5043_50430101_155_dialog_content = "(Maybe I should... be a bit more proactive?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>The Next Day</color>",
  ui_story_5043_50430201_2_dialog_content = "So that's the way things are.",
  ui_story_5043_50430201_3_dialog_content = "The City Lord has decided to set up a temporary court within Lumopolis Gardens.",
  ui_story_5043_50430201_4_dialog_content = "I've decided to call it the <color=#FFB400>Romance Division</color>.",
  ui_story_5043_50430201_5_dialog_content = "I understand. And I'll continue to do my very best there.",
  ui_story_5043_50430201_6_dialog_content = "But if I may ask, who will serve as the chief judge? Will you also take on that burden?",
  ui_story_5043_50430201_7_dialog_content = "No, we have had guidance from the City Lord on that matter. He has suggested Judge <color=#FFB400>Schwab</color>.",
  ui_story_5043_50430201_8_dialog_content = "A decision I don't entirely understand, though he did seem to make an impression on the City Lord yesterday...",
  ui_story_5043_50430201_9_dialog_content = "And perhaps his style is particularly suited for dealing with love affairs.",
  ui_story_5043_50430201_10_dialog_content = "Very well. Schwab did have his own unique way of resolving that mess yesterday. I was impressed.",
  ui_story_5043_50430201_11_dialog_content = "He certainly knows how to use his... charms.",
  ui_story_5043_50430201_12_dialog_content = "You mustn't be disappointed, Leyn.",
  ui_story_5043_50430201_13_dialog_content = "You've all just become official judges, but the City Lord appreciates your abilities.",
  ui_story_5043_50430201_14_dialog_content = "And when you return from the Romance Division, you will be well-positioned for promotion.",
  ui_story_5043_50430201_15_dialog_content = "Yes. Thanks, Chief Judge.",
  ui_story_5043_50430201_16_dialog_content = "Also, I have another task for you.",
  ui_story_5043_50430201_17_dialog_content = "In fact, it could be the trickiest case the Romance Division has to handle at the moment.",
  ui_story_5043_50430201_18_dialog_content = "You might have heard of it? <color=#FFB400>The case of the headless statue</color>?",
  ui_story_5043_50430201_19_dialog_content = "I get my first case so soon?",
  ui_story_5043_50430201_20_dialog_content = "Ah, it's a relief to hear you are so keen. I have had five or six people decline the case already.",
  ui_story_5043_50430201_21_dialog_content = "And why did they do so?",
  ui_story_5043_50430201_22_dialog_content = "Apart from the fact that it's a weird case... most of them said they were busy going on dates with their lovers.",
  ui_story_5043_50430201_23_dialog_content = "Ah, I see...",
  ui_story_5043_50430201_24_dialog_content = "(Those nobles never change...)",
  ui_story_5043_50430201_25_dialog_content = "The plaintiff in the case is a noble from Lumopolis Courtyard, Mr. <color=#FFB400>Byron</color>.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>Four days ago</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>Ding, ding—Ding—</color>",
  ui_story_5043_50430201_28_dialog_content = "I'm coming, I'm coming. Stop dinging!",
  ui_story_5043_50430201_29_dialog_content = "You rang, sir? You rang the Bell of Justice?",
  ui_story_5043_50430201_30_dialog_content = "I did. I wish to sue someone! It's my neighbor.",
  ui_story_5043_50430201_31_dialog_content = "He damaged <color=#FFB400>Galatea</color>, the statue that stands outside the Hall of Justice. I saw it with my own eyes!",
  ui_story_5043_50430201_32_dialog_content = "Hang on. I know the statue out there symbolizes justice. But since when has it been named Galatea?",
  ui_story_5043_50430201_33_dialog_content = "And yeah, it broke a few days ago, but to be honest, we thought it was just old...",
  ui_story_5043_50430201_34_dialog_content = "Miss, please mind your language. Galatea is a <color=#FFB400>\"she\"</color>!!! It was I who named her.",
  ui_story_5043_50430201_35_dialog_content = "Er, alright. Then, would you please hand me your complaint?",
  ui_story_5043_50430201_36_dialog_content = "Let me see...",
  ui_story_5043_50430201_37_dialog_content = "Hm? Mr. Byron, the crime you accuse your neighbor of—is this correct?",
  ui_story_5043_50430201_38_dialog_content = "You just said he damaged the statue, but here you've written <color=#FFB400>\"obstruction of love</color>.\"",
  ui_story_5043_50430201_39_dialog_content = "That's correct. Because...",
  ui_story_5043_50430201_40_dialog_content = "Galatea is my <color=#FFB400>lover</color>!",
  ui_story_5043_50430201_41_dialog_content = "So he fell in love with a statue... and now wishes to sue the person who vandalized it?",
  ui_story_5043_50430201_42_dialog_content = "Yes. Because the statue is classified as a public facility, we can't prevent someone from falling in love with it.",
  ui_story_5043_50430201_42X1_dialog_content = "And so, strictly speaking, this is a case for the Romance Division.",
  ui_story_5043_50430201_43_dialog_content = "I've also sent people to speak to the defendant.",
  ui_story_5043_50430201_44_dialog_content = "There are holes in Mr. Byron's story. The defendant in the case might not be the suspect.",
  ui_story_5043_50430201_45_dialog_content = "As you know, here in the Hall of Justice, we investigate as much as we judge. Leyn, we must figure out what's going on before the case is heard.",
  ui_story_5043_50430201_46_dialog_content = "Otherwise we'll just end up adjourning the case until some future hearing. And the Romance Division isn't even a permanent arrangement, so that's not an option.",
  ui_story_5043_50430201_47_dialog_content = "Yes, I understand. I'll solve the case before the Romance Division closes, I assure you.",
  ui_story_5043_50430201_48_dialog_content = "I'm glad to hear that. And two of your colleagues will be assisting you.",
  ui_story_5043_50430201_49_dialog_content = "One is your old friend, Tina. She agreed to help this morning.",
  ui_story_5043_50430201_50_dialog_content = "I've asked her to review the paperwork, although I suspect she's catching up on her sleep now.",
  ui_story_5043_50430201_51_dialog_content = "The other... well, he's a headache, but he's technically <color=#FFB400>more experienced</color> than you. I'm sure he will give you some useful pointers.",
  ui_story_5043_50430201_52_dialog_content = "You can meet with him now, in front of that statue.",
  ui_story_5043_50430201_53_dialog_content = "Compare notes with Tina when you finish your investigations.",
  ui_story_5043_50430201_54_dialog_content = "I'll go right away.",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, by the statue</color>",
  ui_story_5043_50430201_56_dialog_content = "(I wonder who this \"more experienced\" person the Chief Judge was being so vague about is...)",
  ui_story_5043_50430201_57_dialog_content = "Oh my, is the Hall of Justice just letting any commoner in the door now?",
  ui_story_5043_50430201_58_dialog_content = "(I should have guessed...)",
  ui_story_5043_50430201_59_dialog_content = "I think Leyn looks more like a proper judge than you do, Matthieu.",
  ui_story_5043_50430201_60_dialog_content = "Good day, Captain Carleen, and my very best wishes.",
  ui_story_5043_50430201_61_dialog_content = "Please, do not stand on ceremony. This is PlayerName. Matthieu here has asked us both to lend a hand in the investigation.",
  ui_story_5043_50430201_62_dialog_content = "You're the legendary Caelestite! You're so much more approachable in person!",
  ui_story_5043_50430201_63_dialog_content = "Y-You're very kind. I hope I can be of some help.",
  ui_story_5043_50430201_64_dialog_content = "<size=32>What in the world do the rumors say about me...</size>",
  ui_story_5043_50430201_65_dialog_content = "You should give thanks to the God of Light, commoner. With our help, your work is bound to proceed swiftly.",
  ui_story_5043_50430201_66_dialog_content = "I'll just be amazed if it doesn't go badly.",
  ui_story_5043_50430201_67_dialog_content = "What's wrong, rookie? You don't seem excited.",
  ui_story_5043_50430201_68_dialog_content = "This is one of the strangest cases in the history of the Hall of Justice. Show a little enthusiasm!",
  ui_story_5043_50430201_69_dialog_content = "Yes. An odd statue, an odd crime, an odd plaintiff. And an odd mentor.",
  ui_story_5043_50430201_70_dialog_content = "Watch it, kid! Show a little more respect.",
  ui_story_5043_50430201_71_dialog_content = "Very well. I didn't come here to bicker with you. I assume you've examined the statue?",
  ui_story_5043_50430201_72_dialog_content = "Huh? Oh, you mean the money box?",
  ui_story_5043_50430201_73_dialog_content = "Sorry, it's just without the head, it reminds me of something you might save coins in. It makes me want to throw a Nightium in.",
  ui_story_5043_50430201_74_dialog_content = "Oh, please. Try and take this seriously...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>Snap—</color>",
  ui_story_5043_50430201_76_dialog_content = "What was that?",
  ui_story_5043_50430201_77_dialog_content = "Graaaaaah! Roar!",
  ui_story_5043_50430201_78_dialog_content = "What in the world?! How did Eclipsites get into Lumopolis Gardens?",
  ui_story_5043_50430201_79_dialog_content = "It's impossible! Lumopolis is guarded day and night. There's no way an Eclipsite could get in...",
  ui_story_5043_50430201_80_dialog_content = "Guards!",
  ui_story_5043_50430201_81_dialog_content = "Ma'am!",
  ui_story_5043_50430201_82_dialog_content = "I'm going to check all entry and exit records. And tell the Nightwatch I want a report on all recent activity!",
  ui_story_5043_50430201_83_dialog_content = "As for the Eclipsites... PlayerName, I assume you four can deal with them?",
  ui_story_5043_50430201_84_dialog_content = "Of course. Go, Carleen.",
  ui_story_5043_50430201_85_dialog_content = "Okay then. Time for the Eclipsites to receive their final verdict.",
  ui_story_5043_50430202_1_dialog_content = "It's over! Nobody got hurt, did they?",
  ui_story_5043_50430202_2_dialog_content = "I'm fine. Just a bit disgusted.",
  ui_story_5043_50430202_3_dialog_content = "I just got to work. Now I need a bath again.",
  ui_story_5043_50430202_4_dialog_content = "Hey, commoner, are you okay?",
  ui_story_5043_50430202_5_dialog_content = "Thanks for asking. As it happens, I'm not blessed with the same need for constant bathing you aristocrats enjoy.",
  ui_story_5043_50430202_6_dialog_content = "I feel so sorry for you. Although I suppose that means Loewe is the biggest germaphobe here.",
  ui_story_5043_50430202_7_dialog_content = "You always have yourself covered up so tightly, Loewe. I suspect you even find the air dirty.",
  ui_story_5043_50430202_8_dialog_content = "You guys can probably step down if the statue is broken.",
  ui_story_5043_50430202_9_dialog_content = "Don't ignore me!",
  ui_story_5043_50430202_10_dialog_content = "Okay, you've seen enough. The Hall of Justice can deal with it now.",
  ui_story_5043_50430202_11_dialog_content = "Crucial <color=#FFB400>evidence</color> shouldn't be left sitting out in the open like this.",
  ui_story_5043_50430202_12_dialog_content = "According to the plaintiff, this is the <color=#FFB400>victim</color>.",
  ui_story_5043_50430202_13_dialog_content = "Wait, let me take a closer look...",
  ui_story_5043_50430202_14_dialog_content = "Hmm. The fracture section is cleaner. It doesn't look like an old crack that finally broke open.",
  ui_story_5043_50430202_15_dialog_content = "It's more like someone deliberately broke the head off.",
  ui_story_5043_50430202_16_dialog_content = "PlayerName, do you have any advice?",
  ui_story_5043_50430202_17_dialog_content = "There's one odd thing.",
  ui_story_5043_50430202_18_option_content = "The missing head",
  ui_story_5043_50430202_19_dialog_content = "It doesn't look like spontaneous vandalism. The break is too clean.",
  ui_story_5043_50430202_20_dialog_content = "Also, there's no other damage. Just the missing head.",
  ui_story_5043_50430202_21_option_content = "Statue fragments",
  ui_story_5043_50430202_22_dialog_content = "The surroundings are too clean. Shouldn't there be extra bits of the statue laying around?",
  ui_story_5043_50430202_23_dialog_content = "The people sent to collect the evidence probably swept those up.",
  ui_story_5043_50430202_24_dialog_content = "T-That makes sense! In that case, I guess the odd thing is—the missing head.",
  ui_story_5043_50430202_25_dialog_content = "I think you're right. It looks like someone broke off the head of the statue so they could <color=#FFB400>steal it</color>...",
  ui_story_5043_50430202_26_dialog_content = "Hey, hang on. Do any of you see <color=#FFB400>that</color>? I just appeared out of nowhere.",
  ui_story_5043_50430202_27_dialog_content = "Look, beside that window, in the sky over Lumopolis...",
  ui_story_5043_50430202_28_dialog_content = "It's a <color=#FFB400>moon</color>.",
  ui_story_5043_50430202_29_dialog_content = "I see it!",
  ui_story_5043_50430202_30_dialog_content = "Weird things just keep happening. What in the world is going on?",
  ui_story_5043_50430202_31_dialog_content = "How intriguing. Should we take a look?",
  ui_story_5043_50430202_32_dialog_content = "Hang on... We still have work to do!",
  ui_story_5043_50430202_33_dialog_content = "Oh, you're all here?",
  ui_story_5043_50430202_34_dialog_content = "Hey, Tina. This is PlayerName. The Caelestite.",
  ui_story_5043_50430202_35_dialog_content = "Heheh. Actually we met last month, on Mooncrown Day.",
  ui_story_5043_50430202_36_dialog_content = "Good morning, PlayerName. It's lovely to see you again.",
  ui_story_5043_50430202_37_dialog_content = "Hello, Tina. Although it isn't morning anymore...",
  ui_story_5043_50430202_38_dialog_content = "Tina always thinks it's morning when she wakes up.",
  ui_story_5043_50430202_39_dialog_content = "You have perfect timing, Tina. Let's share notes on the investigation.",
  ui_story_5043_50430202_40_dialog_content = "Then... let's both say what we have at the same time. So far, I've discovered—",
  ui_story_5043_50430202_41_dialog_content = "Nothing.",
  ui_story_5043_50430202_42_dialog_content = "Sigh. So you haven't made any progress either?",
  ui_story_5043_50430202_43_dialog_content = "I went over the case documents the Chief Judge gave me over and over again.",
  ui_story_5043_50430202_44_dialog_content = "But it's all so illogical and inconsistent. I can't make sense of any of it.",
  ui_story_5043_50430202_45_dialog_content = "We do have one potential theory, at least.",
  ui_story_5043_50430202_46_dialog_content = "PlayerName and I suspect that the statue's head was stolen.",
  ui_story_5043_50430202_47_dialog_content = "Right... Why would anyone do that?",
  ui_story_5043_50430202_48_dialog_content = "Who knows! Maybe Judge Jr. decided to get himself new headgear.",
  ui_story_5043_50430202_49_dialog_content = "If we're not making any progress, maybe we should call it quits for the day?",
  ui_story_5043_50430202_50_dialog_content = "Wait! Actually, I... Erm...",
  ui_story_5043_50430202_51_dialog_content = "The thing is, I wanted to ask you all for some advice on a private matter.",
  ui_story_5043_50430202_52_dialog_content = "Uh, what kind of private matter, exactly? I'm not sure I want to get involved...",
  ui_story_5043_50430202_53_dialog_content = "F-Fine. I've run into a little problem lately and wanted a second opinion.",
  ui_story_5043_50430202_54_dialog_content = "Oooh. A private matter, at a time like this?",
  ui_story_5043_50430202_55_dialog_content = "Let me venture a guess. It's a romantic problem, isn't it?",
  ui_story_5043_50430202_56_dialog_content = "You are way too excited about this.",
  ui_story_5043_50430202_57_dialog_content = "Mmm. Anyway, can I invite you all to come to my place? I've prepared tea and cakes.",
  ui_story_5043_50430202_58_dialog_content = "PlayerName, I'd like you to come as well.",
  ui_story_5043_50430202_59_dialog_content = "I hear you Caelestites are very good at understanding people's emotions. So you have to help me.",
  ui_story_5043_50430202_60_dialog_content = "It would be an honor. Although I'm not sure we have that particular ability...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Tina's home</color>",
  ui_story_5043_50430301_2_dialog_content = "Okay, this is what happened.",
  ui_story_5043_50430301_3_dialog_content = "On Mooncrown Day last month, I got a present from <color=#FFB400>him</color>.",
  ui_story_5043_50430301_4_dialog_content = "It was just some ordinary things, but I could tell that <color=#FFB400>he</color> really cared for me.",
  ui_story_5043_50430301_5_dialog_content = "W-Woah! Hold on, Tina. Are you in love?",
  ui_story_5043_50430301_6_dialog_content = "Huh? No, I don't think that's it...",
  ui_story_5043_50430301_7_dialog_content = "Well, this sounds like the kind of thing lovers do.",
  ui_story_5043_50430301_8_dialog_content = "If you think so too...",
  ui_story_5043_50430301_9_dialog_content = "Oh, never mind that! Let me finish the story.",
  ui_story_5043_50430301_10_dialog_content = "It's been almost a month since Mooncrown Day, and according to tradition, I should send <color=#FFB400>him</color> a gift in return.",
  ui_story_5043_50430301_11_dialog_content = "So I made some cookies for <color=#FFB400>him</color>. I even made each cookie in a different shape.",
  ui_story_5043_50430301_12_dialog_content = "So the cookies were all ready to be sent. But...",
  ui_story_5043_50430301_13_dialog_content = "But <color=#FFB400>he</color> hasn't replied to any more of my letters.",
  ui_story_5043_50430301_14_dialog_content = "I haven't had a chance to sneak a meeting with <color=#FFB400>him</color>. And now I don't even get any letters.",
  ui_story_5043_50430301_15_dialog_content = "I'm so worried. It's been keeping me awake. I'm only sleeping 16 hours a night!",
  ui_story_5043_50430301_16_dialog_content = "What a despicable man!",
  ui_story_5043_50430301_17_dialog_content = "Yes. He sounds worse than Matthieu.",
  ui_story_5043_50430301_18_dialog_content = "I suggest you just give up on him.",
  ui_story_5043_50430301_19_dialog_content = "No, I can't do that yet. I'm sure he's got his reasons.",
  ui_story_5043_50430301_20_dialog_content = "After all, <color=#FFB400>he</color> has a rather unique appearance. People notice <color=#FFB400>him</color> wherever he goes. So perhaps he can't keep in touch as much as he would like.",
  ui_story_5043_50430301_21_dialog_content = "Uh-oh. Tina's got a bad case of being in love.",
  ui_story_5043_50430301_22_dialog_content = "Hmm...?",
  ui_story_5043_50430301_23_dialog_content = "<size=32>Hey, PlayerName, Matthieu, Loewe. I've got a theory...</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>This <color=#FFB400>man</color> Tina's talking about sounds kind of familiar!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>True! Someone who gets noticed everywhere he goes...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>And makes only a minimal effort to keep his admirers happy...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>And is cruel, shallow, self-obsessed, egotistical...</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>Sounds like he could be your twin.</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>Anyway, this person Tina's talking about has to be <color=#FFB400>Schwab</color>, right?</size>",
  ui_story_5043_50430301_30_dialog_content = "Hey, what are you whispering about?",
  ui_story_5043_50430301_31_dialog_content = "Ahem. Okay, Tina. We know who your crush is.",
  ui_story_5043_50430301_32_dialog_content = "What? You guessed already? I-I was hoping to keep it a secret...",
  ui_story_5043_50430301_33_dialog_content = "(Looks like Tina has no choice but to admit it...)",
  ui_story_5043_50430301_34_dialog_content = "The first time I saw him was at Salar Manor.",
  ui_story_5043_50430301_35_dialog_content = "I'd been invited to a dance there.",
  ui_story_5043_50430301_36_dialog_content = "But I arrived a little early and I was shown into the garden to wait.",
  ui_story_5043_50430301_37_dialog_content = "But of course, the Salars have an incredible garden, and I got lost in the hedge maze.",
  ui_story_5043_50430301_38_dialog_content = "Heaven knows how long I spent in there. Then, suddenly, I came across a little pavilion, and he was sitting in it.",
  ui_story_5043_50430301_39_dialog_content = "He was surprised to see anyone there. And we just spent so long gazing at each other under that beautiful blue sky...",
  ui_story_5043_50430301_40_dialog_content = "It was the first time I noticed how gentle and kind he could be. He seemed to be one with the trees and flowers around him.",
  ui_story_5043_50430301_41_dialog_content = "He ended up leaving before me. But I couldn't pay attention to anyone else that day.",
  ui_story_5043_50430301_42_dialog_content = "Heheh. How romantic.",
  ui_story_5043_50430301_43_dialog_content = "(Salar Manor. Then it has to be Schwab Salar.)",
  ui_story_5043_50430301_44_dialog_content = "(\"Gentle\"? \"Kind\"?! That guy?? If you say so...)",
  ui_story_5043_50430301_45_dialog_content = "Given you already know who he is, I have a favor to ask of you all.",
  ui_story_5043_50430301_46_dialog_content = "I need you to help me with <color=#FFB400>Operation Acci-Meet</color>.",
  ui_story_5043_50430301_47_dialog_content = "What in the world is an Acci-Meet?",
  ui_story_5043_50430301_48_dialog_content = "Well, I want to engineer as many <color=#FFB400>accidental meetings</color> with him as possible. Accimeet. Clever, huh?",
  ui_story_5043_50430301_49_dialog_content = "You're not going to give up, are you? Even if we don't help you.",
  ui_story_5043_50430301_50_dialog_content = "No. Sorry...",
  ui_story_5043_50430301_51_dialog_content = "Very well. I'm always happy to help a colleague.",
  ui_story_5043_50430301_52_dialog_content = "Me too.",
  ui_story_5043_50430301_53_dialog_content = "Gaah... Graaah...",
  ui_story_5043_50430301_54_dialog_content = "Eclipsites!",
  ui_story_5043_50430301_55_dialog_content = "Oh, really! Servant! Servant!",
  ui_story_5043_50430301_56_dialog_content = "Never mind. It's been ages since I gave the Divine Hand a workout.",
  ui_story_5043_50430301_57_dialog_content = "I'll clean up this filth myself.",
  ui_story_5043_50430301_58_dialog_content = "Isn't this your own house? You're acting like these are just a couple of cockroaches!",
  ui_story_5043_50430302_1_dialog_content = "What a thrilling fight... *Yawns*",
  ui_story_5043_50430302_2_dialog_content = "I hadn't noticed before, but are you left-handed?",
  ui_story_5043_50430302_3_dialog_content = "Haha. Yes, I am. I was trained this way to handle the power of the Divine Hand.",
  ui_story_5043_50430302_4_dialog_content = "But I always feel so tired after a fight...",
  ui_story_5043_50430302_5_dialog_content = "If you're going to bed now, then we're leaving.",
  ui_story_5043_50430302_6_dialog_content = "Bed? No! I'm full of energy.",
  ui_story_5043_50430302_7_dialog_content = "Let's get back to business. I need you all to help me with Operation Accimeet.",
  ui_story_5043_50430302_8_dialog_content = "Okay, but... how?",
  ui_story_5043_50430302_9_dialog_content = "Well... To be honest, I've never pursued anyone before. That's why I need your help.",
  ui_story_5043_50430302_10_dialog_content = "What do I need to do?",
  ui_story_5043_50430302_11_dialog_content = "Let me think... I read once in a book that the first step to change is to acknowledge your own shortcomings.",
  ui_story_5043_50430302_12_dialog_content = "I think the best way to win his heart is—<color=#FFB400> to confess your love</color>.",
  ui_story_5043_50430302_13_dialog_content = "Go somewhere he's likely to show up and wait for him.",
  ui_story_5043_50430302_14_dialog_content = "And when he turns up, you strike! Surprise him!",
  ui_story_5043_50430302_15_dialog_content = "Oh. I see...",
  ui_story_5043_50430302_16_dialog_content = "Wrong again, commoner. Tina can't rely solely on taking the initiative. She also needs to learn <color=#FFB400>the art of concealment</color>.",
  ui_story_5043_50430302_17_dialog_content = "She needs to hide her true feelings. He cannot be allowed to see how anxious she is.",
  ui_story_5043_50430302_18_dialog_content = "If you have the courage to approach him yet are too nervous to look him in the eyes, just pretend to be shy.",
  ui_story_5043_50430302_19_dialog_content = "Oh, I see! I understand.",
  ui_story_5043_50430302_20_dialog_content = "And also—<color=#FFB400>reconnaissance</color>.",
  ui_story_5043_50430302_21_dialog_content = "You have to watch his attitude while discussing apparently innocuous topics.",
  ui_story_5043_50430302_22_dialog_content = "You'll be able to figure out his true feelings in two or three conversations.",
  ui_story_5043_50430302_23_dialog_content = "That sounds difficult. But I'll do my best...",
  ui_story_5043_50430302_24_dialog_content = "After careful consideration, I think it's best to just <color=#FFB400>be honest</color>.",
  ui_story_5043_50430302_25_dialog_content = "Over the course of a relationship, all your habits and flaws will be exposed to the other person.",
  ui_story_5043_50430302_26_dialog_content = "You won't be able to cover those up forever. So, honesty is the most important thing.",
  ui_story_5043_50430302_27_dialog_content = "You're right! Though I hope we can even get to that stage...",
  ui_story_5043_50430302_28_dialog_content = "Thanks, everyone! I'll remember all your advice.",
  ui_story_5043_50430302_29_dialog_content = "By the way... are you guys speaking from experience?",
  ui_story_5043_50430302_30_dialog_content = "Ahem...",
  ui_story_5043_50430302_31_dialog_content = "I'm afraid I don't have any practical experience, no...",
  ui_story_5043_50430302_32_dialog_content = "I-I didn't mean to criticize anyone. It's just... I guess I'll just need to try it myself.",
  ui_story_5043_50430302_33_dialog_content = "But where can I find him?",
  ui_story_5043_50430302_34_dialog_content = "If it's him, then most likely somewhere busy, somewhere full of people.",
  ui_story_5043_50430302_35_dialog_content = "Oh. Okay...",
  ui_story_5043_50430302_36_dialog_content = "Speaking of busy places, there's an obvious choice.",
  ui_story_5043_50430302_37_dialog_content = "That place where nobles and commoners alike congregate. Directly under the \"moon.\"",
  ui_story_5043_50430302_38_dialog_content = "W-Why!?",
  ui_story_5043_50430302_39_dialog_content = "I heard some news about the \"moon\" earlier. I think we should go and investigate.",
  ui_story_5043_50430302_40_dialog_content = "You just want to go and see it.",
  ui_story_5043_50430302_41_dialog_content = "Never mind him, I'm curious too. Let's go now!",
  ui_story_5043_50430302_42_dialog_content = "Oh no. Wait a minute!",
  ui_story_5043_50430302_43_dialog_content = "I want to wear the <color=#FFB400>gloves</color> I wore when we first met and held hands.",
  ui_story_5043_50430302_44_dialog_content = "And I have to take the cookies I made for him too.",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Residential District</color>",
  ui_story_5043_50430401_2_dialog_content = "So, this hot air balloon that looks like a moon has been floating around up there for days?",
  ui_story_5043_50430401_3_dialog_content = "I hadn't even noticed it...",
  ui_story_5043_50430401_4_dialog_content = "I guess I hadn't imagined there would be anything up there, except Lumopolis Gardens and the sun.",
  ui_story_5043_50430401_5_dialog_content = "It's quite normal for you to miss it. Commoners such as you would never think to raise their heads and appreciate the beauty of the skies.",
  ui_story_5043_50430401_6_dialog_content = "Hey, say that again!",
  ui_story_5043_50430401_7_dialog_content = "Okay, okay. More walking, less fighting, please.",
  ui_story_5043_50430401_8_dialog_content = "I remember when I was a little girl, my mother took me to the Stairway to the Skies and said that was the only place we could see stars.",
  ui_story_5043_50430401_9_dialog_content = "With each step, you see one star. Go up all the steps, you see a thousand.",
  ui_story_5043_50430401_10_dialog_content = "I was so excited! I ran all the way to the top.",
  ui_story_5043_50430401_11_dialog_content = "How many stars did you see?",
  ui_story_5043_50430401_12_dialog_content = "None. Just the sun. It was midday.",
  ui_story_5043_50430401_13_dialog_content = "You could've at least waited until evening!",
  ui_story_5043_50430401_14_dialog_content = "But that's when I sleep...",
  ui_story_5043_50430401_15_dialog_content = "...",
  ui_story_5043_50430401_16_dialog_content = "By the way Matthieu, what did you hear about the \"moon\"?",
  ui_story_5043_50430401_17_dialog_content = "Oh, it's just some event cooked up by those Mooncrown Day enthusiasts.",
  ui_story_5043_50430401_18_dialog_content = "They send a hot air balloon that looks like the moon up into the sky over Lumopolis, to announce the reign of free love.",
  ui_story_5043_50430401_19_dialog_content = "And when the balloon goes up, everyone knows to gather underneath it for an impromptu salon.",
  ui_story_5043_50430401_20_dialog_content = "All the trend-following nobles love it.",
  ui_story_5043_50430401_21_dialog_content = "I see. I remember Carleen saying something about the Mooncrown Day enthusiasts.",
  ui_story_5043_50430401_22_dialog_content = "So that's why they use a balloon that looks like the moon... because it's Mooncrown Day.",
  ui_story_5043_50430401_23_dialog_content = "How clever you nobles are.",
  ui_story_5043_50430401_24_dialog_content = "I think it makes sense because the moon and love are both pure and beautiful things.",
  ui_story_5043_50430401_25_dialog_content = "I'm sure that's what whoever planned these events was thinking.",
  ui_story_5043_50430401_26_dialog_content = "What a thing to say. Is this what girls are like when they're in love?",
  ui_story_5043_50430401_27_dialog_content = "I said I'm not in love! Whatever, just stop teasing me, okay?",
  ui_story_5043_50430401_28_dialog_content = "Anyway, it looks like the balloon is over Lumopolis Courtyard, so that must be where the party will be.",
  ui_story_5043_50430401_29_dialog_content = "Ugh. How come we've got to walk even further? When are the Guardians going to put carriages on the Stairway to the Skies?",
  ui_story_5043_50430401_30_dialog_content = "Not everyone can afford to take carriages, you know.",
  ui_story_5043_50430401_31_dialog_content = "The Stairway to the Skies is the main route from Lumopolis Courtyard to Lumopolis Gardens.",
  ui_story_5043_50430401_32_dialog_content = "Are you ready to dive into the world of the commoners, Matthieu?",
  ui_story_5043_50430401_33_dialog_content = "Oh, shush!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>Lumopolis Courtyard, Meadow Square</color>",
  ui_story_5043_50430401_35_dialog_content = "Wow—",
  ui_story_5043_50430401_36_dialog_content = "I didn't know Lumopolis Courtyard had such a lovely green space. It's gorgeous.",
  ui_story_5043_50430401_37_dialog_content = "I think it was just built this spring. They use Luminatics to maintain it.",
  ui_story_5043_50430401_38_dialog_content = "Hey, do you hear that?",
  ui_story_5043_50430401_39_dialog_content = "It sounds like they're playing music in the middle of the square, right under the balloon.",
  ui_story_5043_50430401_39X1_dialog_content = "According to what I heard, there are three parts to the salon: a gathering, a dance, and a poetry appreciation session.",
  ui_story_5043_50430401_40_dialog_content = "Mm... pretty standard dance music. Surprisingly acceptable taste.",
  ui_story_5043_50430401_40X1_dialog_content = "Youngsters, is this your first time attending the Moonlight Salon?",
  ui_story_5043_50430401_40X2_dialog_content = "Don't just stand around! Come, come!",
  ui_story_5043_50430401_40X3_dialog_content = "Hey! Wait, don't pull me... Gosh, I can't stand this!",
  ui_story_5043_50430401_41_dialog_content = "We must have arrived in time for the dancing!",
  ui_story_5043_50430401_42_dialog_content = "It's impolite to just stand to one side with your back against the wall. Let's join them and observe the crowd as we do!",
  ui_story_5043_50430401_43_dialog_content = "B-But... I don't know a thing about noble dances or customs!",
  ui_story_5043_50430401_44_dialog_content = "And I have two left feet.",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5043_50430401_46_dialog_content = "So... Why am I the one stuck dancing with the commoner? I feel sick!",
  ui_story_5043_50430401_47_dialog_content = "You think I'm enjoying this?!",
  ui_story_5043_50430401_48_dialog_content = "Ow!",
  ui_story_5043_50430401_49_dialog_content = "Watch where you're putting your feet, you fool—ouch!",
  ui_story_5043_50430401_50_dialog_content = "You're doing that deliberately!",
  ui_story_5043_50430401_51_dialog_content = "Hey, what are you doing!?",
  ui_story_5043_50430401_52_dialog_content = "Stop it! Don't pull my hair!",
  ui_story_5043_50430401_53_dialog_content = "Hahaha! They look like they're having fun.",
  ui_story_5043_50430401_54_dialog_content = "PlayerName, are you nervous?",
  ui_story_5043_50430401_55_dialog_content = "No, no, I'm fine.",
  ui_story_5043_50430401_56_dialog_content = "Go left, raise my foot, back to the right, turn...",
  ui_story_5043_50430401_57_dialog_content = "H-H-H-How did my hand hit you!?",
  ui_story_5043_50430401_58_dialog_content = "Don't worry, it's just a friendly dance.",
  ui_story_5043_50430401_59_dialog_content = "Why don't we try that again?",
  ui_story_5043_50430401_60_dialog_content = "Okay. I'll do better this time.",
  ui_story_5043_50430401_61_dialog_content = "Haha. See, you can do it.",
  ui_story_5043_50430401_62_dialog_content = "You're a quick learner.",
  ui_story_5043_50430401_63_dialog_content = "Phew! Dancing is a real workout.",
  ui_story_5043_50430401_64_dialog_content = "I so do not want to do this again...",
  ui_story_5043_50430401_65_dialog_content = "Tch, if I weren't so kind, I'd be suing you.",
  ui_story_5043_50430401_66_dialog_content = "Where did Loewe disappear to?",
  ui_story_5043_50430401_67_dialog_content = "Looks like I missed all the fun.",
  ui_story_5043_50430401_68_dialog_content = "I spotted some suspicious characters outside earlier. Definitely weren't salon participants.",
  ui_story_5043_50430401_69_dialog_content = "I went over to investigate and ran into Lady Carleen.",
  ui_story_5043_50430401_70_dialog_content = "Thanks for showing me the way. And those suspicious characters are with me, actually.",
  ui_story_5043_50430401_71_dialog_content = "Wow! Lady Carleen, you came too!",
  ui_story_5043_50430401_72_dialog_content = "What's the latest, Carleen? Any progress on the Eclipsite incursion?",
  ui_story_5043_50430401_73_dialog_content = "No, but I have eliminated a few possibilities.",
  ui_story_5043_50430401_74_dialog_content = "The travel passes are all in order, so they couldn't have been sneaking into Lumopolis in disguise.",
  ui_story_5043_50430401_75_dialog_content = "The Nightwatch has been doing its job and there aren't any holes in the shield over Lumopolis.",
  ui_story_5043_50430401_76_dialog_content = "There's been more movement of goods and mercenaries lately, because of all the festivals.",
  ui_story_5043_50430401_77_dialog_content = "So it's possible that the guards haven't been searching goods shipments properly and the Eclipsites have been sneaking in that way.",
  ui_story_5043_50430401_78_dialog_content = "Huh? You're searching for infiltrating Eclipsites?",
  ui_story_5043_50430401_79_dialog_content = "In that case... I have to find him as soon as possible.",
  ui_story_5043_50430401_80_dialog_content = "I don't think you need to worry about him. I'm sure he's perfectly safe.",
  ui_story_5043_50430401_81_dialog_content = "R-Really...?",
  ui_story_5043_50430401_82_dialog_content = "(Tina's worrying seems really strange...)",
  ui_story_5043_50430401_83_dialog_content = "Well, the head Eclipsite must know some kind of <color=#FFB400>camouflage skill</color> to be able to blend in with the crowd.",
  ui_story_5043_50430401_84_dialog_content = "I haven't authorized a full search as I don't want to cause panic.",
  ui_story_5043_50430401_85_dialog_content = "I've just put some guards in plain clothes and told them to watch any busy areas, just in case.",
  ui_story_5043_50430401_86_dialog_content = "You know, Carleen, that sounds a lot like what the City Lord is doing with the Mooncrown Day cases.",
  ui_story_5043_50430401_87_dialog_content = "... I don't regard that as a compliment.",
  ui_story_5043_50430401_88_dialog_content = "Erm... Sorry. How about I apologize by helping out a bit?",
  ui_story_5043_50430401_89_dialog_content = "I could at least confirm that there aren't any Eclipsites in the crowd here..",
  ui_story_5043_50430401_90_option_content = "Force Boost",
  ui_story_5043_50430401_91_dialog_content = "Thanks, PlayerName.",
  ui_story_5043_50430401_92_dialog_content = "Well? Anything unusual?",
  ui_story_5043_50430401_93_dialog_content = "Uh...",
  ui_story_5043_50430401_94_dialog_content = "Sorry. It's too busy and noisy here. It's not working.",
  ui_story_5043_50430401_95_dialog_content = "Lady Carleen! PlayerName! Hey!",
  ui_story_5043_50430401_96_dialog_content = "Don't just stand there. Get over here!",
  ui_story_5043_50430401_97_dialog_content = "Since I'm already here... let's go see what's happening.",
  ui_story_5043_50430401_98_dialog_content = "That balloon really is impressive up close.",
  ui_story_5043_50430401_99_dialog_content = "Lady Carleen, do you think so too?",
  ui_story_5043_50430401_100_dialog_content = "Spring meadows, loving couples, a choir singing in the background...",
  ui_story_5043_50430401_101_dialog_content = "And under a rarely-seen moon, everyone proceeds up the steps as they exchange intellectual thoughts, regardless of their classes...",
  ui_story_5043_50430401_102_dialog_content = "Why, it's like something out of a fairytale.",
  ui_story_5043_50430401_103_dialog_content = "Intellectual thoughts, my ass. This is just a sappy love fest for dating couples.",
  ui_story_5043_50430401_104_dialog_content = "And I've never seen so many commoners in one place before. The place stinks of Lower Lumopolis. Yuck.",
  ui_story_5043_50430401_105_dialog_content = "Well, it's too late now.",
  ui_story_5043_50430401_106_dialog_content = "Hey, commoner. What are you staring at?",
  ui_story_5043_50430401_107_dialog_content = "I was just thinking... that moon balloon is a little odd.",
  ui_story_5043_50430401_108_dialog_content = "It isn't tethered to the ground yet stays in one place. I wonder if they're controlling it with Luminatics.",
  ui_story_5043_50430401_109_dialog_content = "Never mind. Just the foolish concerns of an ordinary commoner. Why even bother asking what I think?",
  ui_story_5043_50430401_110_dialog_content = "You're correct, sir. And what's more...",
  ui_story_5043_50430401_111_dialog_content = "The Luminatics is also maintaining the <color=#FFB400>gifts from ancient festivals</color> inside the balloon.",
  ui_story_5043_50430401_112_dialog_content = "Sorry, you are...?",
  ui_story_5043_50430401_113_dialog_content = "Oh, just a nun from Lumopolis. You can just call me Sister.",
  ui_story_5043_50430401_114_dialog_content = "I'm the organizer of these Moonlight Salons.",
  ui_story_5043_50430401_115_dialog_content = "And I don't believe I've ever seen you here before. I hope you're enjoying yourself.",
  ui_story_5043_50430401_116_dialog_content = "W-Well I haven't been here long. It all seems very exciting.",
  ui_story_5043_50430401_117_dialog_content = "It doesn't feel anything like the Lumopolis I know.",
  ui_story_5043_50430401_118_dialog_content = "Heheh. Thank you, and may the God of Light bless you. I'll leave you to enjoy yourselves.",
  ui_story_5043_50430401_119_dialog_content = "Please do help yourselves to the tea and desserts. And don't forget to enjoy the choir.",
  ui_story_5043_50430401_120_dialog_content = "(That choir... please don't tell me...)",
  ui_story_5043_50430401_121_dialog_content = "So you've come to the party by the moon. ♪",
  ui_story_5043_50430401_122_dialog_content = "But it is a balloon. ♪",
  ui_story_5043_50430401_123_dialog_content = "We see you wander and mingle. ♪",
  ui_story_5043_50430401_124_dialog_content = "Are you still single? Still single? ♪",
  ui_story_5043_50430401_125_dialog_content = "See? Such cute children.",
  ui_story_5043_50430401_126_dialog_content = "Cute? As if!",
  ui_story_5043_50430401_127_dialog_content = "Give it a jab! Fatty goes pop! ♪",
  ui_story_5043_50430401_128_dialog_content = "Hanging up there, high on top! ♪",
  ui_story_5043_50430401_129_dialog_content = "What is it that pops so soon? ♪",
  ui_story_5043_50430401_130_dialog_content = "Maybe a noble, maybe a balloon. ♪",
  ui_story_5043_50430401_131_dialog_content = "Ah, they got the Dawn Academy choir to sing for them, huh?",
  ui_story_5043_50430401_132_dialog_content = "I see they're sticking to their usual style.",
  ui_story_5043_50430401_133_dialog_content = "Men and women flirt under the moonlight. ♪",
  ui_story_5043_50430401_134_dialog_content = "Nobles and commoners share a table and don't fight. ♪",
  ui_story_5043_50430401_135_dialog_content = "Oh honorable nun, lovely nun! ♪",
  ui_story_5043_50430401_136_dialog_content = "Your salons sure are fun! ♪",
  ui_story_5043_50430401_137_dialog_content = "I'm not sure their lyrics make much sense, but they're good singers...",
  ui_story_5043_50430401_138_dialog_content = "Listening to a choir always makes me want to pray.",
  ui_story_5043_50430401_139_dialog_content = "White Night up high, oh, God of Light, please allow me to find him.",
  ui_story_5043_50430401_140_dialog_content = "I'm not entirely sure the God of Light is in charge of such matters...",
  ui_story_5043_50430401_141_dialog_content = "All in Lumopolis can praise the God of Light. ♪",
  ui_story_5043_50430401_142_dialog_content = "But a noble wed a commoner? That's not right! ♪",
  ui_story_5043_50430401_143_dialog_content = "Oh honorable nun, poor nun! ♪",
  ui_story_5043_50430401_144_dialog_content = "Disaster's coming. You! Should! Run! ♪",
  ui_story_5043_50430401_145_dialog_content = "Wait, what?!",
  ui_story_5043_50430401_146_dialog_content = "Clear the area! I want everyone attending this illegal gathering arrested.",
  ui_story_5043_50430401_147_dialog_content = "And bring me the organizer!",
  ui_story_5043_50430401_148_dialog_content = "Eek!",
  ui_story_5043_50430401_149_dialog_content = "The Guardians from Lumopolis Gardens! Run!",
  ui_story_5043_50430401_150_dialog_content = "I-I'm a noble from Uptown. They wouldn't dare...",
  ui_story_5043_50430401_151_dialog_content = "Ehhhh!?",
  ui_story_5043_50430401_152_dialog_content = "Ah! My <color=#FFB400>cookies</color>!",
  ui_story_5043_50430401_153_dialog_content = "I <color=#FFB400>lost</color> the cookies I was going to give him!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>*Crowd mumbling*</color>",
  ui_story_5043_50430401_155_dialog_content = "(This can't be. These aren't my guards!)",
  ui_story_5043_50430401_156_dialog_content = "I gave no such orders! Who dares...",
  ui_story_5043_50430401_157_dialog_content = "Captain Carleen!",
  ui_story_5043_50430401_158_dialog_content = "They're not Guardians from Lumopolis Gardens.",
  ui_story_5043_50430401_159_dialog_content = "But few other nobles have such forces.",
  ui_story_5043_50430401_160_dialog_content = "The partygoers will assume this raid has been ordered by Lumopolis Gardens!",
  ui_story_5043_50430401_161_dialog_content = "I see what you're saying. But we need to restore order first.",
  ui_story_5043_50430401_162_dialog_content = "Please, don't panic. Follow me!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>Smash—!</color>",
  ui_story_5043_50430401_164_dialog_content = "(What was that noise?!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerName, Whirling Paladin, I need your help.",
  ui_story_5043_50430401_166_dialog_content = "Join forces with my plain-clothes guards and tackle these soldiers, whoever they are!",
  ui_story_5043_50430401_167_dialog_content = "Happy to help!",
  ui_story_5043_50430401_168_dialog_content = "As you wish!",
  ui_story_5043_50430501_1_dialog_content = "Those guards sure run fast!",
  ui_story_5043_50430501_2_dialog_content = "Captain, should I give chase?",
  ui_story_5043_50430501_3_dialog_content = "Don't bother. You've got other work to do.",
  ui_story_5043_50430501_4_dialog_content = "It's a pity, though. The Moonlight Salon is ruined and we didn't find who we were looking for.",
  ui_story_5043_50430501_5_dialog_content = "Oh? Who were you looking for?",
  ui_story_5043_50430501_6_dialog_content = "Tina wanted to find Schwab and give him something in return for his Mooncrown Day gift.",
  ui_story_5043_50430501_7_dialog_content = "Oh, I didn't know the two of them had this kind of relationship.",
  ui_story_5043_50430501_8_dialog_content = "So that's the power of Mooncrown Day. Young folk falling in love without their families making prior arrangements.",
  ui_story_5043_50430501_9_dialog_content = "But... If I can be frank, what does she see in that playboy?",
  ui_story_5043_50430501_10_dialog_content = "I know, right...?",
  ui_story_5043_50430501_11_dialog_content = "Hey, has anyone seen Loewe?",
  ui_story_5043_50430501_12_dialog_content = "I haven't seen him since those guards fled.",
  ui_story_5043_50430501_13_dialog_content = "I sent him off to find out where they came from. You should carry on investigating your case.",
  ui_story_5043_50430501_14_dialog_content = "I've got a very good idea of what happened already. But it's best to make sure.",
  ui_story_5043_50430501_15_dialog_content = "T-This is not good.",
  ui_story_5043_50430501_16_dialog_content = "I know, I know. Your cookies have gone missing, right?",
  ui_story_5043_50430501_17_dialog_content = "Let's look for them. They're probably mixed up with all these messes.",
  ui_story_5043_50430501_18_dialog_content = "Oh, I wish that was the only problem!",
  ui_story_5043_50430501_19_dialog_content = "It's the statue at the entrance to the square. It's...",
  ui_story_5043_50430501_20_dialog_content = "It got <color=#FFB400>broken</color> during all the chaos.",
  ui_story_5043_50430501_21_dialog_content = "What!?",
  ui_story_5043_50430501_22_dialog_content = "I heard something breaking while everyone was rushing about.",
  ui_story_5043_50430501_23_dialog_content = "The weird thing is, it broke in exactly the same way the one at the Hall of Justice did.",
  ui_story_5043_50430501_24_dialog_content = "It's like there are statue decapitators at work.",
  ui_story_5043_50430501_25_dialog_content = "Hmm... I think we should go and report to our temporary chief judge then.",
  ui_story_5043_50430501_26_dialog_content = "Yeah. And if he's not here at the Moonlight Salon, then he must be—",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Schwab's Office</color>",
  ui_story_5043_50430501_28_dialog_content = "Mmm... Okay, I've got it.",
  ui_story_5043_50430501_29_dialog_content = "I'm glad you came back. I need you to put the statue case aside for now, until the plaintiff updates their request.",
  ui_story_5043_50430501_30_dialog_content = "We've got a new romance case about to start. So get ready, my darling subordinates.",
  ui_story_5043_50430501_31_dialog_content = "Just like that?",
  ui_story_5043_50430501_32_dialog_content = "This is life in the Romance Division. Moving constantly forwards, like a Luminatics-powered carriage.",
  ui_story_5043_50430501_33_dialog_content = "It's very hard for you to understand, my little dandelion, as you aren't the chief judge.",
  ui_story_5043_50430501_34_dialog_content = "L-Little dandelion???",
  ui_story_5043_50430501_35_dialog_content = "(Did he just call me little dandelion? How nauseating.)",
  ui_story_5043_50430501_36_dialog_content = "You'll get used to it, PlayerName...",
  ui_story_5043_50430501_37_dialog_content = "Actually, Chief Judge Schwab, Tina has something she wants to—",
  ui_story_5043_50430501_38_dialog_content = "I'm not sure this is the best time for that.",
  ui_story_5043_50430501_39_dialog_content = "(Yeah. What's Leyn doing? I don't have anything to say to Schwab.)",
  ui_story_5043_50430501_40_dialog_content = "Hmm? Looks like my subordinates are working so well together that they even have little secrets from me.",
  ui_story_5043_50430501_41_dialog_content = "Anyway, here's the indictment and all the paperwork. It's all very straightforward. See you in court!",
  ui_story_5043_50430501_42_dialog_content = "He's right, it does look easy. And it's to do with that Moonlight Salon we were at...",
  ui_story_5043_50430501_43_dialog_content = "Huh? Hang on a minute! Everyone, look at the reason for the case!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>Hall of Justice, Romance Division</color>",
  ui_story_5043_50430501_45_dialog_content = "The City Lord doesn't do things by halves. Look at the size of this place!",
  ui_story_5043_50430501_46_dialog_content = "And given the number of cases we're handling on our first day, he's also getting good value for money.",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50430501_48_dialog_content = "Court is in session!",
  ui_story_5043_50430501_49_dialog_content = "First, let us introduce the parties involved in today's litigation!",
  ui_story_5043_50430501_50_dialog_content = "The plaintiff is... a male from Lower Lumopolis, who cannot be named for reasons of privacy.",
  ui_story_5043_50430501_51_dialog_content = "The defendant is... a female from Lower Lumopolis, who cannot be named for reasons of privacy.",
  ui_story_5043_50430501_52_dialog_content = "(I didn't hear any of that!)",
  ui_story_5043_50430501_53_dialog_content = "I, Schwab Salar, shall preside as the chief judge in today's trial.",
  ui_story_5043_50430501_54_dialog_content = "The judicial panel consists of Matthieu Sawyer, Tina Campbell, and Leyn...",
  ui_story_5043_50430501_55_dialog_content = "As well as several other members of the court.",
  ui_story_5043_50430501_56_dialog_content = "(Wow! Schwab actually seems kind of competent when he puts his mind to it...)",
  ui_story_5043_50430501_57_dialog_content = "If nobody has any objections to any of that, we can proceed.",
  ui_story_5043_50430501_58_dialog_content = "Hang on. How come we're all just \"several other members of the court\"?",
  ui_story_5043_50430501_59_dialog_content = "No objections? Very good, let us begin.",
  ui_story_5043_50430501_60_dialog_content = "If the plaintiff could recount the facts of the case for us?",
  ui_story_5043_50430501_61_dialog_content = "*Sobbing* This is what happened...",
  ui_story_5043_50430501_62_dialog_content = "My fiancee—the defendant—and I went to Meadow Square in Lumopolis Courtyard for the Moonlight Salon...",
  ui_story_5043_50430501_63_dialog_content = "B-But she...",
  ui_story_5043_50430501_64_dialog_content = "Please don't cry. Just tell us what happened.",
  ui_story_5043_50430501_65_dialog_content = "I love her so much. We've been together for four years! She likes to have coffee with chocolate and—",
  ui_story_5043_50430501_66_dialog_content = "If you could stick to the relevant matters, please.",
  ui_story_5043_50430501_67_dialog_content = "S-Sorry. Oh, I always make such a mess of everything...",
  ui_story_5043_50430501_68_dialog_content = "We went to the Moonlight Salon and had such a good time. But then she got angry all of a sudden and said she wanted to break up with me!",
  ui_story_5043_50430501_69_dialog_content = "I mean... What would I tell my family? *Sobbing*",
  ui_story_5043_50430501_70_dialog_content = "Very well. Next, the defendant.",
  ui_story_5043_50430501_71_dialog_content = "I had my reasons.",
  ui_story_5043_50430501_72_dialog_content = "This man, the plaintiff, took me out on a date.",
  ui_story_5043_50430501_73_dialog_content = "Yet dared accept a gift from another!",
  ui_story_5043_50430501_74_dialog_content = "(She's acting like she's the plaintiff.)",
  ui_story_5043_50430501_75_dialog_content = "I-I didn't...",
  ui_story_5043_50430501_76_dialog_content = "Then can you explain where that basket of <color=#FFB400>cookies</color> came from?",
  ui_story_5043_50430501_77_dialog_content = "(Cookies? Are those...)",
  ui_story_5043_50430501_78_dialog_content = "There! That's the evidence!",
  ui_story_5043_50430501_79_dialog_content = "You put them on your chair. And there's a card.",
  ui_story_5043_50430501_80_dialog_content = "And it gets worse. Whoever wrote the card uses the same <color=#FFB400>pet name</color> for you that I do!",
  ui_story_5043_50430501_81_dialog_content = "Oh, I'm done for.",
  ui_story_5043_50430501_82_dialog_content = "We were right. These two found the cookies that Tina had lost.",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5043_50430501_84_dialog_content = "Order!",
  ui_story_5043_50430501_85_dialog_content = "Any citizen of Lumopolis found in contempt of court will be sentenced to death... Kidding!",
  ui_story_5043_50430501_86_dialog_content = "<size=32>Hey, Tina. Is that the basket of cookies you lost?</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>Eh? Is that PlayerName?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>You can't talk to me when the court is in session!</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>In that case...</size>",
  ui_story_5043_50430501_90_option_content = "Force Boost!",
  ui_story_5043_50430501_91_dialog_content = "Oh wow! Is this your Caelestite ability? I've always wondered about it.",
  ui_story_5043_50430501_92_dialog_content = "Never mind that now. So those are your cookies, right?",
  ui_story_5043_50430501_93_dialog_content = "Yes, they're mine! I can't believe I've caused these innocent people so much trouble...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName, what do you think I should do?",
  ui_story_5043_50430501_95_option_content = "Be honest",
  ui_story_5043_50430501_96_dialog_content = "I think you should admit what happened. The cookies are yours but were meant to be given to someone else.",
  ui_story_5043_50430501_97_dialog_content = "But I guess this isn't the best time for Schwab to hear the truth.",
  ui_story_5043_50430501_98_dialog_content = "So I'd understand if you weren't too keen on the idea.",
  ui_story_5043_50430501_99_dialog_content = "Huh? Schwab? Hear what truth?",
  ui_story_5043_50430501_100_option_content = "Wait and see",
  ui_story_5043_50430501_101_dialog_content = "I think you should wait and see how things turn out.",
  ui_story_5043_50430501_102_dialog_content = "If you start talking now, you'll risk being found in contempt of court.",
  ui_story_5043_50430501_103_dialog_content = "So what will the court do next?",
  ui_story_5043_50430501_104_dialog_content = "Next we hear arguments from both sides.",
  ui_story_5043_50430501_105_dialog_content = "I'm not sure why PlayerName is so interested. But I'll just let Schwab continue with the case.",
  ui_story_5043_50430501_106_dialog_content = "As both plaintiff and defendant seem so keen to continue, we will now hear further arguments.",
  ui_story_5043_50430501_107_dialog_content = "<size=32>Listen up, commoner! This isn't the way to go about things.</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>We need to do something. But we can't embarrass Tina.</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>I agree. But we don't know what Tina wants to do.</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>She isn't speaking up for herself. So... what if we help Schwab figure it out for himself?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>Not bad, kid! Good idea.</size>",
  ui_story_5043_50430501_112_dialog_content = "The judges will now please commence with cross-examinations.",
  ui_story_5043_50430501_113_dialog_content = "Ahem. Plaintiff, you say this basket of cookies is not yours. Could you tell us who it does belong to?",
  ui_story_5043_50430501_114_dialog_content = "I... I have no idea. It just suddenly appeared on the table in front of me.",
  ui_story_5043_50430501_115_dialog_content = "I can only assume <color=#FFB400>someone left it there</color>.",
  ui_story_5043_50430501_116_dialog_content = "So you would say someone attending the Moonlight Salon lost the basket of cookies?",
  ui_story_5043_50430501_117_dialog_content = "And I'm sure we can all imagine what it was intended for.",
  ui_story_5043_50430501_118_dialog_content = "Yes. I mean, it must have been intended as a <color=#FFB400>gift</color>.",
  ui_story_5043_50430501_119_dialog_content = "But not a gift for me. I have nothing to do with it.",
  ui_story_5043_50430501_120_dialog_content = "Then I would like to ask the defendant, why are you so sure that your lover has been disloyal?",
  ui_story_5043_50430501_121_dialog_content = "Surely it's obvious. Anyone can see that basket of cookies was a gift from a <color=#FFB400>woman</color>.",
  ui_story_5043_50430501_122_dialog_content = "He wouldn't dare accept such a gift unless he was planning to break up with me.",
  ui_story_5043_50430501_123_dialog_content = "And here is the heart of the matter. The plaintiff insists he did not accept any gift. You believe he did.",
  ui_story_5043_50430501_124_dialog_content = "But the message on the <color=#FFB400>card</color> is clearly from a lover...",
  ui_story_5043_50430501_125_dialog_content = "Oh, okay. Maybe I was too hasty. But then, who were the cookies intended for?",
  ui_story_5043_50430501_126_dialog_content = "That is the crucial question!",
  ui_story_5043_50430501_127_dialog_content = "And the intended recipient is right here!",
  ui_story_5043_50430501_128_dialog_content = "Right here...?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5043_50430501_130_dialog_content = "Judge Leyn, Judge Matthieu, please do not make statements of a leading nature to the defendant.",
  ui_story_5043_50430501_131_dialog_content = "This is a court. Guilty means guilty.",
  ui_story_5043_50430501_132_dialog_content = "Oh, but Chief Judge Schwab... You are so handsome, so popular with the ladies. How can you bear to interrupt such a fair maid?",
  ui_story_5043_50430501_133_dialog_content = "And proof of a lady's love for you lies here but you fail to realize who that lady is.",
  ui_story_5043_50430501_134_dialog_content = "Oh! I think I understand. You mean the cookies were actually intended for—",
  ui_story_5043_50430501_135_dialog_content = "Huh?",
  ui_story_5043_50430501_136_dialog_content = "Order!",
  ui_story_5043_50430501_137_dialog_content = "Silence in the court! I wish to speak.",
  ui_story_5043_50430501_138_dialog_content = "Judge Tina, you cannot interrupt the court's business like this!",
  ui_story_5043_50430501_139_dialog_content = "Chief Judge Schwab, as the owner of the evidence-cookies, I wish to make a <color=#FFB400>witness statement</color>.",
  ui_story_5043_50430501_140_dialog_content = "(Attagirl, Tina! That's the spirit!)",
  ui_story_5043_50430501_141_dialog_content = "O-Okay. The court agrees. You may speak, witness.",
  ui_story_5043_50430501_142_dialog_content = "I made the cookies.",
  ui_story_5043_50430501_143_dialog_content = "I made them myself, with loving hands and a fluttering heart.",
  ui_story_5043_50430501_144_dialog_content = "I whisked the butter. I piped the pretty designs. I baked them until they were golden yellow and picked out the best-looking ones.",
  ui_story_5043_50430501_145_dialog_content = "All so I could give him a perfect gift.",
  ui_story_5043_50430501_146_dialog_content = "But then I lost them all at the Moonlight Salon.",
  ui_story_5043_50430501_147_dialog_content = "And this card is proof!",
  ui_story_5043_50430501_148_dialog_content = "I made that card myself. I can tell you the name on the card and everything written on it.",
  ui_story_5043_50430501_149_dialog_content = "Oh! Really? It's so bizarre that we've met like this...",
  ui_story_5043_50430501_150_dialog_content = "It's like a beautiful love story.",
  ui_story_5043_50430501_151_dialog_content = "I don't know what to do with you, my pretties. You're all such a charming burden for me to bear.",
  ui_story_5043_50430501_152_dialog_content = "Perhaps the witness and the defendant can confirm what's written on the card? Then we can conclude this case.",
  ui_story_5043_50430501_153_dialog_content = "Okay. Let's read it out together.",
  ui_story_5043_50430501_154_dialog_content = "Good idea. Three. Two. One!",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>Toto</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "Ha?",
  ui_story_5043_50430501_156_dialog_content = "What!?",
  ui_story_5043_50430501_157_dialog_content = "Why, Chief Judge Schwab, I've always heard about how famous and fashionable you are.",
  ui_story_5043_50430501_158_dialog_content = "I never imagined you would have such a cute little nickname.",
  ui_story_5043_50430501_159_dialog_content = "It makes you seem a little less intimidating to us folk from Lower Lumopolis.",
  ui_story_5043_50430501_160_dialog_content = "Darling, finally I have won back your trust. *Sobbing*",
  ui_story_5043_50430501_161_dialog_content = "Toto. Heehee. Such a cute name.",
  ui_story_5043_50430501_162_dialog_content = "Schwab, is that a childhood nickname? Something your mommy called you?",
  ui_story_5043_50430501_163_dialog_content = "Hahahahaha!",
  ui_story_5043_50430501_164_dialog_content = "But... This...",
  ui_story_5043_50430501_165_dialog_content = "Stop! What exactly is going on!?",
  ui_story_5043_50430501_166_dialog_content = "Yes, what's going on?",
  ui_story_5043_50430501_167_dialog_content = "What do the card and cookies have to do with Chief Judge Schwab?",
  ui_story_5043_50430601_1_dialog_content = "So... I guess that's what happened.",
  ui_story_5043_50430601_2_dialog_content = "I made the cookies for Toto. But it seems the defendant got the wrong idea...",
  ui_story_5043_50430601_3_dialog_content = "I never imagined anything like this would happen. At least we've cleared up the misunderstanding between the two lovers.",
  ui_story_5043_50430601_4_dialog_content = "Ha?",
  ui_story_5043_50430601_5_dialog_content = "They weren't the only ones with a misunderstanding.",
  ui_story_5043_50430601_6_dialog_content = "So who's this Toto? We thought you liked our idiot chief judge!",
  ui_story_5043_50430601_7_dialog_content = "Yeah, though that never made much sense. But where did we go wrong?",
  ui_story_5043_50430601_8_dialog_content = "It's my fault. It's an embarrassing situation so I was being very vague.",
  ui_story_5043_50430601_9_dialog_content = "I should have explained things better before asking you all to help.",
  ui_story_5043_50430601_10_dialog_content = "Although I don't understand how even you got it wrong, Schwab.",
  ui_story_5043_50430601_11_dialog_content = "We've hardly even spoken apart from the normal work and social chat.",
  ui_story_5043_50430601_12_dialog_content = "I mean, it's obvious when someone likes you, right? That's just something people can tell.",
  ui_story_5043_50430601_13_dialog_content = "Enough. Please don't say any more.",
  ui_story_5043_50430601_14_dialog_content = "This is all... irrelevant. The important matter at hand is...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>Everyone in the Hall of Justice thinks my nickname is Toto!!!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>Judge Jr. and those assistant judges on the panel must already have told everyone!!!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>And soon every noble in Lumopolis Gardens society will have heard the news!!!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>And it's all because of you and those stupid cookies and that stupid card!!!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>You're a bunch of love-addled morons! And clingy troublesome women...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>You're all the same!</size>",
  ui_story_5043_50430601_21_dialog_content = "I-I'm so very sorry!",
  ui_story_5043_50430601_22_dialog_content = "Hey. Tina might have made a mistake. But you're being too harsh on her, Schwab.",
  ui_story_5043_50430601_23_dialog_content = "I'm not exactly sure what's been going on. I'm relieved Tina doesn't have a crush on Schwab though.",
  ui_story_5043_50430601_24_dialog_content = "...",
  ui_story_5043_50430601_25_dialog_content = "Sigh...",
  ui_story_5043_50430601_26_dialog_content = "Okay, let's get back to business.",
  ui_story_5043_50430601_27_dialog_content = "The broken statue at Lumopolis Courtyard has nothing to do with Mr. Byron.",
  ui_story_5043_50430601_28_dialog_content = "Which is lucky for you. I don't want to see him turning up with any new indictments.",
  ui_story_5043_50430601_29_dialog_content = "Now go and get ready for the case hearing. Go on, out!",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>Outside the Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430601_31_dialog_content = "Pfft!",
  ui_story_5043_50430601_32_dialog_content = "Hey, did you lot notice Schwab's expression?",
  ui_story_5043_50430601_33_dialog_content = "You were great, Tina. So ruthless!",
  ui_story_5043_50430601_34_dialog_content = "Heheh. I bet he's never had a woman talk to him like that before.",
  ui_story_5043_50430601_35_dialog_content = "Oh, please don't tease me...",
  ui_story_5043_50430601_36_dialog_content = "I'm sorry. I got all of us into trouble.",
  ui_story_5043_50430601_37_dialog_content = "That doesn't matter. But what I want to know is—",
  ui_story_5043_50430601_38_dialog_content = "Tina, you told us you met this man in the garden at Schwab's manor?",
  ui_story_5043_50430601_39_dialog_content = "So if it wasn't Schwab, who was it?",
  ui_story_5043_50430601_40_dialog_content = "Oh, this terrible misunderstanding is all my fault.",
  ui_story_5043_50430601_41_dialog_content = "Let me try and explain it properly...",
  ui_story_5043_50430601_42_dialog_content = "I was in the garden at Salar Manor. And I did run into Schwab. He was sitting by himself, reading and drinking tea.",
  ui_story_5043_50430601_43_dialog_content = "He noticed me right away and was surprised that anyone would turn up in such a secluded spot.",
  ui_story_5043_50430601_44_dialog_content = "But while he noticed me, he failed to see there was another unexpected guest nearby.",
  ui_story_5043_50430601_45_dialog_content = "In the bushes behind Schwab, I saw Toto's furry little head sticking out of the leaves. He was trembling as he gazed at me.",
  ui_story_5043_50430601_46_dialog_content = "I think he was worried I'd give away his hiding place. After all, nobody wants an Eclipsite in their hedge.",
  ui_story_5043_50430601_47_dialog_content = "But he was so cute and he was clearly harmless. The poor thing had got lost in that huge garden.",
  ui_story_5043_50430601_48_dialog_content = "In fact, I'd even seen him brush some flies away from Schwab's teacup. That was before Schwab noticed me.",
  ui_story_5043_50430601_49_dialog_content = "After the Moonlight Salon, I rushed back to the garden. I took his hand and led him safely out of Salar Manor.",
  ui_story_5043_50430601_50_dialog_content = "I had to wear my new gloves to make sure my Lumina and his Darkflow didn't collide.",
  ui_story_5043_50430601_51_dialog_content = "He could understand Universese, although he could only say a few basic words. And on Mooncrown Day, shortly after we met, I received a present from him.",
  ui_story_5043_50430601_52_dialog_content = "That's it. That's the whole story.",
  ui_story_5043_50430601_53_dialog_content = "(Wow. So even an ordinary little Eclipsite has a name...)",
  ui_story_5043_50430601_54_dialog_content = "Hang on. Didn't you say something about him not replying to your letters?",
  ui_story_5043_50430601_55_dialog_content = "Well, he won't have an address in Lumopolis, will he? I wrote back to the return address on the present but never heard anything back.",
  ui_story_5043_50430601_56_dialog_content = "And you said you hadn't had a chance to sneak a meeting with him?",
  ui_story_5043_50430601_57_dialog_content = "Yes. We haven't run into each other at all. I can't find him anywhere.",
  ui_story_5043_50430601_58_dialog_content = "And when you said he gets noticed wherever he goes...",
  ui_story_5043_50430601_59_dialog_content = "Surely you can understand that. An Eclipsite in Lumopolis is bound to cause a panic.",
  ui_story_5043_50430601_60_dialog_content = "So... when you denied you were in love...",
  ui_story_5043_50430601_61_dialog_content = "Eclipsites live to attack Aurorians. Is there such a thing as a harmless Eclipsite?",
  ui_story_5043_50430601_62_dialog_content = "If there is I'd love to see one for myself.",
  ui_story_5043_50430601_63_dialog_content = "I think it's some kind of unnecessary feeling, yes. But it's too weird to call it love.",
  ui_story_5043_50430601_64_dialog_content = "I wouldn't talk about it in romantic terms. I just want to look after him.",
  ui_story_5043_50430601_64X1_dialog_content = "But anyway, I can't stand Eclipsites either.",
  ui_story_5043_50430601_64X2_dialog_content = "*sniff sniff*",
  ui_story_5043_50430601_64X3_dialog_content = "Miss Tina, I'm not trying to alarm anyone, but you seem to have the stench of an Eclipsite about you.",
  ui_story_5043_50430601_64X4_dialog_content = "Huh? You can still smell it after such a long time...? Sorry...",
  ui_story_5043_50430601_65_dialog_content = "As I stated before, the law is the law in Lumopolis. I cannot let this slide.",
  ui_story_5043_50430601_66_dialog_content = "There's no sign of the Eclipsite you mentioned on any of the arrest sheets from the guards.",
  ui_story_5043_50430601_67_dialog_content = "So, should this matter be brought to its conclusion here?",
  ui_story_5043_50430601_68_dialog_content = "Oh. Thank you, Lady Carleen. And as part of the Hall of Justice, I know the stakes.",
  ui_story_5043_50430601_69_dialog_content = "For Aurorians, adopting an Eclipsite is not an uncommon fantasy.",
  ui_story_5043_50430601_69X1_dialog_content = "I'm sorry to have caused everyone such trouble... Let's return to the case and try our best to investigate further.",
  ui_story_5043_50430601_69X2_dialog_content = "It's not as if all you brought was trouble. Didn't something interesting happen as a result of all this?",
  ui_story_5043_50430601_70_dialog_content = "Tina, you... you really played everyone in the Romance Division for fools.",
  ui_story_5043_50430601_71_dialog_content = "Hahahahaha! Right! I definitely made the right decision when I chose to work with you.",
  ui_story_5043_50430601_72_dialog_content = "I certainly did encounter so much more than I had bargained for.",
  ui_story_5043_50430601_74_dialog_content = "Haha. Well, we might not have made much progress with the case, but my cookies definitely caused some entertainment.",
  ui_story_5043_50430601_75_dialog_content = "But! I feel the same way as all of you...",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50430601_77_dialog_content = "Tina!? Tina!",
  ui_story_5043_50430601_78_dialog_content = "What's wrong with her... Hey, don't just stand there, come and help!",
  ui_story_5043_50430601_79_dialog_content = "Phew! Don't worry, she's just fallen asleep.",
  ui_story_5043_50430601_80_dialog_content = "It's been a very exciting day. She must have been exhausted.",
  ui_story_5043_50430601_81_dialog_content = "I'll have one of my servants pick her up in a carriage and take her home.",
  ui_story_5043_50430601_82_dialog_content = "Huff Puff. Lady Carleen...",
  ui_story_5043_50430601_83_dialog_content = "Ah, Loewe. You'll have to do better than this if you want to be a Salar servant.",
  ui_story_5043_50430601_84_dialog_content = "Spit it out!",
  ui_story_5043_50430601_85_dialog_content = "Lady Carleen, you were right.",
  ui_story_5043_50430601_86_dialog_content = "Those guards were all wearing Troy heraldry.",
  ui_story_5043_50430601_87_dialog_content = "And there's something strange about the Moonlight Salon too.",
  ui_story_5043_50430601_88_dialog_content = "What?",
  ui_story_5043_50430601_89_dialog_content = "There's always an Eclipsite attack when one of those salons ends.",
  ui_story_5043_50430601_90_dialog_content = "And the nearby statue's head always goes missing.",
  ui_story_5043_50430601_91_dialog_content = "I'm sorry, that's all I could find out.",
  ui_story_5043_50430601_92_dialog_content = "...",
  ui_story_5043_50430601_93_dialog_content = "You've done great work, Loewe.",
  ui_story_5043_50430601_94_dialog_content = "And you'll be able to rest soon. But not yet!",
  ui_story_5043_50430702_1_dialog_content = "Since we know where the guards came from, I can't leave it at that.",
  ui_story_5043_50430702_2_dialog_content = "PlayerName, I need to meet with the Guardians and decide what to do next.",
  ui_story_5043_50430702_3_dialog_content = "Then I'll need to update the City Lord about the recent Eclipsite problems.",
  ui_story_5043_50430702_4_dialog_content = "Go then. We can handle things here.",
  ui_story_5043_50430702_5_dialog_content = "Okay. I'll catch up with you before the hearing at the latest.",
  ui_story_5043_50430702_6_dialog_content = "Take care.",
  ui_story_5043_50430702_7_dialog_content = "We've all had a busy day. We should go home and rest.",
  ui_story_5043_50430702_8_dialog_content = "As for tomorrow...",
  ui_story_5043_50430702_9_dialog_content = "Well, we all know what we need to do, right?",
  ui_story_5043_50430702_10_dialog_content = "I'm sure the organizer of those weird Moonlight Salons will be in court before long.",
  ui_story_5043_50430702_11_dialog_content = "It does seem like there's something odd going on...",
  ui_story_5043_50430702_12_dialog_content = "Listen, why don't we go and find that nun tomorrow? All we'll need to do is follow the balloon.",
  ui_story_5043_50430702_13_dialog_content = "Can someone tell me what's been happening?",
  ui_story_5043_50430702_14_dialog_content = "And why is Tina asleep again?",
  ui_story_5043_50430702_15_dialog_content = "It's a long story. I'll fill you in on the way back.",
  ui_story_5043_50430702_16_dialog_content = "The carriage is here. We'll take Tina home. PlayerName, Leyn, we'll see you tomorrow.",
  ui_story_5043_50430702_17_dialog_content = "Eh?",
  ui_story_5043_50430702_18_dialog_content = "What?",
  ui_story_5043_50430702_19_dialog_content = "You didn't call me commoner for once.",
  ui_story_5043_50430702_20_dialog_content = "Oh shut up!",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>The Next Day</color>",
  ui_story_5043_50430702_22_dialog_content = "Oh, now I see.",
  ui_story_5043_50430702_23_dialog_content = "You're right. I choose the locations for our Moonlight Salons very carefully.",
  ui_story_5043_50430702_24_dialog_content = "I like places with a sense of culture. Places with statues are ideal.",
  ui_story_5043_50430702_25_dialog_content = "I don't mind if the statues are of old people, children, men, or—like the two that got damaged—women.",
  ui_story_5043_50430702_26_dialog_content = "They're all the building blocks of Lumopolis' civilization.",
  ui_story_5043_50430702_27_dialog_content = "But you can't deny that the Moonlight Salons seem to be causing damage to the statues.",
  ui_story_5043_50430702_28_dialog_content = "Oh, I don't intend to deny that things have been a little chaotic. And obviously I've been nearby when the statues have got damaged.",
  ui_story_5043_50430702_29_dialog_content = "But I can swear on the White Night up high that I have nothing to do with the damaged statues or the Eclipsite attacks.",
  ui_story_5043_50430702_30_dialog_content = "(This nun certainly looks and sounds calm and entirely unconcerned.)",
  ui_story_5043_50430702_31_dialog_content = "(And she's got such a powerful aura. Maybe because of her faith?)",
  ui_story_5043_50430702_32_dialog_content = "(My instincts tell me she hasn't got anything to do with our case.)",
  ui_story_5043_50430702_33_dialog_content = "Tut. Another dead end, and I guess we can't go around arresting people on our hunches.",
  ui_story_5043_50430702_34_dialog_content = "Sister, if all that you say is true...",
  ui_story_5043_50430702_35_dialog_content = "Might you be willing to attend the hearing as a witness?",
  ui_story_5043_50430702_36_dialog_content = "Well, I'm rushed off my feet organizing the Moonlight Salons, but if that's what the Hall of Justice desires, then yes.",
  ui_story_5043_50430702_37_dialog_content = "I'll do all I can to help.",
  ui_story_5043_50430702_38_dialog_content = "But...!",
  ui_story_5043_50430702_39_dialog_content = "(What if taking her to the Hall of Justice causes her more problems...)",
  ui_story_5043_50430702_40_dialog_content = "Yes? Young lady, you have something to say?",
  ui_story_5043_50430702_41_dialog_content = "I just want to know how you are able to stay so calm.",
  ui_story_5043_50430702_42_dialog_content = "I don't object to the Moonlight Salons. I enjoy them—they make Lumopolis seem like a different place.",
  ui_story_5043_50430702_43_dialog_content = "But the customs of Lumopolis are unaccepting even of divorce. Much less free love.",
  ui_story_5043_50430702_44_dialog_content = "And as a woman of faith, someone who is clearly very devout...",
  ui_story_5043_50430702_45_dialog_content = "How did you come to decide to organize these salons for the people of Lumopolis?",
  ui_story_5043_50430702_46_dialog_content = "And you're not afraid of setting foot inside the Hall of Justice? It's so... admirable.",
  ui_story_5043_50430702_47_dialog_content = "Tina...",
  ui_story_5043_50430702_48_dialog_content = "Heheh... My child, are you perhaps asking about your own worries?",
  ui_story_5043_50430702_49_dialog_content = "The thing is, when you get to my age, you simply stop worrying and overthinking so much.",
  ui_story_5043_50430702_50_dialog_content = "All I do is listen to the will of the God of Light.",
  ui_story_5043_50430702_51_dialog_content = "Over the course of its long history, Lumopolis has developed complex systems of etiquette to control our desires.",
  ui_story_5043_50430702_52_dialog_content = "But originally it was founded by ordinary men and women. Simple and pure Aurorians.",
  ui_story_5043_50430702_53_dialog_content = "Over the years, the teachings of the God of Light were reinterpreted over and over.",
  ui_story_5043_50430702_54_dialog_content = "But at their heart, those teachings are both simple and kind.",
  ui_story_5043_50430702_55_dialog_content = "And that's the God of Light's true blessing. His true lesson.",
  ui_story_5043_50430702_56_dialog_content = "All I'm doing is taking the Aurorians back to their origins, to their true desires.",
  ui_story_5043_50430702_57_dialog_content = "There's no sin in this. It's merely something that our rules and customs do not understand.",
  ui_story_5043_50430702_58_dialog_content = "Faith and love... at their roots, they're one.",
  ui_story_5043_50430702_59_dialog_content = "I-I think I understand. Thank you so much.",
  ui_story_5043_50430702_60_dialog_content = "Then I'll take my leave.",
  ui_story_5043_50430702_61_dialog_content = "And do let me know if I can help further with your investigation.",
  ui_story_5043_50430702_62_dialog_content = "Although if I might offer a small suggestion to the Hall of Justice?",
  ui_story_5043_50430702_63_dialog_content = "Oh...?",
  ui_story_5043_50430702_64_dialog_content = "If you really want to learn more before the court hearing starts, rather than simply going through your processes...",
  ui_story_5043_50430702_65_dialog_content = "Then you'll have to stop working so mechanically. Think about what the plaintiff really wants.",
  ui_story_5043_50430702_66_dialog_content = "Thank you for the advice. We will think about this...",
  ui_story_5043_50430702_67_dialog_content = "Sure. That is all. Until next time.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>The Following Day</color>",
  ui_story_5043_50430801_2_dialog_content = "What, is this all you've found?",
  ui_story_5043_50430801_3_dialog_content = "So you've not solved the original case, but you've managed to find another headless statue!?",
  ui_story_5043_50430801_4_dialog_content = "I am sorry. We're still investigating but have not had any breakthroughs so far...",
  ui_story_5043_50430801_5_dialog_content = "No breakthroughs!? You've made no progress at all!",
  ui_story_5043_50430801_6_dialog_content = "Is this the best the great Hall of Justice can do?",
  ui_story_5043_50430801_7_dialog_content = "I might as well hand the case over to a blind dog. Maybe it could sniff out the criminal!",
  ui_story_5043_50430801_8_dialog_content = "I'm sorry. We will try harder...",
  ui_story_5043_50430801_9_dialog_content = "I can see now that the Hall of Justice has no interest in the romantic problems of the citizenry.",
  ui_story_5043_50430801_10_dialog_content = "And this \"Romance Division\" is just a home for freeloaders!",
  ui_story_5043_50430801_11_dialog_content = "All taking plump pay packets and working hard—at sleeping!",
  ui_story_5043_50430801_12_dialog_content = "I cannot deny that we have such employees.",
  ui_story_5043_50430801_13_dialog_content = "B-But sleeping helps me work better...",
  ui_story_5043_50430801_14_dialog_content = "I'm losing my patience. The hearing is in two days!",
  ui_story_5043_50430801_15_dialog_content = "I'll say no more now. If you can't find something new tomorrow, I will have no choice but to continue to sue my neighbor.",
  ui_story_5043_50430801_16_dialog_content = "And I will be complaining to Lady Irridon!",
  ui_story_5043_50430801_17_dialog_content = "What's the point of paying you all so much if you can't solve our problems? Why, Lumopolis would be better off if we demolished the entire building!",
  ui_story_5043_50430801_18_dialog_content = "Demolish?",
  ui_story_5043_50430801_19_dialog_content = "Hey, that's a bit harsh, isn't it?",
  ui_story_5043_50430801_20_dialog_content = "Mr. Byron, please don't be hasty.",
  ui_story_5043_50430801_21_dialog_content = "Hmph. You all need to do better!",
  ui_story_5043_50430801_22_dialog_content = "H-He's gone.",
  ui_story_5043_50430801_23_dialog_content = "This is not good. The Romance Division could be in more trouble than I thought.",
  ui_story_5043_50430801_24_dialog_content = "Oh great. We're done for now.",
  ui_story_5043_50430801_25_dialog_content = "Chief Judge Irridon hates bad feedback from the public. If she gets a complaint...",
  ui_story_5043_50430801_26_dialog_content = "Yeah, she'll be very angry.",
  ui_story_5043_50430801_27_dialog_content = "And this is only a temporary arrangement. If the boss decides the Romance Division isn't doing its job...",
  ui_story_5043_50430801_28_dialog_content = "We could lose all this.",
  ui_story_5043_50430801_29_dialog_content = "I guess I was right earlier...",
  ui_story_5043_50430801_30_dialog_content = "The way things are looking, you really could all lose your jobs.",
  ui_story_5043_50430801_31_dialog_content = "Lose our jobs!?",
  ui_story_5043_50430801_32_dialog_content = "That can't happen. And things aren't that bad!",
  ui_story_5043_50430801_33_dialog_content = "P-Please don't even suggest it.",
  ui_story_5043_50430801_34_dialog_content = "If I lost my job, I'd die of boredom staying at home all day. I couldn't get out and have fun!",
  ui_story_5043_50430801_35_dialog_content = "Wait, that's all you're worried about? Having fun?",
  ui_story_5043_50430801_36_dialog_content = "Where will I find somewhere quiet enough to sleep in the daytime?",
  ui_story_5043_50430801_37_dialog_content = "You're not meant to be sleeping at work!",
  ui_story_5043_50430801_38_dialog_content = "And if I don't have a job, they'll make me go home.",
  ui_story_5043_50430801_39_dialog_content = "They'll force me to join the family business.",
  ui_story_5043_50430801_40_dialog_content = "Yeah. That's families. Nothing but bunches of boring old fogeys.",
  ui_story_5043_50430801_41_dialog_content = "Who in the world would want to sit there helping them count their Nightium?",
  ui_story_5043_50430801_42_dialog_content = "I can see you nobles don't need me worrying about you...",
  ui_story_5043_50430801_43_dialog_content = "So what if you lose your jobs? You'll be fine! Cheer up, everyone.",
  ui_story_5043_50430801_44_dialog_content = "Yes. Even if we do lose our jobs, life will go on.",
  ui_story_5043_50430801_45_dialog_content = "Although without a salary... I'll need to stock up on potatoes and veg.",
  ui_story_5043_50430801_46_dialog_content = "And cut down to one meal a day.",
  ui_story_5043_50430801_47_dialog_content = "Wait, how come things get so grim when we come to you?",
  ui_story_5043_50430801_48_dialog_content = "Because life in Lumopolis is grim, that's why.",
  ui_story_5043_50430801_49_dialog_content = "Buying food, keeping up with society. Living isn't free, you know.",
  ui_story_5043_50430801_50_dialog_content = "If I lose my salary, I need to start counting every penny.",
  ui_story_5043_50430801_51_dialog_content = "Wow. Life is tough...",
  ui_story_5043_50430801_52_dialog_content = "But it's not time to give up yet! We've still got a day. Let's make good use of it!",
  ui_story_5043_50430801_53_dialog_content = "Yeah. If we actually do something, we might make some progress.",
  ui_story_5043_50430801_54_dialog_content = "But the problem is—we don't have a single lead to follow.",
  ui_story_5043_50430801_55_dialog_content = "What line of inquiry should we take?",
  ui_story_5043_50430801_56_dialog_content = "Ladies and gentlemen... I have an idea!",
  ui_story_5043_50430801_57_dialog_content = "I've been thinking things over. Our approach has been too narrow.",
  ui_story_5043_50430801_58_dialog_content = "The serial statue decapitation case is no ordinary crime.",
  ui_story_5043_50430801_59_dialog_content = "The victims are statues. That means we can't look at their social circles to find someone with a motive.",
  ui_story_5043_50430801_60_dialog_content = "Similarly, there's no chance of finding the perpetrator among the members of the victim's family.",
  ui_story_5043_50430801_61_dialog_content = "True. These factors do hamper our investigations.",
  ui_story_5043_50430801_62_dialog_content = "But let's think outside the box for a moment.",
  ui_story_5043_50430801_63_dialog_content = "There's one crucial factor that has resulted in the damage to the statues becoming a case here at the court—",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>Love</color>!",
  ui_story_5043_50430801_65_dialog_content = "Yes. It's love that makes this a case for the Romance Division.",
  ui_story_5043_50430801_66_dialog_content = "And when love is involved, it is no longer possible to take a purely logical approach.",
  ui_story_5043_50430801_67_dialog_content = "We're not faced with any ordinary case. This is an affair of the heart.",
  ui_story_5043_50430801_68_dialog_content = "Oh! Oh! This makes everything clearer!",
  ui_story_5043_50430801_69_dialog_content = "Hang on. I'm not sure I follow...",
  ui_story_5043_50430801_70_dialog_content = "... Can you even hear yourselves?",
  ui_story_5043_50430801_71_dialog_content = "We don't have any leads. But maybe we don't need leads.",
  ui_story_5043_50430801_72_dialog_content = "My dear friends, when it comes to love it is not necessary to understand everything.",
  ui_story_5043_50430801_73_dialog_content = "The important thing is the heart.",
  ui_story_5043_50430801_74_dialog_content = "Think about what that nun said.",
  ui_story_5043_50430801_75_dialog_content = "\"If you really want to learn more before the court hearing starts, rather than simply going through your processes...",
  ui_story_5043_50430801_76_dialog_content = "Then you will have to stop working so mechanically. Think about what the plaintiff really wants.\"",
  ui_story_5043_50430801_77_dialog_content = "And we can solve the case with... heart?",
  ui_story_5043_50430801_78_dialog_content = "To work, friends!",
  ui_story_5043_50430801_79_dialog_content = "We'll find the answers the plaintiff needs, with love!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>The Next Day</color>",
  ui_story_5043_50430801_81_dialog_content = "Hey, why are you blocking the way?",
  ui_story_5043_50430801_82_dialog_content = "Let me in!",
  ui_story_5043_50430801_83_dialog_content = "Please wait a moment, Mr. Byron.",
  ui_story_5043_50430801_84_dialog_content = "The judges are currently busy in the courtroom.",
  ui_story_5043_50430801_85_dialog_content = "We'll let you through as soon as they have time to speak with you.",
  ui_story_5043_50430801_86_dialog_content = "Busy? Don't be ridiculous. They're busy with my case!",
  ui_story_5043_50430801_87_dialog_content = "If they want to hide from me, they could at least come up with a better excuse!",
  ui_story_5043_50430801_88_dialog_content = "Mr. Byron, the judges really are...",
  ui_story_5043_50430801_89_dialog_content = "I don't care what they're doing. These are the court's working hours.",
  ui_story_5043_50430801_90_dialog_content = "S-Sir, please wait!",
  ui_story_5043_50430801_91_dialog_content = "Step aside!",
  ui_story_5043_50430801_92_dialog_content = "Ah, but...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>Judge Matthieu! He's gone in!!!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50430801_95_dialog_content = "Congratulations, Mr. Byron!",
  ui_story_5043_50430801_96_dialog_content = "I'm so happy for you both!",
  ui_story_5043_50430801_97_dialog_content = "How wonderful for you to be reunited with your true love on this otherwise ordinary day!",
  ui_story_5043_50430801_98_dialog_content = "Huh? This is...",
  ui_story_5043_50430801_99_dialog_content = "It took us a whole day but we made your statue a new head.",
  ui_story_5043_50430801_100_dialog_content = "If we'd had a little bit more time, we'd have made it look even better!",
  ui_story_5043_50430801_101_dialog_content = "Yep. We realized we needed to take a more romantic approach and this was our solution.",
  ui_story_5043_50430801_102_dialog_content = "The question isn't what have you lost. It's what you can still get.",
  ui_story_5043_50430801_103_dialog_content = "After all, surely the loss of a mere head isn't going to stand in the way of your love?",
  ui_story_5043_50430801_104_dialog_content = "No. You still need to love. But it was understandable that her incompleteness saddened you.",
  ui_story_5043_50430801_105_dialog_content = "And to remove that sadness from your heart, we had to make her complete once more.",
  ui_story_5043_50430801_106_dialog_content = "Heheh. A beautiful tale of loss and recovery...",
  ui_story_5043_50430801_107_dialog_content = "Y-You...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>What in the world have you done!?</size>",
  ui_story_5043_50430801_109_dialog_content = "What's that hideous lump on Galatea's neck? Are you trying to insult me?",
  ui_story_5043_50430801_110_dialog_content = "This? Hideous?",
  ui_story_5043_50430801_111_dialog_content = "You don't seem pleased...",
  ui_story_5043_50430801_112_dialog_content = "Tut. I knew we shouldn't trust a commoner in matters of aesthetics.",
  ui_story_5043_50430801_113_dialog_content = "If you aren't happy with her new appearance, we can make another...",
  ui_story_5043_50430801_114_dialog_content = "Stop it! You morons have made a mockery of my love!",
  ui_story_5043_50430801_115_dialog_content = "What would you know of true love!?",
  ui_story_5043_50430801_116_dialog_content = "Love is unique and true! Love is a choice that can never change!",
  ui_story_5043_50430801_117_dialog_content = "And when Galatea lost her head, my love died!",
  ui_story_5043_50430801_118_dialog_content = "Even if you could produce an exact replica of her head, she would not be my Galatea!",
  ui_story_5043_50430801_119_dialog_content = "She would not be the one I loved!",
  ui_story_5043_50430801_120_dialog_content = "Ah. So that's how it works...",
  ui_story_5043_50430801_121_dialog_content = "Erm, so I misunderstood?",
  ui_story_5043_50430801_122_dialog_content = "We failed. I guess the Romance Division is doomed...",
  ui_story_5043_50430801_123_dialog_content = "Oh, never mind all that for now.",
  ui_story_5043_50430801_124_dialog_content = "I've got more important things to discuss with you.",
  ui_story_5043_50430801_125_dialog_content = "My <color=#FFB400>wife</color> is in mortal danger right at this very moment.",
  ui_story_5043_50430801_126_dialog_content = "For the sake of our love, I beg you to send people to protect her!",
  ui_story_5043_50430801_127_dialog_content = "W-Wait! Your wife is in mortal danger?",
  ui_story_5043_50430801_128_dialog_content = "Isn't this your wife?",
  ui_story_5043_50430801_129_dialog_content = "No, you've got it wrong. Galatea is my <color=#FFB400>lover</color>!",
  ui_story_5043_50430801_130_dialog_content = "The person in mortal danger is my <color=#FFB400>wife</color>. They're not the same person.",
  ui_story_5043_50430801_131_dialog_content = "What!?",
  ui_story_5043_50430801_132_dialog_content = "Your wife and your lover are different people?",
  ui_story_5043_50430801_133_dialog_content = "My wife is a different gorgeous statue. She's called Aphrodite.",
  ui_story_5043_50430801_134_dialog_content = "And what happened to love being unique and true?",
  ui_story_5043_50430801_135_dialog_content = "Of course it is!",
  ui_story_5043_50430801_136_dialog_content = "So how come you're in love with two different statues?",
  ui_story_5043_50430801_137_dialog_content = "Love is also vast and accepting.",
  ui_story_5043_50430801_138_dialog_content = "I love my wife. And I love my lover. Two different and unique loves.",
  ui_story_5043_50430801_139_dialog_content = "Consider this. You love your mother, don't you? And you also love your father?",
  ui_story_5043_50430801_140_dialog_content = "I guess that makes a sort of sense...",
  ui_story_5043_50430801_141_dialog_content = "It does not! Those are completely different types of relationships.",
  ui_story_5043_50430801_142_dialog_content = "Look, I don't have time to educate you children about the nature of love.",
  ui_story_5043_50430801_143_dialog_content = "I just saw the moon-balloon floating up above the Stairway to the Skies.",
  ui_story_5043_50430801_144_dialog_content = "And that's where my wife is.",
  ui_story_5043_50430801_145_dialog_content = "You already know that balloon means there will be a Moonlight Salon. And a Moonlight Salon means a statue will lose its head.",
  ui_story_5043_50430801_146_dialog_content = "And if anything should happen to my wife... I-I will have nobody left to love.",
  ui_story_5043_50430801_147_dialog_content = "Surely it's your duty to protect citizens' right to love?",
  ui_story_5043_50430801_148_dialog_content = "Well, we've accepted your case. So I guess we need to protect your love.",
  ui_story_5043_50430801_149_dialog_content = "Tut, or half of his love, at least.",
  ui_story_5043_50430801_150_dialog_content = "And there's a chance we'll find a new lead to help us with our case.",
  ui_story_5043_50430801_151_dialog_content = "We have to go in order to solve the serial statue decapitation case.",
  ui_story_5043_50430801_152_dialog_content = "So what are you waiting for? Move!",
  ui_story_5043_50430801_153_dialog_content = "The Moonlight Salon is about to start!",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>Lumopolis Courtyard, near the Stairway to the Skies</color>",
  ui_story_5043_50430801_155_dialog_content = "Ah, we're almost there.",
  ui_story_5043_50430801_156_dialog_content = "Mr. Byron said his wife was here. So she must be...",
  ui_story_5043_50430801_157_dialog_content = "Got it. It must be this one!",
  ui_story_5043_50430801_158_dialog_content = "Oh. And still intact.",
  ui_story_5043_50430801_159_dialog_content = "So all we need to do is protect the statue?",
  ui_story_5043_50430801_160_dialog_content = "Yeah. The criminal may try to strike during the salon.",
  ui_story_5043_50430801_161_dialog_content = "But where are all the salon-goers?",
  ui_story_5043_50430801_162_dialog_content = "I see them. They're all at the bottom of the stairs.",
  ui_story_5043_50430801_163_dialog_content = "So they are. Aren't they coming up?",
  ui_story_5043_50430801_164_dialog_content = "Ah, this means we've struck lucky.",
  ui_story_5043_50430801_165_dialog_content = "If the salon is down there, it'll be easier to protect a statue up here.",
  ui_story_5043_50430801_166_dialog_content = "Awesome. We can do what Mr. Byron asked.",
  ui_story_5043_50430801_167_dialog_content = "Oh, I see the judges are here.",
  ui_story_5043_50430801_168_dialog_content = "Sister! I didn't expect to see you again so soon.",
  ui_story_5043_50430801_169_dialog_content = "Where else would you expect to find me, if not under the moon-balloon?",
  ui_story_5043_50430801_170_dialog_content = "And now you are here, why not join the celebrations?",
  ui_story_5043_50430801_171_dialog_content = "Is the salon being held at the bottom of the stairs?",
  ui_story_5043_50430801_172_dialog_content = "We'd love to help, but we've got a...",
  ui_story_5043_50430801_173_dialog_content = "Oh no. Today's event is not a salon.",
  ui_story_5043_50430801_174_dialog_content = "Huh? So what...",
  ui_story_5043_50430801_175_dialog_content = "<size=45>Is everyone ready?</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>Let the parade begin!</size>",
  ui_story_5043_50430901_1_dialog_content = "We're here to sing in praise of love! ♪",
  ui_story_5043_50430901_2_dialog_content = "Here in sacred Lumopolis! ♪",
  ui_story_5043_50430901_3_dialog_content = "Here in sight of all lovers! ♪",
  ui_story_5043_50430901_4_dialog_content = "Sing in praise of love's true beauty! ♪",
  ui_story_5043_50430901_5_dialog_content = "We sing in praise of love! ♪",
  ui_story_5043_50430901_6_dialog_content = "Sing in praise of love! ♪",
  ui_story_5043_50430901_7_dialog_content = "Marchers... march!",
  ui_story_5043_50430901_8_dialog_content = "Wow? There's a massive crowd of people coming up the stairs.",
  ui_story_5043_50430901_9_dialog_content = "This is not good, right?",
  ui_story_5043_50430901_10_dialog_content = "Yeah. If they come past the statue, it's going to be harder to keep it safe.",
  ui_story_5043_50430901_11_dialog_content = "And if the statue gets damaged under your nose again, your jobs are as good as lost.",
  ui_story_5043_50430901_12_dialog_content = "We need to figure out a way to stop the parade.",
  ui_story_5043_50430901_13_dialog_content = "Stop the parade? Why, have we done something wrong?",
  ui_story_5043_50430901_14_dialog_content = "This took a lot of organizing. You can't stop it from going ahead without good reason.",
  ui_story_5043_50430901_15_dialog_content = "They're moving quickly. We haven't got long.",
  ui_story_5043_50430901_16_dialog_content = "I'll try and stop them. You explain to the nun!",
  ui_story_5043_50430901_17_dialog_content = "Oh, why are commoners always so hasty...",
  ui_story_5043_50430901_18_dialog_content = "Sister, listen. We don't want to stop the parade.",
  ui_story_5043_50430901_19_dialog_content = "But we have to. For love.",
  ui_story_5043_50430901_20_dialog_content = "Love?",
  ui_story_5043_50430901_21_dialog_content = "Someone's going to use the parade as cover to commit a crime.",
  ui_story_5043_50430901_22_dialog_content = "And I'm sure you don't want your events to get a reputation for causing heartbreak, right?",
  ui_story_5043_50430901_23_dialog_content = "We! Praise! Love!",
  ui_story_5043_50430901_24_dialog_content = "Free! Love!",
  ui_story_5043_50430901_25_dialog_content = "Woah! Hold up, everyone!",
  ui_story_5043_50430901_26_dialog_content = "I think we're going the wrong way.",
  ui_story_5043_50430901_27_dialog_content = "We're meant to be going to the residential district in Lumopolis Courtyard!",
  ui_story_5043_50430901_28_dialog_content = "We need to turn around and go back.",
  ui_story_5043_50430901_29_dialog_content = "Yeah! Go back!",
  ui_story_5043_50430901_30_dialog_content = "Huh? We're going the wrong way?",
  ui_story_5043_50430901_31_dialog_content = "That's not right. We were told to climb the Stairway to the Skies together.",
  ui_story_5043_50430901_32_dialog_content = "We must have got it wrong. Maybe someone misheard the instructions.",
  ui_story_5043_50430901_33_dialog_content = "The residential district?",
  ui_story_5043_50430901_34_dialog_content = "I heard it was the square in Lumopolis Courtyard!",
  ui_story_5043_50430901_35_dialog_content = "That's miles away! Hurry up, let's turn around and get going!",
  ui_story_5043_50430901_36_dialog_content = "Exactly! Turn around and get going!",
  ui_story_5043_50430901_37_dialog_content = "Go back? But we've come so far...",
  ui_story_5043_50430901_38_dialog_content = "Yeah!",
  ui_story_5043_50430901_39_dialog_content = "But we're meant to be going to the residential district.",
  ui_story_5043_50430901_40_dialog_content = "No! It's the square!",
  ui_story_5043_50430901_41_dialog_content = "Hold on. I remember very clearly being told we were going to climb Stairway to the Skies.",
  ui_story_5043_50430901_42_dialog_content = "Right! And if not, why did we all meet at the bottom of the stairs?",
  ui_story_5043_50430901_43_dialog_content = "You people who want to go to the residential district or the square, where did you get your info?",
  ui_story_5043_50430901_44_dialog_content = "Some guy with white hair tied in a ponytail. He seemed trustworthy.",
  ui_story_5043_50430901_45_dialog_content = "Some trustworthy-looking guy with white hair tied in a ponytail.",
  ui_story_5043_50430901_46_dialog_content = "Hey, that's the same person. You've been tricked!",
  ui_story_5043_50430901_47_dialog_content = "What?!",
  ui_story_5043_50430901_48_dialog_content = "Hey, that's him! Look, he's got white hair and a ponytail!",
  ui_story_5043_50430901_49_dialog_content = "What? Me? No, I'm just passing...",
  ui_story_5043_50430901_50_dialog_content = "That's him!",
  ui_story_5043_50430901_51_dialog_content = "He's the one that told me!",
  ui_story_5043_50430901_52_dialog_content = "So who is this stranger trying to ruin our Love Parade?",
  ui_story_5043_50430901_53_dialog_content = "Take him to the Romance Division!",
  ui_story_5043_50430901_54_dialog_content = "T-There's no need. I'm going there anyway...",
  ui_story_5043_50430901_55_dialog_content = "Come on! Keep marching up the steps!",
  ui_story_5043_50430901_56_dialog_content = "And don't let that guy get away.",
  ui_story_5043_50430901_57_dialog_content = "(Darn. My brilliant idea wasn't as good as I'd hoped.)",
  ui_story_5043_50430901_58_dialog_content = "(And the people have set off again. What should I do?)",
  ui_story_5043_50430901_59_dialog_content = "Oh dear, oh dear! I've knocked over the pails of milk and honey!",
  ui_story_5043_50430901_60_dialog_content = "Oh my, what a clumsy man I am.",
  ui_story_5043_50430901_61_dialog_content = "What? Look at all the milk pouring down the stairs.",
  ui_story_5043_50430901_62_dialog_content = "Where in the world did that come from?",
  ui_story_5043_50430901_63_dialog_content = "And why is there honey mixed in the milk!?",
  ui_story_5043_50430901_64_dialog_content = "(T-That looks like one of Matthieu's more direct strategies!)",
  ui_story_5043_50430901_65_dialog_content = "(It was a weird idea but it seems to have worked. People have stopped.)",
  ui_story_5043_50430901_66_dialog_content = "Wow. Everything seems to be going wrong today.",
  ui_story_5043_50430901_67_dialog_content = "We can't give up. As the God of Light says, the road to the blessed land is one of trial and tribulation!",
  ui_story_5043_50430901_68_dialog_content = "Exactly! The milk and honey simply show that we are on the right path!",
  ui_story_5043_50430901_69_dialog_content = "Continue forward, everyone. But take care not to slip.",
  ui_story_5043_50430901_70_dialog_content = "(They've started again?)",
  ui_story_5043_50430901_71_dialog_content = "(They sure are a determined bunch...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>Ahhh!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>The stairs are so slippery!!!</size>",
  ui_story_5043_50430901_74_dialog_content = "What's going on?!",
  ui_story_5043_50430901_75_dialog_content = "I think someone fell over.",
  ui_story_5043_50430901_76_dialog_content = "Boo-hoo... it really hurts...",
  ui_story_5043_50430901_77_dialog_content = "I'm seeing stars, even if it's daytime.",
  ui_story_5043_50430901_78_dialog_content = "S-She seems badly injured.",
  ui_story_5043_50430901_79_dialog_content = "These steps are kind of dangerous right now...",
  ui_story_5043_50430901_80_dialog_content = "Maybe... we should call it quits for today?",
  ui_story_5043_50430901_81_dialog_content = "Yeah. We can parade somewhere else.",
  ui_story_5043_50430901_82_dialog_content = "Don't just stand there blocking the way. Find someone to take this poor girl to a doctor.",
  ui_story_5043_50430901_83_dialog_content = "They're falling back!",
  ui_story_5043_50430901_84_dialog_content = "Excellent performance, Tina!",
  ui_story_5043_50430901_85_dialog_content = "Yeah, very convincing!",
  ui_story_5043_50430901_86_dialog_content = "Heehee. If I do lose my job at the Hall of Justice, maybe I'll take to the stage.",
  ui_story_5043_50430901_87_dialog_content = "And what about my trick? Clever, huh?",
  ui_story_5043_50430901_88_dialog_content = "It was awesome. Just perfect.",
  ui_story_5043_50430901_89_dialog_content = "You children... that was something else.",
  ui_story_5043_50430901_90_dialog_content = "But as it was all to protect the reputation of these events, so be it.",
  ui_story_5043_50430901_91_dialog_content = "All love is worthy of protection. Even love of a statue.",
  ui_story_5043_50430901_92_dialog_content = "I can see why you run your salons. Thanks for being so understanding, Sister.",
  ui_story_5043_50430901_93_dialog_content = "I must go. I'll steer the parade people in a different direction.",
  ui_story_5043_50430901_94_dialog_content = "And we'll do our best at our jobs too.",
  ui_story_5043_50430901_95_dialog_content = "Oh no! Everyone, stop!",
  ui_story_5043_50430901_96_dialog_content = "We need to go back to the stairs!",
  ui_story_5043_50430901_97_dialog_content = "What's going on? There's some kind of commotion!",
  ui_story_5043_50430901_98_dialog_content = "Eclipsites! Where did they come from!?",
  ui_story_5043_50430901_99_dialog_content = "Quick! Get up the stairs!",
  ui_story_5043_50430901_100_dialog_content = "What? Where did these Eclipsites come from?",
  ui_story_5043_50430901_101_dialog_content = "I see them! Only a few, though.",
  ui_story_5043_50430901_102_dialog_content = "Leyn is already tackling them!",
  ui_story_5043_50430901_103_dialog_content = "Let's go help him, stat!",
  ui_story_5043_50430901_104_dialog_content = "Don't forget the statue! That crowd is about to stampede past.",
  ui_story_5043_50430901_105_dialog_content = "It's just a few Eclipsites. One extra person should be enough.",
  ui_story_5043_50430901_106_dialog_content = "Tina, you go help Leyn. Everyone else stay here with the statue.",
  ui_story_5043_50430901_107_dialog_content = "I'll use my psychic abilities to help you fight the Eclipsites, Tina.",
  ui_story_5043_50430901_108_dialog_content = "Okay, sounds good.",
  ui_story_5043_50430901_109_dialog_content = "You guys make sure you look after the statue!",
  ui_story_5043_50431001_1_dialog_content = "That's the last one over there!",
  ui_story_5043_50431001_2_dialog_content = "Leave it to me!",
  ui_story_5043_50431001_3_dialog_content = "Okay. That's all the Eclipsites dealt with.",
  ui_story_5043_50431001_4_dialog_content = "But... it looks like all the people ran up the stairs.",
  ui_story_5043_50431001_5_dialog_content = "I wonder how PlayerName and the others are doing.",
  ui_story_5043_50431001_6_dialog_content = "Hey! Be careful everyone!",
  ui_story_5043_50431001_7_dialog_content = "There's a very valuable statue here. You broke it, you bought it!",
  ui_story_5043_50431001_8_dialog_content = "Eclipsites! What are you waiting for!? Run!",
  ui_story_5043_50431001_9_dialog_content = "Everyone can stop panicking! The Eclipsites have been dealt with!",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431001_11_dialog_content = "What's going on?!",
  ui_story_5043_50431001_12_dialog_content = "Oh, no! Someone crashed into the statue!",
  ui_story_5043_50431001_13_dialog_content = "Thankfully it doesn't seem to be damaged.",
  ui_story_5043_50431001_14_dialog_content = "Ahhhhhh!",
  ui_story_5043_50431001_15_dialog_content = "They're coming back!",
  ui_story_5043_50431001_16_dialog_content = "Matthieu, stop them!",
  ui_story_5043_50431001_17_dialog_content = "Sure, but how...",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431001_19_dialog_content = "Ouch!",
  ui_story_5043_50431001_20_dialog_content = "Are you alright?",
  ui_story_5043_50431001_21_dialog_content = "How about you help me up rather than asking stupid questions?",
  ui_story_5043_50431001_22_dialog_content = "Crap! There are Eclipsites in the crowd!",
  ui_story_5043_50431001_23_dialog_content = "Eclipsites?!",
  ui_story_5043_50431001_24_dialog_content = "You're right. I can see several of them.",
  ui_story_5043_50431001_25_dialog_content = "Where are they coming from?",
  ui_story_5043_50431001_26_dialog_content = "Don't panic! I'll shoe them to death!",
  ui_story_5043_50431001_27_dialog_content = "Can you kill an Eclipsite with a shoe?",
  ui_story_5043_50431001_28_dialog_content = "Wait! That's going to hit the statue!",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431001_30_dialog_content = "I hope Mr. Byron doesn't object to a little footprint...",
  ui_story_5043_50431001_31_dialog_content = "I'll help! Watch this!",
  ui_story_5043_50431001_32_dialog_content = "What!? Another one?",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431001_34_dialog_content = "Hey, is the statue okay?",
  ui_story_5043_50431001_35_dialog_content = "It seems okay for now, but if this carries on...",
  ui_story_5043_50431001_36_dialog_content = "Stop throwing shoes. You aren't even damaging a statue!",
  ui_story_5043_50431001_37_dialog_content = "Let alone defeat the Eclipsites!",
  ui_story_5043_50431001_38_dialog_content = "He's right. Have we got any better weapons?",
  ui_story_5043_50431001_39_dialog_content = "I do! Some cheese. It's rock hard!",
  ui_story_5043_50431001_40_dialog_content = "What kind of person carries cheese around!?",
  ui_story_5043_50431001_41_dialog_content = "Oh no. If the cheese hits the statue then it might...",
  ui_story_5043_50431001_42_dialog_content = "Everyone, calm down! I said, calm down! Stop throwing things.",
  ui_story_5043_50431001_43_dialog_content = "I don't want to see any more throwing!",
  ui_story_5043_50431001_44_dialog_content = "Sister!",
  ui_story_5043_50431001_45_dialog_content = "Everyone stop throwing things. We might hit Sister.",
  ui_story_5043_50431001_46_dialog_content = "Phew... I think we've avoided disaster.",
  ui_story_5043_50431001_47_dialog_content = "Thank you, Sister.",
  ui_story_5043_50431001_48_dialog_content = "It's nothing. I was just doing my duty.",
  ui_story_5043_50431001_49_dialog_content = "I can't let our Mooncrown Day themed events get a reputation for ruining people's love!",
  ui_story_5043_50431001_50_dialog_content = "(Well, given how she protected the statue, I think we can eliminate her from our enquiries.)",
  ui_story_5043_50431001_51_dialog_content = "The crowd is dispersing at last.",
  ui_story_5043_50431001_52_dialog_content = "It looks like we can relax.",
  ui_story_5043_50431001_53_dialog_content = "Yeah.",
  ui_story_5043_50431001_54_dialog_content = "That stampeding crowd was scarier than the Eclipsites.",
  ui_story_5043_50431001_55_dialog_content = "Sure was. If I'd known I'd have gone with Tina.",
  ui_story_5043_50431001_56_dialog_content = "Hey! Why are you just standing there?",
  ui_story_5043_50431001_57_dialog_content = "Leyn, you're back!",
  ui_story_5043_50431001_58_dialog_content = "Behind you!",
  ui_story_5043_50431001_59_dialog_content = "There are Eclipsites behind you!",
  ui_story_5043_50431002_1_dialog_content = "These Eclipsites sure know how to sneak up on folk.",
  ui_story_5043_50431002_2_dialog_content = "But they can't stand up to a good fight.",
  ui_story_5043_50431002_3_dialog_content = "Don't relax yet. There are still some left.",
  ui_story_5043_50431002_4_dialog_content = "Come on, let's finish them off.",
  ui_story_5043_50431002_5_dialog_content = "Wait!",
  ui_story_5043_50431002_6_dialog_content = "PlayerName, beside you...",
  ui_story_5043_50431002_7_dialog_content = "Beside me?",
  ui_story_5043_50431002_8_dialog_content = "It's...",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5043_50431002_10_dialog_content = "Oh no! The statue...",
  ui_story_5043_50431002_11_dialog_content = "Who did this!?",
  ui_story_5043_50431002_12_dialog_content = "I've got the vandal's hand!",
  ui_story_5043_50431002_13_dialog_content = "Quick, pull him out from the pile of Eclipsites.",
  ui_story_5043_50431002_14_dialog_content = "Step aside! You're all in my way.",
  ui_story_5043_50431002_15_dialog_content = "Huh? There's nobody here.",
  ui_story_5043_50431002_16_dialog_content = "Sorry. He got away.",
  ui_story_5043_50431002_17_dialog_content = "He slipped out of his glove and escaped. Like a lizard abandoning its tail...",
  ui_story_5043_50431002_18_dialog_content = "This is awful. The statue got damaged right under my nose!",
  ui_story_5043_50431002_19_dialog_content = "How am I going to explain this?",
  ui_story_5043_50431002_20_dialog_content = "Well... at least we've got the culprit's glove, right?",
  ui_story_5043_50431002_21_dialog_content = "That's a valuable lead.",
  ui_story_5043_50431002_22_dialog_content = "I guess we could call it a breakthrough in our investigation.",
  ui_story_5043_50431002_23_dialog_content = "But... I don't think Mr. Byron will see it like that.",
  ui_story_5043_50431002_24_dialog_content = "Hey, where's Tina?",
  ui_story_5043_50431002_25_dialog_content = "I thought she was with you, Leyn?",
  ui_story_5043_50431002_26_dialog_content = "I guess she got left behind while I was rushing back.",
  ui_story_5043_50431002_27_dialog_content = "Hey? Are you all okay?",
  ui_story_5043_50431002_28_dialog_content = "Sorry, I met some more Eclipsites on the way up the stairs.",
  ui_story_5043_50431002_29_dialog_content = "Wait, the statue... where's its head!?",
  ui_story_5043_50431002_30_dialog_content = "Sigh...",
  ui_story_5043_50431002_31_dialog_content = "Come on. Let's go back and report in.",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>The Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>My wife! My wife!</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>My darling Aphrodite!</size>",
  ui_story_5043_50431002_35_dialog_content = "...",
  ui_story_5043_50431002_36_dialog_content = "We're dead.",
  ui_story_5043_50431002_37_dialog_content = "How... Why did this have to happen?",
  ui_story_5043_50431002_38_dialog_content = "I loved you so much. And I did everything I could to protect you.",
  ui_story_5043_50431002_39_dialog_content = "And yet... my love has been stolen from me...",
  ui_story_5043_50431002_40_dialog_content = "Why can't I save my beloved statues? Not even one of them...",
  ui_story_5043_50431002_41_dialog_content = "I know what happened and understand how you must feel, Mr. Byron.",
  ui_story_5043_50431002_42_dialog_content = "You? You understand?",
  ui_story_5043_50431002_43_dialog_content = "You understand nothing!",
  ui_story_5043_50431002_44_dialog_content = "There's nothing left in this world worthy of my love!",
  ui_story_5043_50431002_45_dialog_content = "Oh God of Light, why do you punish me like this...",
  ui_story_5043_50431002_46_dialog_content = "Perhaps if you calm down.",
  ui_story_5043_50431002_47_dialog_content = "After all, what's done is done.",
  ui_story_5043_50431002_48_dialog_content = "But we will ensure you get justice.",
  ui_story_5043_50431002_49_dialog_content = "Ha. The Hall of Justice can't help!",
  ui_story_5043_50431002_50_dialog_content = "If the Hall of Justice could do its job, then my wife wouldn't have suffered this fate!",
  ui_story_5043_50431002_51_dialog_content = "Never mind the fact that three of your judges failed to find the culprit! You couldn't even protect a single statue!",
  ui_story_5043_50431002_52_dialog_content = "Just you wait until Chief Judge Irridon hears of your great successes!",
  ui_story_5043_50431002_53_dialog_content = "I'm sure she won't let one division full of incompetents ruin the good name of the Hall of Justice!",
  ui_story_5043_50431002_54_dialog_content = "I'm very sorry we disappointed you so badly, Mr. Byron.",
  ui_story_5043_50431002_55_dialog_content = "We were unable to protect the statue or catch the culprit at the scene.",
  ui_story_5043_50431002_56_dialog_content = "But... we were able to get a glove the culprit was wearing.",
  ui_story_5043_50431002_57_dialog_content = "My goodness! So my wife has lost her lovely head, and in return, you've got a glove?",
  ui_story_5043_50431002_58_dialog_content = "Surely you don't think this was a worthwhile exchange.",
  ui_story_5043_50431002_59_dialog_content = "How many people live in Lumopolis? How many pairs of gloves do they have?",
  ui_story_5043_50431002_60_dialog_content = "And what will you even do with this glove, given how incompetent the entire Romance Division is?",
  ui_story_5043_50431002_61_dialog_content = "Mr. Byron, please don't dismiss the entire Romance Division because of the failings of a few employees.",
  ui_story_5043_50431002_62_dialog_content = "The judges have not performed well. But as the chief judge, I ensure that each case reaches a just conclusion.",
  ui_story_5043_50431002_63_dialog_content = "A just conclusion? Save the pretty words for Chief Judge Irridon!",
  ui_story_5043_50431002_64_dialog_content = "My lover and my wife has been damaged. And the guilty party remains at large.",
  ui_story_5043_50431002_65_dialog_content = "You call this justice!?",
  ui_story_5043_50431002_66_dialog_content = "Not yet, Mr. Byron. But let's not be too hasty.",
  ui_story_5043_50431002_67_dialog_content = "The culprit has not escaped until the gavel falls.",
  ui_story_5043_50431002_68_dialog_content = "Oh, you think you can catch the criminal before the case concludes?",
  ui_story_5043_50431002_69_dialog_content = "Judge Leyn, please present the glove.",
  ui_story_5043_50431002_70_dialog_content = "Of course.",
  ui_story_5043_50431002_71_dialog_content = "This is a glove taken from the hand of the culprit at the scene. Is that correct?",
  ui_story_5043_50431002_72_dialog_content = "It is. I almost caught the culprit, but he escaped by slipping out of the glove.",
  ui_story_5043_50431002_73_dialog_content = "Which makes things simple. Whoever owns the glove removed the statue's head.",
  ui_story_5043_50431002_74_dialog_content = "And as it happens, my people have found <color=#FFB400>the other glove</color>.",
  ui_story_5043_50431002_75_dialog_content = "As you will see, the two gloves are a pair.",
  ui_story_5043_50431002_76_dialog_content = "The other glove!?",
  ui_story_5043_50431002_77_dialog_content = "?!",
  ui_story_5043_50431002_78_dialog_content = "But how!?",
  ui_story_5043_50431002_79_dialog_content = "Where did you find it? And who does it belong to?",
  ui_story_5043_50431002_80_dialog_content = "And now we have the gloves, we can easily bring this case to a just conclusion.",
  ui_story_5043_50431002_81_dialog_content = "Guards! Stand ready!",
  ui_story_5043_50431002_82_dialog_content = "And arrest... Tina Campbell!",
  ui_story_5043_50431002_83_dialog_content = "What? Arrest Tina?",
  ui_story_5043_50431002_84_dialog_content = "Yes, sir!",
  ui_story_5043_50431101_1_dialog_content = "Wait! This can't be right.",
  ui_story_5043_50431101_2_dialog_content = "How can it be Tina!",
  ui_story_5043_50431101_3_dialog_content = "I know. It's not possible.",
  ui_story_5043_50431101_4_dialog_content = "Are you some kind of idiot, Chief Judge Schwab?",
  ui_story_5043_50431101_5_dialog_content = "You judges lack judgment. Haven't I made my reasoning perfectly clear?",
  ui_story_5043_50431101_6_dialog_content = "The owner of the glove collected by Judge Leyn is the culprit. That's obvious.",
  ui_story_5043_50431101_7_dialog_content = "And after this latest incident, my people were able to quickly identify the other half of the pair.",
  ui_story_5043_50431101_8_dialog_content = "And it was found... in Judge Tina's desk drawer.",
  ui_story_5043_50431101_9_dialog_content = "What!?",
  ui_story_5043_50431101_10_dialog_content = "Tina, are these your gloves?",
  ui_story_5043_50431101_11_dialog_content = "I... I do have a pair of gloves like that.",
  ui_story_5043_50431101_12_dialog_content = "But I don't understand how they turned up at the scene...",
  ui_story_5043_50431101_13_dialog_content = "Judge Tina, I'm not sure you understand how grave your situation is.",
  ui_story_5043_50431101_14_dialog_content = "Given you're our prime suspect, you should be telling us how the gloves came to be there.",
  ui_story_5043_50431101_15_dialog_content = "And I would never have expected a pretty little thing such as yourself to commit such cruel crimes.",
  ui_story_5043_50431101_16_dialog_content = "Ah, the tragedy of it all...",
  ui_story_5043_50431101_17_dialog_content = "Hey! Stop slandering poor Tina!",
  ui_story_5043_50431101_18_dialog_content = "Tina was with us when everything happened. Fighting Eclipsites!",
  ui_story_5043_50431101_19_dialog_content = "We can all give her an alibi. She can't be the culprit!",
  ui_story_5043_50431101_20_dialog_content = "Leyn, remember that you must take responsibility for your statements as a judge.",
  ui_story_5043_50431101_21_dialog_content = "I'm sure you don't need me to tell you the punishments for perjury.",
  ui_story_5043_50431101_22_dialog_content = "But he's right! And I can prove it!",
  ui_story_5043_50431101_23_dialog_content = "Really? Think carefully, all of you.",
  ui_story_5043_50431101_24_dialog_content = "When the incident occurred, was Judge Tina actually at your side in the fight against the Eclipsites?",
  ui_story_5043_50431101_25_dialog_content = "She...",
  ui_story_5043_50431101_26_dialog_content = "Hey, where's Tina?",
  ui_story_5043_50431101_27_dialog_content = "I thought she was with you, Leyn?",
  ui_story_5043_50431101_28_dialog_content = "I guess she got left behind while I was rushing back.",
  ui_story_5043_50431101_29_dialog_content = "Hey? Are you all okay?",
  ui_story_5043_50431101_30_dialog_content = "(Oh no... She really wasn't with us during the fight!)",
  ui_story_5043_50431101_31_dialog_content = "It seems you understand now.",
  ui_story_5043_50431101_32_dialog_content = "When testifying under oath, it's imperative that we pay close attention to every single word that's spoken.",
  ui_story_5043_50431101_33_dialog_content = "If you cannot grasp a basic concept such as this, I fear you'll never be a worthy judge in the Hall of Justice.",
  ui_story_5043_50431101_34_dialog_content = "...",
  ui_story_5043_50431101_35_dialog_content = "In any case, the culprit has been captured, so let's bring today's farcical proceedings to an end.",
  ui_story_5043_50431101_36_dialog_content = "Are you satisfied with our results today, Mr. Byron?",
  ui_story_5043_50431101_37_dialog_content = "I would never have expected a judge to be the culprit behind all this...",
  ui_story_5043_50431101_38_dialog_content = "No wonder you people get nothing done around here!",
  ui_story_5043_50431101_39_dialog_content = "That's not it at all, Mr. Byron...",
  ui_story_5043_50431101_40_dialog_content = "I was foolish enough to put my faith in you lot...",
  ui_story_5043_50431101_41_dialog_content = "And what did I get in return, eh? A bunch of misfits bickering about love while destroying it and wasting my time!",
  ui_story_5043_50431101_42_dialog_content = "This lousy criminal better answer for her crimes, Chief Judge Schwab! I mean it!",
  ui_story_5043_50431101_43_dialog_content = "I assure you that she will be brought to justice, Mr. Byron... Just not today.",
  ui_story_5043_50431101_44_dialog_content = "Let's not forget that the trial of the statue decapitator will be held tomorrow.",
  ui_story_5043_50431101_45_dialog_content = "At that time, you may present your claim to the court.",
  ui_story_5043_50431101_46_dialog_content = "I'm well aware of that!",
  ui_story_5043_50431101_47_dialog_content = "My lover, my wife... They're the true victims of all of this! They didn't deserve what happened to them!",
  ui_story_5043_50431101_48_dialog_content = "Promise me that you'll seek justice for them, Chief Judge Schwab!",
  ui_story_5043_50431101_49_dialog_content = "But of course. The Romance Division has a duty to protect the sanctity of love, after all.",
  ui_story_5043_50431101_50_dialog_content = "Guards! Take her away!",
  ui_story_5043_50431101_51_dialog_content = "A moment, please!",
  ui_story_5043_50431101_52_dialog_content = "Your Honor, I would like to inspect that glove one more time.",
  ui_story_5043_50431101_53_dialog_content = "There's no way Tina could have committed this crime... Maybe we misinterpreted some parts of the evidence?",
  ui_story_5043_50431101_54_dialog_content = "Either way, we cannot have her detained so hastily!",
  ui_story_5043_50431101_55_dialog_content = "Hear, hear! Just because it's the same style of glove, does not necessarily mean it belongs to the original pair!",
  ui_story_5043_50431101_56_dialog_content = "In fact, I have been known to buy seven pairs of the exact same gloves from time to time!",
  ui_story_5043_50431101_57_dialog_content = "Leyn... Matthieu...",
  ui_story_5043_50431101_58_dialog_content = "Enough, judges. I've had my fill of ludicrous speculations for one day.",
  ui_story_5043_50431101_59_dialog_content = "If you have anything else to say, I suggest you save it for tomorrow's trial.",
  ui_story_5043_50431101_60_dialog_content = "But why? I just want to take a look...",
  ui_story_5043_50431101_61_dialog_content = "I said, IT IS ENOUGH.",
  ui_story_5043_50431101_62_dialog_content = "The suspect will be taken into solitary confinement shortly. No one will be allowed to see her until the start of tomorrow's proceedings.",
  ui_story_5043_50431101_63_dialog_content = "Solitary confinement?! Have you gone mad?!",
  ui_story_5043_50431101_64_dialog_content = "You have no right to place her in solitary confinement before her trial! That's against the law!",
  ui_story_5043_50431101_65_dialog_content = "As the chief judge of the Romance Division, I have been granted the sole authority to strike the gravel and decide who's guilty.",
  ui_story_5043_50431101_66_dialog_content = "Placing her in solitary confinement is but another necessary step in the process, or do you doubt the Hall of Justice and its laws?",
  ui_story_5043_50431101_67_dialog_content = "You—",
  ui_story_5043_50431101_68_dialog_content = "D-Don't be hasty, everyone!",
  ui_story_5043_50431101_69_dialog_content = "I'll go along with Judge Schwab's decision for now. We'll just have to dispute the accusations in court tomorrow.",
  ui_story_5043_50431101_70_dialog_content = "Tina...",
  ui_story_5043_50431101_71_dialog_content = "I'm a judge, so I have to believe that Lumopolis' justice system would never wrongfully punish an innocent person.",
  ui_story_5043_50431101_72_dialog_content = "I'm sure the truth will make itself clear during tomorrow's trial...",
  ui_story_5043_50431101_73_dialog_content = "Because I believe in the Romance Division.",
  ui_story_5043_50431101_74_dialog_content = "And I believe in all of you.",
  ui_story_5043_50431101_75_dialog_content = "...",
  ui_story_5043_50431101_76_dialog_content = "...",
  ui_story_5043_50431101_77_dialog_content = "Take her away, guards.",
  ui_story_5043_50431101_78_dialog_content = "Yes, sir!",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>Outside the Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431101_80_dialog_content = "They locked Tina up. What are we gonna do?",
  ui_story_5043_50431101_81_dialog_content = "You don't think they'll find her guilty tomorrow, do you?",
  ui_story_5043_50431101_82_dialog_content = "If things stay the way they are right now... they will.",
  ui_story_5043_50431101_83_dialog_content = "W-We can't let that happen! She's innocent!",
  ui_story_5043_50431101_84_dialog_content = "Is it just me, or did something about Schwab seem strange today?",
  ui_story_5043_50431101_85_dialog_content = "Huh?",
  ui_story_5043_50431101_86_dialog_content = "Well, I've always thought of him as a very strange person, but now that you mention it...",
  ui_story_5043_50431101_87_dialog_content = "His attitude today did seem a little extreme.",
  ui_story_5043_50431101_88_dialog_content = "He was very clearly opposing us, yes.",
  ui_story_5043_50431101_89_dialog_content = "He embellished any information that implicated Tina, and ignored all of our rebuttals.",
  ui_story_5043_50431101_90_dialog_content = "Precisely. It's too much to be just a coincidence, don't you think?",
  ui_story_5043_50431101_91_dialog_content = "The moment the incident occurred, his people just happened to come across that glove and submit it as evidence.",
  ui_story_5043_50431101_92_dialog_content = "It's almost as if he already knew where the other glove was...",
  ui_story_5043_50431101_93_dialog_content = "Not only that. He seemed to have a very detailed understanding of what happened at the crime scene.",
  ui_story_5043_50431101_94_dialog_content = "Remember that disgusting, self-satisfied look he had on his face?",
  ui_story_5043_50431101_95_dialog_content = "Really? Think carefully, all of you.",
  ui_story_5043_50431101_96_dialog_content = "When the incident occurred, was Judge Tina actually at your side in the fight against the Eclipsites?",
  ui_story_5043_50431101_97_dialog_content = "He was never there to begin with, so what gave him the confidence to ask us that?",
  ui_story_5043_50431101_98_dialog_content = "You're right!",
  ui_story_5043_50431101_99_dialog_content = "When you take all of these into account, the court's proceedings against Tina went way too smoothly today.",
  ui_story_5043_50431101_100_dialog_content = "Everything pointed to Tina being guilty without a doubt...",
  ui_story_5043_50431101_101_dialog_content = "But none of these things were as strange as his final decision.",
  ui_story_5043_50431101_102_dialog_content = "The decision to lock her away.",
  ui_story_5043_50431101_103_dialog_content = "I couldn't agree more.",
  ui_story_5043_50431101_104_dialog_content = "Finding that glove, knowing exactly what happened at the crime scene... He could explain these things easily—maybe there were lots of witnesses, or it was sheer luck.",
  ui_story_5043_50431101_105_dialog_content = "All the procedures were legitimate, and there would be no loose ends in his accusation.",
  ui_story_5043_50431101_106_dialog_content = "Indeed. But he had grown tired of proving himself in the end.",
  ui_story_5043_50431101_107_dialog_content = "He barred us from inspecting the evidence and locked Tina in solitary confinement without offering a reason.",
  ui_story_5043_50431101_108_dialog_content = "This means he's hiding something, something he cannot afford to let others see.",
  ui_story_5043_50431101_109_dialog_content = "Especially not us.",
  ui_story_5043_50431101_110_dialog_content = "It must be an important clue, for him to break the rules in order to cover it up.",
  ui_story_5043_50431101_111_dialog_content = "Something tells me that clue is the key to uncovering the truth and proving Tina's innocence!",
  ui_story_5043_50431101_112_dialog_content = "Wow! What a brilliant deduction!",
  ui_story_5043_50431101_113_dialog_content = "Watch your words.",
  ui_story_5043_50431101_114_dialog_content = "This is the gate of the Hall of Justice.",
  ui_story_5043_50431101_115_dialog_content = "O-Oh yeah, we should keep it down.",
  ui_story_5043_50431101_116_dialog_content = "So all we have to do is find out what Schwab is hiding from us, and we'll be able to prove Tina's innocence, right?",
  ui_story_5043_50431101_117_dialog_content = "It sounds easy when you put it that way, but I'm worried that we won't be able to figure it out in time.",
  ui_story_5043_50431101_118_dialog_content = "Huh?",
  ui_story_5043_50431101_119_dialog_content = "Schwab is definitely going to tie up any loose ends before the trial tomorrow.",
  ui_story_5043_50431101_120_dialog_content = "He knows what needs to be done to cover his tracks which we have no idea about.",
  ui_story_5043_50431101_121_dialog_content = "I'm sure he has plenty of contingencies lined up, in case something goes wrong.",
  ui_story_5043_50431101_122_dialog_content = "The odds of him succeeding are heavily in his favor.",
  ui_story_5043_50431101_123_dialog_content = "So what, are we just waiting until the trial and hoping for the best?!",
  ui_story_5043_50431101_124_dialog_content = "If we do, Tina will definitely be found guilty.",
  ui_story_5043_50431101_125_dialog_content = "Which means we need to dig up some clues before the trial begins.",
  ui_story_5043_50431101_126_dialog_content = "If we can't get to the bottom of Schwab's secret, we'll have to search for other clues.",
  ui_story_5043_50431101_127_dialog_content = "Hahaha, an interesting suggestion!",
  ui_story_5043_50431101_128_dialog_content = "And something tells me you already know where to start, don't you?",
  ui_story_5043_50431101_129_dialog_content = "Hey, you three better not do anything stupid, you hear me?",
  ui_story_5043_50431101_130_dialog_content = "Oh, come now, Loewe! We would never dream of it.",
  ui_story_5043_50431101_131_dialog_content = "... I still have more investigations, so I'll be leaving now.",
  ui_story_5043_50431101_132_dialog_content = "If you three get caught doing something stupid, I was never here, and we never had this conversation. Understand?",
  ui_story_5043_50431101_133_dialog_content = "You...",
  ui_story_5043_50431101_134_dialog_content = "It's better this way, Matthieu. More people would only get in the way.",
  ui_story_5043_50431101_135_dialog_content = "Now come closer, you two.",
  ui_story_5043_50431101_136_dialog_content = "Sure, what is it?",
  ui_story_5043_50431101_137_dialog_content = "If Schwab was willing to break the rules in order to hide his secret...",
  ui_story_5043_50431101_138_dialog_content = "We'll have to do the same if we want to beat him.",
  ui_story_5043_50431101_139_dialog_content = "But how exactly?",
  ui_story_5043_50431101_140_dialog_content = "We're going to break into Schwab's house.",
  ui_story_5043_50431101_141_dialog_content = "What?!",
  ui_story_5043_50431101_142_dialog_content = "If we can't get near the suspect or the evidence, we'll just have to go with the next best thing—Schwab himself.",
  ui_story_5043_50431101_143_dialog_content = "And his home is the safest place to keep his secrets.",
  ui_story_5043_50431101_144_dialog_content = "If he's truly hiding something important, that would be the best place to start looking.",
  ui_story_5043_50431101_145_dialog_content = "But... wouldn't that be against the law?",
  ui_story_5043_50431101_146_dialog_content = "This is interesting! What a wonderful idea!",
  ui_story_5043_50431101_147_dialog_content = "Then that settles it! Let's go pay the good judge's manor a visit!",
  ui_story_5043_50431101_148_dialog_content = "Guess I'm the only one who cares about the law anymore... Fine, I'm in.",
  ui_story_5043_50431101_149_dialog_content = "The only reason we're in this predicament is that our opponent did the same to us.",
  ui_story_5043_50431101_150_dialog_content = "When the time comes, I'll gladly take full responsibility for breaking into his house.",
  ui_story_5043_50431101_151_dialog_content = "But what matters most right now is making sure that Tina isn't punished for a crime she didn't commit.",
  ui_story_5043_50431101_152_dialog_content = "Hmph. Full responsibility, you say?",
  ui_story_5043_50431101_153_dialog_content = "Sigh, that kind of honesty is only going to cause problems for you in the future, you know.",
  ui_story_5043_50431101_154_dialog_content = "You're right... Proving Tina's innocence comes first!",
  ui_story_5043_50431101_155_dialog_content = "So should we get going now?",
  ui_story_5043_50431101_156_dialog_content = "There's still one last thing we have to do before that.",
  ui_story_5043_50431101_157_dialog_content = "I don't know if you two noticed, but those guards behind us have been following us for quite some time.",
  ui_story_5043_50431101_158_dialog_content = "Schwab must've ordered them to keep tabs on us. There's no way he just let us go.",
  ui_story_5043_50431101_159_dialog_content = "Looks like we'll just have to shake them off, then.",
  ui_story_5043_50431101_160_dialog_content = "My thoughts exactly.",
  ui_story_5043_50431101_161_dialog_content = "Should be easy enough. After all, I'm a pro when it comes to running away.",
  ui_story_5043_50431101_162_dialog_content = "Don't forget, I have an extra set of \"eyes\" on them.",
  ui_story_5043_50431101_163_dialog_content = "That's right! We can use your psychic abilities on them!",
  ui_story_5043_50431101_164_dialog_content = "So as our resident escape artist, what should be our first move?",
  ui_story_5043_50431101_165_dialog_content = "It's pretty simple, actually.",
  ui_story_5043_50431101_166_dialog_content = "The first step to running away—",
  ui_story_5043_50431101_167_dialog_content = "—is to start running!!!",
  ui_story_5043_50431102_1_dialog_content = "Turn right up ahead!",
  ui_story_5043_50431102_2_dialog_content = "Ah, this is positively exhausting.",
  ui_story_5043_50431102_3_dialog_content = "Well? Are there any guards following our trail?",
  ui_story_5043_50431102_4_dialog_content = "Nope! Not a single one!",
  ui_story_5043_50431102_5_dialog_content = "What? Then why are we still running?!",
  ui_story_5043_50431102_6_dialog_content = "A-Aren't we going to Schwab's home right now?",
  ui_story_5043_50431102_7_dialog_content = "I'm certain this is the right way.",
  ui_story_5043_50431102_8_dialog_content = "Yes, but if nobody is chasing after us, we can just walk the rest of the way there!",
  ui_story_5043_50431102_9_dialog_content = "Besides, how do you know his home is this way?",
  ui_story_5043_50431102_10_dialog_content = "Because I told him.",
  ui_story_5043_50431102_11_dialog_content = "We're low on time, so I thought running there would be quicker.",
  ui_story_5043_50431102_12_dialog_content = "You could have at least told me that we lost the guards! I was terrified that they were on our heels this entire time!!",
  ui_story_5043_50431102_13_dialog_content = "Alright, alright, keep your voice down. His house is just up ahead.",
  ui_story_5043_50431102_14_dialog_content = "Why, you...",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>Outside of the Salar Manor, Lumopolis Gardens</color>",
  ui_story_5043_50431102_16_dialog_content = "Looks like they have a lot of guards and servants posted at the entrance.",
  ui_story_5043_50431102_17_dialog_content = "How are we supposed to avoid them AND search for clues?",
  ui_story_5043_50431102_18_dialog_content = "You're right, it won't be easy.",
  ui_story_5043_50431102_19_dialog_content = "If any of them see us, we'll be sitting next to Tina on the dock tomorrow.",
  ui_story_5043_50431102_20_dialog_content = "Knowing that, are you two still willing to go through with this?",
  ui_story_5043_50431102_21_dialog_content = "This is our only choice if we want to prove Tina innocent...",
  ui_story_5043_50431102_22_dialog_content = "We must do it, no matter how dangerous it might be!",
  ui_story_5043_50431102_23_dialog_content = "There's one silver lining to this reckless scheme. Schwab's home is definitely large enough to afford us plenty of places to hide.",
  ui_story_5043_50431102_24_dialog_content = "With that and some psychic abilities, we should be able to avoid the dangers well enough.",
  ui_story_5043_50431102_25_dialog_content = "I'll make sure to keep a close eye on our surroundings! Just leave it to me!",
  ui_story_5043_50431102_26_dialog_content = "So how exactly do we set foot inside the manor?",
  ui_story_5043_50431102_27_dialog_content = "I'm not sure we have enough time to wait for the guards to change shifts...",
  ui_story_5043_50431102_28_dialog_content = "It doesn't matter, since we won't be entering through the front gate.",
  ui_story_5043_50431102_29_dialog_content = "Oh? Did you happen to see another gate, then?",
  ui_story_5043_50431102_30_dialog_content = "No, but look at that garden over there. It has plenty of hedges that we can use for cover.",
  ui_story_5043_50431102_31_dialog_content = "Once we're close enough, we'll just jump over the wall.",
  ui_story_5043_50431102_32_dialog_content = "Jump over the wall?!",
  ui_story_5043_50431102_33_dialog_content = "You're right! It's perfect for staying out of sight, and look, the wall's not that tall, either!",
  ui_story_5043_50431102_34_dialog_content = "Come on, let's get moving.",
  ui_story_5043_50431102_35_dialog_content = "Roger!",
  ui_story_5043_50431102_36_dialog_content = "W-Wait a minute, you two! Don't you think jumping the wall is a bit unbecoming?",
  ui_story_5043_50431102_37_dialog_content = "After all, I'm a proud member of the Sawyer—",
  ui_story_5043_50431102_38_dialog_content = "—Ugh, forget it. Honestly, you commoners are going to be the death of me.",
  ui_story_5043_50431201_1_dialog_content = "Ugh... Why must I do something so foolish...?",
  ui_story_5043_50431201_2_dialog_content = "Just grin and bear it, Matthieu. We're doing this to clear Tina's name.",
  ui_story_5043_50431201_3_dialog_content = "See? We've already made it into the manor!",
  ui_story_5043_50431201_4_dialog_content = "Everything looks so elegant here...",
  ui_story_5043_50431201_5_dialog_content = "So this is Schwab's home, huh?",
  ui_story_5043_50431201_6_dialog_content = "Yeah... I have to admit, it makes me feel a bit envious.",
  ui_story_5043_50431201_7_dialog_content = "The Salar Family is one of the most influential in all of Lumopolis.",
  ui_story_5043_50431201_8_dialog_content = "What we see here is only the tip of the iceberg when it comes to their wealth, I'm sure—",
  ui_story_5043_50431201_9_dialog_content = "Alright, give it a rest already. I think I see someone up ahead.",
  ui_story_5043_50431201_10_dialog_content = "Let's go take a look.",
  ui_story_5043_50431201_11_dialog_content = "Hey, I see them too!",
  ui_story_5043_50431201_12_dialog_content = "Wait, is that... Schwab?",
  ui_story_5043_50431201_13_dialog_content = "Forgive us, Master Schwab, we lost their trails.",
  ui_story_5043_50431201_14_dialog_content = "The Caelestite and the two judges used the winding paths to their advantage, so we couldn't catch up to them...",
  ui_story_5043_50431201_15_dialog_content = "Is this why I hired you fools, hmm?",
  ui_story_5043_50431201_16_dialog_content = "Useless! The lot of you!",
  ui_story_5043_50431201_17_dialog_content = "Forgive us, my lord!",
  ui_story_5043_50431201_18_dialog_content = "... Enough. What's done is done.",
  ui_story_5043_50431201_19_dialog_content = "Now that they're on the run, perhaps some good will come of your idiotic mistake.",
  ui_story_5043_50431201_20_dialog_content = "Return to your posts.",
  ui_story_5043_50431201_21_dialog_content = "Yes, Master Schwab!",
  ui_story_5043_50431201_22_dialog_content = "So his men were spying on us... Hah! As if I would let him do as he pleases!",
  ui_story_5043_50431201_23_dialog_content = "I'm just glad we managed to find Schwab so quickly.",
  ui_story_5043_50431201_24_dialog_content = "Let's keep following him, and see what he's gonna do.",
  ui_story_5043_50431201_25_dialog_content = "Any changes in his behavior might provide us with the clues we need!",
  ui_story_5043_50431201_26_dialog_content = "Roger!",
  ui_story_5043_50431201_27_dialog_content = "Lest you two forget, Schwab is not a man who can be easily understood.",
  ui_story_5043_50431201_28_dialog_content = "If he's willing to break the law before the entire Hall of Justice, who knows what unspeakable acts he is capable of performing in the privacy of his own home...",
  ui_story_5043_50431201_29_dialog_content = "O-Okay, now you're starting to scare me.",
  ui_story_5043_50431201_30_dialog_content = "Good. Your fear will keep you on your toes.",
  ui_story_5043_50431201_31_dialog_content = "Come, let's not lose sight of him.",
  ui_story_5043_50431201_32_dialog_content = "Your tea, my lord.",
  ui_story_5043_50431201_33_dialog_content = "Good, give it here.",
  ui_story_5043_50431201_34_dialog_content = "The kitchen is preparing some desserts. Shall I bring you a plate, Master?",
  ui_story_5043_50431201_35_dialog_content = "That won't be necessary. I have other matters to attend to right now.",
  ui_story_5043_50431201_36_dialog_content = "Do not disturb me until I have finished with them.",
  ui_story_5043_50431201_37_dialog_content = "Y-Yes, Master Schwab!",
  ui_story_5043_50431201_38_dialog_content = "He sent his servant away.",
  ui_story_5043_50431201_39_dialog_content = "Shhh... Could these matters be so wicked that even his own people cannot be privy to them?",
  ui_story_5043_50431201_40_dialog_content = "Er... M-Maybe he just wants to be alone for a while?",
  ui_story_5043_50431201_41_dialog_content = "Honestly, PlayerName... Have you no imagination?",
  ui_story_5043_50431201_42_dialog_content = "Did I, or did I not just say that Schwab is not a man who can be easily understood?",
  ui_story_5043_50431201_43_dialog_content = "Fine, fine. I get it.",
  ui_story_5043_50431201_44_dialog_content = "Still, how bad could it be? What could a complicated man like him possibly do in his own garden?",
  ui_story_5043_50431201_45_dialog_content = "Look! He's raising his hand now!",
  ui_story_5043_50431201_46_dialog_content = "It looks like he's holding something.",
  ui_story_5043_50431201_47_dialog_content = "It's a needle! He has a needle in his hand!",
  ui_story_5043_50431201_48_dialog_content = "A needle?!",
  ui_story_5043_50431201_49_dialog_content = "For what purpose? Does he mean to use it on himself?!",
  ui_story_5043_50431201_50_dialog_content = "No, not on himself...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>Stab!</color>",
  ui_story_5043_50431201_52_dialog_content = "He's using it on that doll in his other hand...",
  ui_story_5043_50431201_53_dialog_content = "Wh-Why is he doing that to a doll?!",
  ui_story_5043_50431201_54_dialog_content = "I've heard of this before... A type of curse involving the use of dolls.",
  ui_story_5043_50431201_55_dialog_content = "A curse?",
  ui_story_5043_50431201_56_dialog_content = "It works by taking something from a person's body, usually hair or blood, and placing it inside a doll.",
  ui_story_5043_50431201_57_dialog_content = "By doing so, the doll becomes spiritually linked to that person.",
  ui_story_5043_50431201_58_dialog_content = "Pricking or harming the doll inflicts the same pain and injuries on the target of the curse.",
  ui_story_5043_50431201_59_dialog_content = "And eventually, the person would die an excruciatingly painful death!",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>Stab!</color>",
  ui_story_5043_50431201_61_dialog_content = "Tsk, he did it again!",
  ui_story_5043_50431201_62_dialog_content = "I think I've heard of curses like that, but I never expected someone like Schwab to dabble in the dark arts...",
  ui_story_5043_50431201_63_dialog_content = "Well, I don't find it surprising at all. I've long since seen through his gentle, noble charade!",
  ui_story_5043_50431201_64_dialog_content = "I don't know... Curses like this are usually just some creepy superstition, right?",
  ui_story_5043_50431201_65_dialog_content = "Besides, this would be an egregious violation of Lumopolis' faith...",
  ui_story_5043_50431201_66_dialog_content = "I see. It doesn't matter if the curse is real or not. What matters is whether or not people believe in it.",
  ui_story_5043_50431201_67_dialog_content = "And it's clear to me that Schwab believes in it.",
  ui_story_5043_50431201_68_dialog_content = "Which means that somewhere in the world... There's a person who Schwab hates enough to want to kill them...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>Stab!</color>",
  ui_story_5043_50431201_70_dialog_content = "But who? Who could it be?!",
  ui_story_5043_50431201_71_dialog_content = "Who could have wronged him so badly, that he would wish death on them?",
  ui_story_5043_50431201_72_dialog_content = "I have no idea... But it really makes you wonder, doesn't it?",
  ui_story_5043_50431201_73_dialog_content = "By most accounts, Schwab lives a near-perfect life... I can't imagine who could ruin that for him.",
  ui_story_5043_50431201_74_dialog_content = "Unless... his hatred comes from a place where no one can easily see it.",
  ui_story_5043_50431201_75_dialog_content = "When you put it that way... Yes, it makes perfect sense now!",
  ui_story_5043_50431201_76_dialog_content = "Clearly, his anger stems from a long-lost yet unforgettable <color=#FFB400>love</color>!",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>Stab!</color>",
  ui_story_5043_50431201_78_dialog_content = "If that's true, we need to do something about it right away! It could mean the difference between life and death for someone out there!",
  ui_story_5043_50431201_79_dialog_content = "Let's not be hasty. We must wait for him to show clear and undeniable evidence of wrongdoing before we can interfere.",
  ui_story_5043_50431201_80_dialog_content = "What could we do right now, given our current knowledge? Stop him from pricking that poor doll?",
  ui_story_5043_50431201_81_dialog_content = "Hey, you don't think those superstitions are true... do you?",
  ui_story_5043_50431201_82_dialog_content = "You mean using a doll to curse someone?",
  ui_story_5043_50431201_83_dialog_content = "Yeah...",
  ui_story_5043_50431201_84_dialog_content = "Because if they are, it's possible...",
  ui_story_5043_50431201_85_dialog_content = "... that we're witnessing a murder scene!",
  ui_story_5043_50431201_86_dialog_content = "Now for the finishing touch...",
  ui_story_5043_50431201_87_dialog_content = "Let this tiny, wretched existence...",
  ui_story_5043_50431201_88_dialog_content = "We have to stop him! Hurry!",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>Stab!</color>",
  ui_story_5043_50431201_90_dialog_content = "—be reborn!!!",
  ui_story_5043_50431201_91_dialog_content = "My... You're a cute one, aren't you?",
  ui_story_5043_50431201_92_dialog_content = "Now then, what should I name you? How about... Chestnut?",
  ui_story_5043_50431201_93_dialog_content = "S-So that's... a stuffed hedgehog?",
  ui_story_5043_50431201_94_dialog_content = "That sure does look like a hedgehog.",
  ui_story_5043_50431201_95_dialog_content = "He even gave it a fitting name. See? It does look like a little chestnut.",
  ui_story_5043_50431201_96_dialog_content = "<size=45>So what are we freaking out about?!?</size>",
  ui_story_5043_50431201_97_dialog_content = "Shhh! Quiet, PlayerName!",
  ui_story_5043_50431201_98_dialog_content = "Sigh... I can't believe how stupid we are, talking about Schwab murdering someone.",
  ui_story_5043_50431201_99_dialog_content = "Er, well, trial and error is just a natural part of an investigation.",
  ui_story_5043_50431201_100_dialog_content = "Only by eliminating all other possibilities will the truth reveal itself. It's all a part of the process.",
  ui_story_5043_50431201_101_dialog_content = "Whatever helps you sleep at night, Leyn...",
  ui_story_5043_50431201_102_dialog_content = "Ahem... Anyway, let's just forget about our conversation just now and focus on helping Tina.",
  ui_story_5043_50431201_103_dialog_content = "Schwab's going back inside now, most likely to prepare for tomorrow's trial.",
  ui_story_5043_50431201_104_dialog_content = "We should go take a closer look.",
  ui_story_5043_50431201_105_dialog_content = "Sigh, it appears my little experiment is still far from complete. Perhaps I'll make more progress today...?",
  ui_story_5043_50431201_106_dialog_content = "Did you hear that? An experiment!",
  ui_story_5043_50431201_107_dialog_content = "Yeah, what could he possibly be researching in there?",
  ui_story_5043_50431201_108_dialog_content = "Nothing good, I presume. After all, he's a difficult man to understand.",
  ui_story_5043_50431201_109_dialog_content = "Not this again, Matthieu...",
  ui_story_5043_50431201_110_dialog_content = "Let's not jump to any crazy conclusions again. Not after the last time.",
  ui_story_5043_50431201_111_dialog_content = "Maybe it's just a small, at-home experiment? It could be a hobby of his...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_113_dialog_content = "Wow!",
  ui_story_5043_50431201_114_dialog_content = "Was that an explosion?! What in the blazes is he doing in there?!",
  ui_story_5043_50431201_115_dialog_content = "I-I don't know. Should we get a little closer and see?",
  ui_story_5043_50431201_116_dialog_content = "How? There's nowhere to hide in that room!",
  ui_story_5043_50431201_117_dialog_content = "If we get any closer than we are now, our cover will be blown...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_119_dialog_content = "Another explosion! Could it be he's making a bomb?!",
  ui_story_5043_50431201_120_dialog_content = "A bomb?! W-Wait, we're jumping to conclusions again!",
  ui_story_5043_50431201_121_dialog_content = "And why not? This is more or less the family business of the Salars!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_123_dialog_content = "But why would he be researching explosives?",
  ui_story_5043_50431201_124_dialog_content = "Well, the more intricately designed a place is, the more susceptible it is to explosives. Lumopolis is no exception.",
  ui_story_5043_50431201_125_dialog_content = "Think about it: someone would come to court for the vandalism of the statues.",
  ui_story_5043_50431201_126_dialog_content = "What if it is a clocktower or a church? The consequences would be far more unimaginable.",
  ui_story_5043_50431201_127_dialog_content = "By harnessing the destructive power of bombs, they can use fear to force others to obey them!",
  ui_story_5043_50431201_128_dialog_content = "I don't know... His \"bomb\" didn't put so much as a scratch on his house.",
  ui_story_5043_50431201_129_dialog_content = "Which is why he called it his \"little experiment\"!",
  ui_story_5043_50431201_130_dialog_content = "Once he fully understands the science behind it, he can use Luminatics to make his bombs a hundred times more powerful!",
  ui_story_5043_50431201_131_dialog_content = "If he succeeds, Schwab could upend our entire society as we know it!",
  ui_story_5043_50431201_132_dialog_content = "All of Lumopolis could even fall under his control...",
  ui_story_5043_50431201_133_dialog_content = "I-Is it really that serious?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_135_dialog_content = "Cough, cough...",
  ui_story_5043_50431201_136_dialog_content = "Ah, another failed attempt.",
  ui_story_5043_50431201_137_dialog_content = "Who knew that making <color=#FFB400>caramel pudding</color> could be so difficult?",
  ui_story_5043_50431201_138_dialog_content = "...",
  ui_story_5043_50431201_139_dialog_content = "So, you're saying he's gonna take over Lumopolis... with PUDDING?!?",
  ui_story_5043_50431201_140_dialog_content = "I-Is he some kind of idiot?! How does he manage to produce explosions while baking desserts?!",
  ui_story_5043_50431201_141_dialog_content = "Here's a better question: how could both of your guesses be so completely and utterly wrong?!",
  ui_story_5043_50431201_142_dialog_content = "Shhh! He's coming back outside! Quick, hide!",
  ui_story_5043_50431201_143_dialog_content = "Sigh... Another waste of time and effort.",
  ui_story_5043_50431201_144_dialog_content = "Perhaps it's time to do something more productive? Now where did I put that cellar key... Ah, here it is.",
  ui_story_5043_50431201_145_dialog_content = "I should check things one last time before tomorrow's trial...",
  ui_story_5043_50431201_146_dialog_content = "Pardon me, Master Schwab, but dinner is ready.",
  ui_story_5043_50431201_147_dialog_content = "Did I not make it perfectly clear that I do not wish to be disturbed right now?!",
  ui_story_5043_50431201_148_dialog_content = "F-Forgive me, Master! I meant no offense... But the food is already on the table...",
  ui_story_5043_50431201_149_dialog_content = "Ugh... Very well, but let this be the last time you interrupt me!",
  ui_story_5043_50431201_150_dialog_content = "Schwab went to dinner. I don't think we'll be able to follow him over there, not with all of those servants around.",
  ui_story_5043_50431201_151_dialog_content = "Did you hear what he said before he left?",
  ui_story_5043_50431201_152_dialog_content = "Let me guess, it has something to do with him being \"difficult to understand\"?",
  ui_story_5043_50431201_153_dialog_content = "Very funny, but no—he mentioned something about a cellar.",
  ui_story_5043_50431201_154_dialog_content = "Do use your brains for once, would you? Right before he was called to dinner, he pulled out a key to the manor's cellar.",
  ui_story_5043_50431201_155_dialog_content = "And look! He left that key in the lock over there!",
  ui_story_5043_50431201_156_dialog_content = "Shall we take a look inside? Who knows what secrets we'll find just beyond that door!",
  ui_story_5043_50431201_157_dialog_content = "It does seem like the perfect opportunity and all, but...",
  ui_story_5043_50431201_158_dialog_content = "We still haven't found anything that'll help us prove Tina's innocence! I don't know if breaking into Schwab's cellar is the right idea.",
  ui_story_5043_50431201_159_dialog_content = "If you truly believe she's innocent, then the truth has to be here in Schwab's house somewhere.",
  ui_story_5043_50431201_160_dialog_content = "Even if he's just a pawn in all of this, there must be some sort of clue left behind.",
  ui_story_5043_50431201_161_dialog_content = "If we haven't found it yet, it's because we haven't dug deep enough!",
  ui_story_5043_50431201_162_dialog_content = "... You're right. There's no going back now... So let's go see what's in that cellar!",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5043_50431201_164_dialog_content = "It's black as pitch in there... I can't see a thing!",
  ui_story_5043_50431201_165_dialog_content = "There appears to be a staircase leading further down. We can try feeling our way forward...",
  ui_story_5043_50431201_166_dialog_content = "Tina? Tina! Are you in here?",
  ui_story_5043_50431201_167_dialog_content = "Wait... I thought PlayerName had some psychic powers?",
  ui_story_5043_50431201_168_dialog_content = "Can you use them to sense what lies ahead?",
  ui_story_5043_50431201_169_dialog_content = "I can try, yeah.",
  ui_story_5043_50431201_170_option_content = "Force Boost",
  ui_story_5043_50431201_171_dialog_content = "Having a Caelestite at one's side can prove quite useful at times, no?",
  ui_story_5043_50431201_172_dialog_content = "Well? What do you see?",
  ui_story_5043_50431201_173_dialog_content = "Are there any light sources we can use, like candles or a torch?",
  ui_story_5043_50431201_174_dialog_content = "This cellar seems to go down really far...",
  ui_story_5043_50431201_175_dialog_content = "... Huh? Something's heading our way!",
  ui_story_5043_50431201_176_dialog_content = "Is that...",
  ui_story_5043_50431201_177_dialog_content = "Graaaah—",
  ui_story_5043_50431201_178_dialog_content = "Wahhhhhhhh—",
  ui_story_5043_50431201_179_dialog_content = "What is it? What did you see?!",
  ui_story_5043_50431201_180_dialog_content = "R-Run! Get back to the entrance!",
  ui_story_5043_50431201_181_dialog_content = "A mob of Eclipsites is charging toward us!",
  ui_story_5043_50431202_1_dialog_content = "Graah...",
  ui_story_5043_50431202_2_dialog_content = "Eclipsites? What are these filthy creatures doing in Schwab's basement?!",
  ui_story_5043_50431202_3_dialog_content = "Apparently, nobles are fond of more than just the finer things in life!",
  ui_story_5043_50431202_4_dialog_content = "Don't lump us all together with your vile slander! I'll have you know my family would never harbor such disgusting monsters in our home!",
  ui_story_5043_50431202_5_dialog_content = "Enough, you guys! They're getting closer!",
  ui_story_5043_50431202_6_dialog_content = "I'll hold off on the Eclipsites! You two get out of here as fast as you can!",
  ui_story_5043_50431202_7_dialog_content = "A-Are you sure?",
  ui_story_5043_50431202_8_dialog_content = "Of course I am! Don't underestimate a Lumopolis judge!",
  ui_story_5043_50431202_9_dialog_content = "Alright, you Eclipsite scum... Take this!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>Crash—!</color>",
  ui_story_5043_50431202_11_dialog_content = "Oh, dear! You just broke their chandelier!",
  ui_story_5043_50431202_12_dialog_content = "It looks to be crafted from Northland crystals? Meaning it was quite an expensive fixture.",
  ui_story_5043_50431202_13_dialog_content = "Whoops! Think they'll ask me to pay for it...?",
  ui_story_5043_50431202_14_dialog_content = "You're worried about money at a time like this?! Focus on the Eclipsites!",
  ui_story_5043_50431202_15_dialog_content = "Here they come again...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>Crash—!</color>",
  ui_story_5043_50431202_17_dialog_content = "Great! Now their tea table is ruined too!",
  ui_story_5043_50431202_18_dialog_content = "And judging from its exquisite craftsmanship, I'm sure Schwab is going to lose sleep over it as well.",
  ui_story_5043_50431202_19_dialog_content = "I-I'm really sorry! But I don't think I'm the one to pay, since it's the Eclipsites' fault in the first place...",
  ui_story_5043_50431202_20_dialog_content = "Now's not the time, you two! Look, there's the door!",
  ui_story_5043_50431202_21_dialog_content = "We need to leave right now!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>Ten minutes later...</color>",
  ui_story_5043_50431202_23_dialog_content = "We've searched the entire perimeter of the estate, Master Schwab... But still no sign of any intruders.",
  ui_story_5043_50431202_24_dialog_content = "What a mess... Who or what could have caused all of this?",
  ui_story_5043_50431202_25_dialog_content = "... You're certain you saw no intruders?",
  ui_story_5043_50431202_26_dialog_content = "Yes, Master. Everything appears safe, at least for the time being.",
  ui_story_5043_50431202_27_dialog_content = "It's quite possible that the culprit or culprits are experts... If they left any clues behind, we have yet to find them.",
  ui_story_5043_50431202_28_dialog_content = "Perhaps it would be best to... leave this to the Hall of Justice?",
  ui_story_5043_50431202_29_dialog_content = "Surely, they would investigate the matter with all due seriousness, given your status?",
  ui_story_5043_50431202_30_dialog_content = "An investigation...",
  ui_story_5043_50431202_31_dialog_content = "No, that won't be necessary.",
  ui_story_5043_50431202_32_dialog_content = "It was merely a few pieces of furniture after all. What was lost can be easily replaced.",
  ui_story_5043_50431202_33_dialog_content = "For now, have someone clean up this mess right away.",
  ui_story_5043_50431202_34_dialog_content = "Yes, Lord Schwab!",
  ui_story_5043_50431202_35_dialog_content = "(The cellar door is open...)",
  ui_story_5043_50431202_36_dialog_content = "(Did I unlock it before I left for dinner?)",
  ui_story_5043_50431202_37_dialog_content = "(For me to make such a foolish mistake... It's almost unfathomable.)",
  ui_story_5043_50431202_38_dialog_content = "(I should go to bed early tonight. I'll need a clear head for tomorrow's trial.)",
  ui_story_5043_50431202_39_dialog_content = "Sigh, what on earth happened here?",
  ui_story_5043_50431202_40_dialog_content = "What kind of villain breaks into someone's home, just to destroy their chandelier and tea table?",
  ui_story_5043_50431202_41_dialog_content = "Still... these broken bits might fetch a good price with the right junk dealer.",
  ui_story_5043_50431202_42_dialog_content = "Huff, huff...",
  ui_story_5043_50431202_43_dialog_content = "(Finally... finally out!)",
  ui_story_5043_50431202_44_dialog_content = "Did anyone manage to follow us?",
  ui_story_5043_50431202_45_dialog_content = "I don't think so. It looks like the coast is clear.",
  ui_story_5043_50431202_46_dialog_content = "Tsk. How embarrassing—an entire day, wasted on pointless shenanigans.",
  ui_story_5043_50431202_47_dialog_content = "What's worse is that we couldn't find Tina, or even the smallest clue that could help her.",
  ui_story_5043_50431202_48_dialog_content = "How is she supposed to make it through the trial now?",
  ui_story_5043_50431202_49_dialog_content = "We've done all we can... All that remains is for us to fulfill our duties as judges.",
  ui_story_5043_50431202_50_dialog_content = "Before the trial begins, we need to take into account everything that has happened today.",
  ui_story_5043_50431202_51_dialog_content = "It's possible that the clues we're looking for are hidden in the details somewhere.",
  ui_story_5043_50431202_52_dialog_content = "It goes without saying that we'll perform our duties to the best of our abilities. However...",
  ui_story_5043_50431202_53_dialog_content = "Without definitive proof, we're as powerless as anyone else to change the outcome of the trial.",
  ui_story_5043_50431202_54_dialog_content = "Not to mention, we have no idea what other tricks Schwab still has up his sleeve.",
  ui_story_5043_50431202_55_dialog_content = "To go to trial against him like this would be hopeless, to say the least.",
  ui_story_5043_50431202_56_dialog_content = "There's more than one way to win, Matthieu.",
  ui_story_5043_50431202_57_dialog_content = "We may not have all the cards we need in our hand, but that doesn't mean we're out of the game just yet.",
  ui_story_5043_50431202_58_dialog_content = "My, my, feeling so sure about ourselves, aren't we?",
  ui_story_5043_50431202_59_dialog_content = "Not in ourselves, but in the truth.",
  ui_story_5043_50431202_60_dialog_content = "One side's job is to conceal the truth, while the other's is to reveal it. Knowing that, we have a clear advantage in the case.",
  ui_story_5043_50431202_61_dialog_content = "Besides, our little trip to Schwab's home wasn't entirely fruitless...",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>The Next Day</color>",
  ui_story_5043_50431301_2_dialog_content = "(So it's finally about to begin...)",
  ui_story_5043_50431301_3_dialog_content = "(The trial of Serial Statue Decapitations will be in session soon.)",
  ui_story_5043_50431301_4_dialog_content = "(Leyn, Matthieu, and Tina... Will they be able to expose the truth before the court?)",
  ui_story_5043_50431301_5_dialog_content = "PlayerName!",
  ui_story_5043_50431301_6_dialog_content = "Carleen! And Loewe too!",
  ui_story_5043_50431301_7_dialog_content = "You made it back!",
  ui_story_5043_50431301_8_dialog_content = "Of course. I gave everyone my word that I would be here for the trial, didn't I?",
  ui_story_5043_50431301_9_dialog_content = "However, something troubling was brought to my attention...",
  ui_story_5043_50431301_10_dialog_content = "I hear that Tina is the defendant?",
  ui_story_5043_50431301_11_dialog_content = "Matthieu, you've really outdone yourself this time.",
  ui_story_5043_50431301_12_dialog_content = "I dare you to say that again...!",
  ui_story_5043_50431301_13_dialog_content = "Th-That's right, yeah...",
  ui_story_5043_50431301_14_dialog_content = "Tina was named the prime suspect in the case after some pieces of bizarre evidence came to light.",
  ui_story_5043_50431301_15_dialog_content = "But I'm positive everything will turn out okay!",
  ui_story_5043_50431301_16_dialog_content = "What exactly happened in the last two days?",
  ui_story_5043_50431301_17_dialog_content = "It's kind of a long story. I'll tell you more once we're inside the courtroom.",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>The Hall of Justice, Romance Division, Lumopolis Gardens</color>",
  ui_story_5043_50431301_19_dialog_content = "Order, order!",
  ui_story_5043_50431301_20_dialog_content = "First, allow me to apologize to everyone for having to make so many trips to the courthouse for this case.",
  ui_story_5043_50431301_21_dialog_content = "Unfortunately, we were unable to prevent the culprit from committing multiple instances of this heinous crime.",
  ui_story_5043_50431301_22_dialog_content = "It appears that today is the day that this villain is finally brought to justice!",
  ui_story_5043_50431301_23_dialog_content = "Now, without further ado—",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431301_25_dialog_content = "The trial of Serial Statue Decapitations is now in session!",
  ui_story_5043_50431301_26_dialog_content = "...",
  ui_story_5043_50431301_27_dialog_content = "...",
  ui_story_5043_50431301_28_dialog_content = "<size=30>You guys...</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>Believe in them. It's all we can do now.</size>",
  ui_story_5043_50431301_30_dialog_content = "First, let us introduce the parties involved in today's litigation!",
  ui_story_5043_50431301_31_dialog_content = "For the prosecution, Mr. Byron.",
  ui_story_5043_50431301_32_dialog_content = "And for the defense, Tina Campbell.",
  ui_story_5043_50431301_33_dialog_content = "It brings us no small measure of shame, to see one of our own Romance Division judges stand trial for such a vile crime. But all are equal in the eyes of the law, and all must be held accountable for their sins.",
  ui_story_5043_50431301_34_dialog_content = "Unbelievable...",
  ui_story_5043_50431301_35_dialog_content = "I, Schwab Salar, shall preside as the chief judge in today's trial.",
  ui_story_5043_50431301_36_dialog_content = "Judges Matthieu Sawyer and Leyn will join the trial, as well as other respected members of the jury.",
  ui_story_5043_50431301_37_dialog_content = "Hmph, you've finally learned to show some respect to the elders.",
  ui_story_5043_50431301_38_dialog_content = "Our contributions to the investigation are just as important as anyone else's!",
  ui_story_5043_50431301_39_dialog_content = "Tell me, what are your thoughts on the case thus far?",
  ui_story_5043_50431301_40_dialog_content = "...",
  ui_story_5043_50431301_41_dialog_content = "...",
  ui_story_5043_50431301_42_dialog_content = "Ah yes, I nearly forgot we are to hold our silence for now...",
  ui_story_5043_50431301_43_dialog_content = "The basic details of the case are outlined in the documents placed in front of you. Everyone is invited to review them at their own discretion.",
  ui_story_5043_50431301_44_dialog_content = "Thanks in no small part to our thorough investigative efforts, we have finally established a clear chain of events.",
  ui_story_5043_50431301_45_dialog_content = "Next, I shall deliver a brief statement on the findings of said investigative efforts concerning the case of the Serial Statue Decapitations.",
  ui_story_5043_50431301_46_dialog_content = "Our findings show that the defendant, Tina Campbell, resorted to the destruction of statues to publicize her deep resentment towards the wave of love sweeping all of Lumopolis.",
  ui_story_5043_50431301_47_dialog_content = "In the previous two incidents, she misused her authority as a judge to destroy any evidence pointing to her wrongdoing.",
  ui_story_5043_50431301_48_dialog_content = "But thanks to Mr. Byron and his timely report, Judge Leyn was fully prepared for the third and final incident.",
  ui_story_5043_50431301_49_dialog_content = "And it was at the scene of the crime, that he was able to obtain a piece of vital evidence from the perpetrator...",
  ui_story_5043_50431301_50_dialog_content = "This glove!",
  ui_story_5043_50431301_51_dialog_content = "Splendid! This should be more than enough to incriminate the defendant!",
  ui_story_5043_50431301_52_dialog_content = "Indeed. I launched an investigation into the owner of this glove, and my subordinates stumbled upon a startling discovery—the other glove was found in the drawer of a desk belonging to none other than Judge Tina Campbell!",
  ui_story_5043_50431301_53_dialog_content = "Why, it's a perfect match!",
  ui_story_5043_50431301_54_dialog_content = "And our investigation confirmed just as much. Both gloves were part of a set belonging to a single owner...",
  ui_story_5043_50431301_55_dialog_content = "And that owner stands before us today, in the defendant's seat—Tina Campbell!",
  ui_story_5043_50431301_56_dialog_content = "It's not like that...",
  ui_story_5043_50431301_X56_dialog_content = "Wow! Chief Judge Schwab is badass beyond his years!",
  ui_story_5043_50431301_57_dialog_content = "Based on the irrefutable evidence provided, the court hereby proposes that the defendant be charged with the destruction of public property, as well as the subversion of romance!",
  ui_story_5043_50431301_58_dialog_content = "Naturally, you are free to justify your abhorrent behavior however you see fit.",
  ui_story_5043_50431301_59_dialog_content = "Just know that nothing short of divine intervention will sway the jury into clearing you of all charges.",
  ui_story_5043_50431301_60_dialog_content = "Why, you...",
  ui_story_5043_50431301_61_dialog_content = "I hardly think that's possible!",
  ui_story_5043_50431301_62_dialog_content = "The most important quality us here when presiding over a case is impartiality!",
  ui_story_5043_50431301_63_dialog_content = "Isn't that right, my fellow jurors?",
  ui_story_5043_50431301_64_dialog_content = "...",
  ui_story_5043_50431301_65_dialog_content = "...",
  ui_story_5043_50431301_66_dialog_content = "I don't know what else to say about that glove...",
  ui_story_5043_50431301_67_dialog_content = "It's true that it belongs to me, but I never took it to the crime scene.",
  ui_story_5043_50431301_68_dialog_content = "I was fighting off Eclipsites at the time, and had no way of going near that statue, much less defacing it.",
  ui_story_5043_50431301_69_dialog_content = "By the time I got to the statue, the damage was already done...",
  ui_story_5043_50431301_70_dialog_content = "Are there any witnesses who can attest to that?",
  ui_story_5043_50431301_71_dialog_content = "I...",
  ui_story_5043_50431301_72_dialog_content = "I'm sorry, but I had gotten separated from everyone at the time, so there were no witnesses...",
  ui_story_5043_50431301_73_dialog_content = "Then it seems your testimony is unable to overturn our current conclusion.",
  ui_story_5043_50431301_74_dialog_content = "If you have no other compelling evidence to offer, then for the crimes of the destruction of public property and subversion of love, we hereby find you—",
  ui_story_5043_50431301_75_dialog_content = "<size=45>Wait!!!</size>",
  ui_story_5043_50431301_76_dialog_content = "... Yes, Judge Matthieu?",
  ui_story_5043_50431301_77_dialog_content = "I fear I must object to your ruling, Judge Schwab!",
  ui_story_5043_50431301_78_dialog_content = "Tina couldn't possibly be the culprit behind these serial statue decapitations! She has evidence that proves she was never at the scene of the crime!",
  ui_story_5043_50431301_79_dialog_content = "Heh, does she, now?",
  ui_story_5043_50431301_80_dialog_content = "Then let us hear what you have to say, Judge Matthieu.",
  ui_story_5043_50431301_81_dialog_content = "And do remember to be as rational and objective as possible in her defense.",
  ui_story_5043_50431301_82_dialog_content = "Otherwise, we may find evidence of accomplices in her crimes instead.",
  ui_story_5043_50431301_83_dialog_content = "Ahem. Let us go back to the very beginning of the case.",
  ui_story_5043_50431301_84_dialog_content = "Namely, the first incident of a statue being decapitated.",
  ui_story_5043_50431301_85_dialog_content = "I have already thoroughly investigated the culprits' actions that day.",
  ui_story_5043_50431301_86_dialog_content = "Unfortunately, the defendant cannot prove that she was not at the crime scene.",
  ui_story_5043_50431301_87_dialog_content = "No, Your Honor... But what matters most is what happened AFTER the crime was committed!",
  ui_story_5043_50431301_88_dialog_content = "That afternoon, Tina and I were at the Hall of Justice, where we worked together for approximately four hours.",
  ui_story_5043_50431301_89_dialog_content = "I can personally attest to this, as can the other members of the Hall who were present that day.",
  ui_story_5043_50431301_90_dialog_content = "Very well, so you worked together for four hours. What then?",
  ui_story_5043_50431301_91_dialog_content = "She could have easily perpetrated the crime before returning to work with you in the Hall of Justice.",
  ui_story_5043_50431301_92_dialog_content = "Wrong, Your Honor! Those four hours are proof positive that she was never at the scene of the crime!",
  ui_story_5043_50431301_93_dialog_content = "You see, Tina suffers from a rare form of hypersomnia. Any hospital in Lumopolis can attest to this as well.",
  ui_story_5043_50431301_94_dialog_content = "As a result, the longest she can remain awake during any given day is approximately four hours!",
  ui_story_5043_50431301_95_dialog_content = "...",
  ui_story_5043_50431301_96_dialog_content = "In other words, outside of the four hours that we spent working together, she had to have been asleep the rest of the time!",
  ui_story_5043_50431301_97_dialog_content = "As such, there's no way she could have vandalized the first statue!",
  ui_story_5043_50431301_98_dialog_content = "She's even sleeping at work!?",
  ui_story_5043_50431301_99_dialog_content = "Does she have no shame? Can anyone really just get paid to do nothing these days?",
  ui_story_5043_50431301_100_dialog_content = "That's right! I was asleep at the time!",
  ui_story_5043_50431301_101_dialog_content = "I didn't hear about the statue until after I had woken up.",
  ui_story_5043_50431301_102_dialog_content = "Well, then? Is that proof that she is not to blame for the first statue?",
  ui_story_5043_50431301_103_dialog_content = "You call that an argument?",
  ui_story_5043_50431301_104_dialog_content = "Using mere speculation to not only establish an alibi for the defendant, but also pass judgment on her entire trial!",
  ui_story_5043_50431301_105_dialog_content = "If our justice system were so frivolous, we would have no need for things such as evidence or testimonies!",
  ui_story_5043_50431301_106_dialog_content = "I understand, Your Honor! You wish to see evidence, yes?",
  ui_story_5043_50431301_107_dialog_content = "Then allow me to move on to the second instance of statue decapitation.",
  ui_story_5043_50431301_108_dialog_content = "Just as the first incident, there's sufficient evidence here proving Tina Campbell was not at the crime scene.",
  ui_story_5043_50431301_109_dialog_content = "For this, Judge Leyn and I can both serve as witnesses.",
  ui_story_5043_50431301_110_dialog_content = "Hmph! Are you sure you meant to say witnesses and not accomplices, Judge Matthieu?",
  ui_story_5043_50431301_111_dialog_content = "My, my, as respected judges of the Hall of Justice, are we not all on the same side, Your Honor?",
  ui_story_5043_50431301_112_dialog_content = "Ah, but no matter... There is one other person here today who can also serve as a witness.",
  ui_story_5043_50431301_113_dialog_content = "And I believe someone in her position would more than suffice to prove Tina's innocence.",
  ui_story_5043_50431301_114_dialog_content = "Unless, of course, you mean to imply that the Princess of Lumopolis is also an accessory to this crime?",
  ui_story_5043_50431301_115_dialog_content = "...",
  ui_story_5043_50431301_116_dialog_content = "... Her?",
  ui_story_5043_50431301_117_dialog_content = "At the time of the second incident, we were all in Meadow Square of the Lumopolis Courtyard, responding to a crisis.",
  ui_story_5043_50431301_118_dialog_content = "I see what you're saying. But we need to restore order first.",
  ui_story_5043_50431301_119_dialog_content = "Please, don't panic. Follow me!",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>Smash—!</color>",
  ui_story_5043_50431301_121_dialog_content = "(What was that noise?!)",
  ui_story_5043_50431301_122_dialog_content = "I was the first to hear the sound of the statue being destroyed. Shortly afterwards, Judge Tina and I went over to investigate.",
  ui_story_5043_50431301_123_dialog_content = "Upon reaching the crime scene, we both discovered the statue missing its head.",
  ui_story_5043_50431301_124_dialog_content = "At no point in the course of that day's events did Judge Tina ever leave my sight. As such, I can attest, with complete certainty, that she was not at the crime scene when the second statue was decapitated.",
  ui_story_5043_50431301_125_dialog_content = "I believe Lady Carleen and the nun can corroborate this.",
  ui_story_5043_50431301_126_dialog_content = "It's true. Prior to the incident, Tina was with us the entire time.",
  ui_story_5043_50431301_127_dialog_content = "She had no way of carrying out the crime.",
  ui_story_5043_50431301_128_dialog_content = "Indeed. I, too, can stand as a witness to Judge Tina's lack of involvement in the crime.",
  ui_story_5043_50431301_129_dialog_content = "Well, Your Honor?",
  ui_story_5043_50431301_130_dialog_content = "Are these testimonials sufficient evidence for you?",
  ui_story_5043_50431301_131_dialog_content = "Fine, fine.",
  ui_story_5043_50431301_132_dialog_content = "The court respects and acknowledges any testimony given by Lady Carleen.",
  ui_story_5043_50431301_133_dialog_content = "Furthermore, your words and passion have had an effect on me, Judge Matthieu.",
  ui_story_5043_50431301_134_dialog_content = "It seems I was wrong to accuse Miss Tina Campbell, after all.",
  ui_story_5043_50431301_135_dialog_content = "(D-Did we just win?)",
  ui_story_5043_50431301_136_dialog_content = "The court retracts its prior judgment! We find that the defendant, Tina Campbell, is not the perpetrator behind the serial statue decapitations.",
  ui_story_5043_50431301_137_dialog_content = "We do, however, find her guilty of the <color=#FFB400>third instance</color> of a statue's decapitation!",
  ui_story_5043_50431301_138_dialog_content = "Eh...?",
  ui_story_5043_50431301_139_dialog_content = "Tch.",
  ui_story_5043_50431301_140_dialog_content = "Be proud of your efforts, Judge Matthieu! Without them, the defendant's sentence will be reduced greatly.",
  ui_story_5043_50431301_141_dialog_content = "However! So long as the crucial piece of evidence provided earlier stands uncontested...",
  ui_story_5043_50431301_142_dialog_content = "... the court will still find Tina Campbell guilty of destroying public property, as well as subverting romance!",
  ui_story_5043_50431301_143_dialog_content = "But you were already aware of that, weren't you, Judge Matthieu?",
  ui_story_5043_50431301_144_dialog_content = "Complete nonsense...",
  ui_story_5043_50431301_145_dialog_content = "With that said, you still wish to continue denying the irrefutable evidence brought to the court today?",
  ui_story_5043_50431301_146_dialog_content = "...",
  ui_story_5043_50431301_147_dialog_content = "<size=30>Hang in there, Matthieu...</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>It's still not enough...</size>",
  ui_story_5043_50431301_149_dialog_content = "No, Your Honor. I've said all that I needed to say.",
  ui_story_5043_50431301_150_dialog_content = "What...?",
  ui_story_5043_50431301_151_dialog_content = "Heheheh, is that so?",
  ui_story_5043_50431301_152_dialog_content = "Yes, Your Honor.",
  ui_story_5043_50431301_153_dialog_content = "In that case, the court hereby—",
  ui_story_5043_50431301_154_dialog_content = "It's your turn, Leyn.",
  ui_story_5043_50431301_155_dialog_content = "!!!",
  ui_story_5043_50431301_156_dialog_content = "Leyn?",
  ui_story_5043_50431301_157_dialog_content = "Go on, then. Newcomers are rarely presented with opportunities like this.",
  ui_story_5043_50431301_158_dialog_content = "Understood.",
  ui_story_5043_50431301_159_dialog_content = "Chief Judge Schwab, fellow jury members, and all who are gathered here today.",
  ui_story_5043_50431301_160_dialog_content = "I humbly request a few minutes of your time.",
  ui_story_5043_50431301_161_dialog_content = "So that we may <color=#FFB400>draw inferences</color> from our understanding of the crime.",
  ui_story_5043_50431301_162_dialog_content = "Huh, this kid's kinda crazy.",
  ui_story_5043_50431301_163_dialog_content = "You would do well to choose your words wisely, Judge Leyn. Especially considering your \"humble\" background.",
  ui_story_5043_50431301_164_dialog_content = "Unlike Judge Matthieu, you do not have the support of a noble family should the quality of your work be called into question.",
  ui_story_5043_50431301_165_dialog_content = "And unlike you, Chief Judge Schwab, I do not believe that my common background is necessarily a hindrance.",
  ui_story_5043_50431301_166_dialog_content = "At the very least, my actions have no way of reflecting ignobly upon the illustrious noble caste.",
  ui_story_5043_50431301_167_dialog_content = "You...",
  ui_story_5043_50431301_168_dialog_content = "But let's return to the case at hand, shall we? Your Honor seems to be quite insistent on that piece of crucial evidence...",
  ui_story_5043_50431301_169_dialog_content = "I suggest we perform an even more detailed review of this case, and leave no stone unturned.",
  ui_story_5043_50431301_170_dialog_content = "By closely examining every detail, I believe we'll find some trace of the true culprit—something that will point us in the direction of the truth!",
  ui_story_5043_50431301_171_dialog_content = "Ohhh! How professional! I like how things are proceeding!",
  ui_story_5043_50431301_172_dialog_content = "(Some trace of the true culprit, huh...)",
  ui_story_5043_50431301_173_dialog_content = "(Did you finally discover something, Leyn?)",
  ui_story_5043_50431301_174_dialog_content = "Let's recall what happened at the Stairway to the Skies yesterday, just prior to the incident.",
  ui_story_5043_50431301_175_dialog_content = "In order to protect the statue at the top of the stairs, we attempted to stop the parade from proceeding.",
  ui_story_5043_50431301_176_dialog_content = "To our surprise, we found a group of small Eclipsites skulking just behind the procession.",
  ui_story_5043_50431301_177_dialog_content = "I immediately engaged them in battle. Not long afterward, Judge Tina caught up to me...",
  ui_story_5043_50431302_1_dialog_content = "I kicked the first Eclipsite down the stairs.",
  ui_story_5043_50431302_2_dialog_content = "The second, I impaled with my weapon.",
  ui_story_5043_50431302_3_dialog_content = "The last one, however, was blown to pieces by Tina's fist.",
  ui_story_5043_50431302_4_dialog_content = "Okay, okay! Are such details really necessary?",
  ui_story_5043_50431302_5_dialog_content = "With the small band of Eclipsites defeated, Tina and I began to make our way back to the statue and reconvene with the others.",
  ui_story_5043_50431302_6_dialog_content = "But the crowds were thick that day, and cutting through them proved to be a difficult task.",
  ui_story_5043_50431302_7_dialog_content = "As a result, I was separated from Tina in the crowd... It wasn't until after the incident that I finally saw her again.",
  ui_story_5043_50431302_8_dialog_content = "Trying to get through all those people was a nightmare... I could barely move half the time!",
  ui_story_5043_50431302_9_dialog_content = "That much we can agree on.",
  ui_story_5043_50431302_10_dialog_content = "But this does not prove that Tina Campbell was not at the scene of the crime that day.",
  ui_story_5043_50431302_11_dialog_content = "Let's set that aside for just a moment, Your Honor. Instead, let us turn our attention to the moment that the incident occurred.",
  ui_story_5043_50431302_12_dialog_content = "When I finally reached the statue, I was ambushed by yet another group of Eclipsites.",
  ui_story_5043_50431302_13_dialog_content = "As we were fighting off the Eclipsites, the culprit had a perfect opportunity to strike.",
  ui_story_5043_50431302_14_dialog_content = "Taking advantage of the surrounding chaos, they reached out a gloved hand and shattered the statue's head.",
  ui_story_5043_50431302_15_dialog_content = "I managed to grab hold of their hand, but the culprit was hiding among the Eclipsites, which prevented me from getting a clear look at their face or body.",
  ui_story_5043_50431302_16_dialog_content = "In the end, the culprit was able to wriggle out of my grasp and escape, leaving behind a single glove...",
  ui_story_5043_50431302_17_dialog_content = "The glove that has been provided as key evidence in the case, yes.",
  ui_story_5043_50431302_18_dialog_content = "Lady Carleen and Judge Matthieu did short work of the Eclipsites soon afterward, but the culprit was nowhere to be seen.",
  ui_story_5043_50431302_19_dialog_content = "Once the dust settled, Judge Tina finally reappeared and joined us.",
  ui_story_5043_50431302_20_dialog_content = "And that, ladies and gentlemen of the court, is the full account of the events surrounding the statue's decapitation.",
  ui_story_5043_50431302_21_dialog_content = "And a very well-worded account, at that. Thank you for your contribution, Judge Leyn.",
  ui_story_5043_50431302_22_dialog_content = "With this in mind, it stands to reason that the owner of the glove is the perpetrator of the crime.",
  ui_story_5043_50431302_23_dialog_content = "That, in turn, was the rationale that led us to arrest the defendant, Tina Campbell.",
  ui_story_5043_50431302_24_dialog_content = "Forgive me, Your Honor... But you're jumping to conclusions.",
  ui_story_5043_50431302_25_dialog_content = "I beg your pardon?",
  ui_story_5043_50431302_26_dialog_content = "Based on the information we gathered at the crime scene regarding the culprit—",
  ui_story_5043_50431302_27_dialog_content = "We know that the culprit managed to smash the statue's head with their bare hand while wearing that glove.",
  ui_story_5043_50431302_28_dialog_content = "The person you apprehended, on the other hand...",
  ui_story_5043_50431302_29_dialog_content = "Is just the young lady who is the rightful owner of the glove.",
  ui_story_5043_50431302_30_dialog_content = "If you compare the two more closely, you'll find more inconsistencies than anything else.",
  ui_story_5043_50431302_31_dialog_content = "I feel that you are overthinking things, Judge Leyn.",
  ui_story_5043_50431302_32_dialog_content = "Does it not stand to reason that the glove owner is the person most likely to have worn it at the crime scene?",
  ui_story_5043_50431302_33_dialog_content = "It does, Your Honor... But you're missing the point.",
  ui_story_5043_50431302_34_dialog_content = "Does Judge Tina look like she can pulverize a statue's head with her bare hands?",
  ui_story_5043_50431302_35_dialog_content = "Oh? A new angle?",
  ui_story_5043_50431302_36_dialog_content = "When you really think about it, how could a little girl break a statue with her bare hands?",
  ui_story_5043_50431302_37_dialog_content = "It seems you've gotten lost in your own thought processes, Judge Leyn.",
  ui_story_5043_50431302_38_dialog_content = "Have you already forgotten what you said not two minutes ago?",
  ui_story_5043_50431302_39_dialog_content = "I kicked the first Eclipsite down the stairs.",
  ui_story_5043_50431302_40_dialog_content = "The second, I impaled with my weapon.",
  ui_story_5043_50431302_41_dialog_content = "The last one, however, was <color=#FFB400>blown to pieces by Tina's fist</color>.",
  ui_story_5043_50431302_42_dialog_content = "Surely, you know your colleague better than that? After all, she is the inheritor of the Campbell Family's Divine Hand.",
  ui_story_5043_50431302_43_dialog_content = "For someone who can completely obliterate an Eclipsite with a single punch, a statue's head should pose no problem at all.",
  ui_story_5043_50431302_44_dialog_content = "That's right! She's no ordinary girl!",
  ui_story_5043_50431302_45_dialog_content = "Young man, you need to put a little more thought into your deductions.",
  ui_story_5043_50431302_46_dialog_content = "(I guess he fell just short of the mark, huh?)",
  ui_story_5043_50431302_47_dialog_content = "(If only Leyn was able to get just a small step ahead of the enemy, and find something that slipped their notice...)",
  ui_story_5043_50431302_48_dialog_content = "Ah, yes... Tina inherited the Divine Hand.",
  ui_story_5043_50431302_49_dialog_content = "Then the assumption is that she used it to smash the statue's head, correct?",
  ui_story_5043_50431302_50_dialog_content = "Correct. It's the only logical conclusion after all.",
  ui_story_5043_50431302_51_dialog_content = "And while I must applaud you for your rigorous method of analysis, Judge Leyn...",
  ui_story_5043_50431302_52_dialog_content = "For future trials, I suggest you share your analyses with me prior to the start of our proceedings instead of wasting the court's valuable time.",
  ui_story_5043_50431302_53_dialog_content = "I don't think I've wasted anyone's time at all, Your Honor.",
  ui_story_5043_50431302_54_dialog_content = "All of my inferences were for the sole purpose of getting you to arrive at this very conclusion.",
  ui_story_5043_50431302_55_dialog_content = "Namely, Tina used the Divine Hand to smash the statue's head.",
  ui_story_5043_50431302_56_dialog_content = "... Get to the point, Judge Leyn. What is it you are trying to say?",
  ui_story_5043_50431302_57_dialog_content = "Now that we have arrived at this conclusion, all we need to do is look back once again to realize the truth.",
  ui_story_5043_50431302_58_dialog_content = "That glove, that piece of crucial evidence, is not irrefutable proof of her guilt, but of her innocence!",
  ui_story_5043_50431302_59_dialog_content = "What?!",
  ui_story_5043_50431302_60_dialog_content = "Your Honor, please allow me to show everyone in the court the perpetrator's glove!",
  ui_story_5043_50431302_61_dialog_content = "It's possible that the glove was purged of any incriminating evidence while it was in your possession, Your Honor...",
  ui_story_5043_50431302_62_dialog_content = "But it doesn't matter, so long as it's still the same glove from the crime scene. We can be sure of that, right, Your Honor?",
  ui_story_5043_50431302_63_dialog_content = "Are you questioning my ability to preserve case evidence, one of the most fundamental responsibilities of the Hall of Justice?!",
  ui_story_5043_50431302_64_dialog_content = "Glad to hear.",
  ui_story_5043_50431302_65_dialog_content = "I ask everyone to take a good, long look at this glove.",
  ui_story_5043_50431302_66_dialog_content = "It's a right-handed glove, isn't it?",
  ui_story_5043_50431302_67_dialog_content = "Enough, Judge Leyn. Get to the point!",
  ui_story_5043_50431302_68_dialog_content = "What difference does it make which hand it goes on—",
  ui_story_5043_50431302_69_dialog_content = "!!!",
  ui_story_5043_50431302_70_dialog_content = "Huh?",
  ui_story_5043_50431302_71_dialog_content = "Ah—!",
  ui_story_5043_50431302_72_dialog_content = "The right hand! That explains everything!",
  ui_story_5043_50431302_73_dialog_content = "Wait, I don't get it! What's going on?!",
  ui_story_5043_50431302_74_dialog_content = "It seems you've realized it too, Your Honor.",
  ui_story_5043_50431302_75_dialog_content = "There is but a single, fatal flaw in your conclusion...",
  ui_story_5043_50431302_76_dialog_content = "Tina's Divine Hand, which is indeed capable of destroying a statue's head, requires the use of her <color=#FFB400>left hand</color>.",
  ui_story_5043_50431302_77_dialog_content = "However, this glove is a <color=#FFB400>right-handed</color> glove!",
  ui_story_5043_50431302_78_dialog_content = "Oh! I get it now!!!",
  ui_story_5043_50431302_79_dialog_content = "Left... Right...",
  ui_story_5043_50431302_80_dialog_content = "After spending the entire trial emphasizing the importance of this crucial piece of evidence.",
  ui_story_5043_50431302_81_dialog_content = "I think we can all safely agree with you now, Your Honor.",
  ui_story_5043_50431302_82_dialog_content = "Now that we know this is not the glove that covers Tina's Divine Hand, I wonder what manner of conclusion will be drawn?",
  ui_story_5043_50431302_83_dialog_content = "Well, Your Honor? Would you kindly grace the court with your thoughts?",
  ui_story_5043_50431302_84_dialog_content = "You... You...!",
  ui_story_5043_50431302_85_dialog_content = "Way to go, Leyn! The same evidence used to incriminate Tina also proves her innocence!",
  ui_story_5043_50431302_86_dialog_content = "Looks like the scales are finally tipping back in our favor!",
  ui_story_5043_50431302_87_dialog_content = "This is unbelievable...",
  ui_story_5043_50431302_88_dialog_content = "Very well, then. I have no choice but to acknowledge and accept your rebuttal.",
  ui_story_5043_50431302_89_dialog_content = "Due to insufficient evidence at this time, the court is unable to find the defendant guilty of the aforementioned crimes.",
  ui_story_5043_50431302_90_dialog_content = "Therefore, the true statue decapitator remains at large.",
  ui_story_5043_50431302_91_dialog_content = "This is great!!!",
  ui_story_5043_50431302_92_dialog_content = "They did it, Carleen! They really pulled it off!",
  ui_story_5043_50431302_93_dialog_content = "Indeed! This is wonderful!",
  ui_story_5043_50431302_94_dialog_content = "To witness justice being preserved in the Hall of Justice has been a great honor!",
  ui_story_5043_50431302_95_dialog_content = "So if the perpetrator is still at large...",
  ui_story_5043_50431302_96_dialog_content = "Does that mean I'm innocent?!",
  ui_story_5043_50431302_97_dialog_content = "Of course, Tina. You were always innocent.",
  ui_story_5043_50431302_98_dialog_content = "You owe us quite a debt of gratitude, you know? Especially to our commoner newbie.",
  ui_story_5043_50431302_99_dialog_content = "For his first major case, he did remarkably well.",
  ui_story_5043_50431302_100_dialog_content = "I couldn't agree more! Thank you both so much for all that you've done for me!",
  ui_story_5043_50431302_101_dialog_content = "I'm proud to call you my dearest colleagues!",
  ui_story_5043_50431302_102_dialog_content = "Hey! What's this supposed to mean?!",
  ui_story_5043_50431302_103_dialog_content = "After wasting half a day debating ourselves hoarse, you mean to tell me that you had the wrong person?!",
  ui_story_5043_50431302_104_dialog_content = "...",
  ui_story_5043_50431302_105_dialog_content = "Incredible. Simply incredible!",
  ui_story_5043_50431302_106_dialog_content = "Forcing me to sit through all that deliberation, only to say that we're right back where we started?",
  ui_story_5043_50431302_107_dialog_content = "I told you a lot before! My patience is at its limit!",
  ui_story_5043_50431302_108_dialog_content = "If you don't bring this case to a close by the end of the day, I'll bring this entire Romance Division of the courts to a close!!!",
  ui_story_5043_50431302_109_dialog_content = "Let's not be hasty, my good sir. As it stands, we've only discussed half of the matter.",
  ui_story_5043_50431302_110_dialog_content = "Half...?",
  ui_story_5043_50431302_111_dialog_content = "Take your seat over here with us, Judge Tina.",
  ui_story_5043_50431302_112_dialog_content = "It's time for someone else to serve as the defendant now.",
  ui_story_5043_50431302_113_dialog_content = "Huh? Who do you mean...?",
  ui_story_5043_50431302_114_dialog_content = "After the Romance Division's exhaustive investigation of the case and all evidence provided, I, Judge Leyn—",
  ui_story_5043_50431302_115_dialog_content = "And I, Judge Matthieu—",
  ui_story_5043_50431302_116_dialog_content = "Hereby charge Mr. Schwab Salar with the crimes of destroying public property and subverting love!",
  ui_story_5043_50431302_117_dialog_content = "Chief Judge Schwab, please take the stand.",
  ui_story_5043_50431302_118_dialog_content = "What? He's accusing Schwab?!",
  ui_story_5043_50431302_119_dialog_content = "Don't tell me this is also part of the plan, PlayerName?!",
  ui_story_5043_50431302_120_dialog_content = "Uh...",
  ui_story_5043_50431302_121_dialog_content = "Well, we did have our suspicions about Schwab yesterday, but...",
  ui_story_5043_50431302_122_dialog_content = "I didn't know they were actually going to accuse him of anything...",
  ui_story_5043_50431302_123_dialog_content = "Did you and the others manage to find any incriminating evidence?",
  ui_story_5043_50431302_124_dialog_content = "Not at all...",
  ui_story_5043_50431302_125_dialog_content = "Accusing me, are you?",
  ui_story_5043_50431302_126_dialog_content = "Do you have any idea what you're doing, Judge Leyn?",
  ui_story_5043_50431302_127_dialog_content = "I'm only doing my duty, sir.",
  ui_story_5043_50431302_128_dialog_content = "Hmph. You had better hope so.",
  ui_story_5043_50431302_129_dialog_content = "Because I can tell you now, I have an unquestionable alibi for each of the three incidents.",
  ui_story_5043_50431302_130_dialog_content = "Wherever this silly inquiry may lead, know that the entire Hall of Justice will corroborate my story.",
  ui_story_5043_50431302_131_dialog_content = "I have nothing more to say about your illogical accusations for now.",
  ui_story_5043_50431302_132_dialog_content = "Rest assured, Judge Schwab, my inquiry will be short and simple.",
  ui_story_5043_50431302_133_dialog_content = "I, too, can attest to your airtight alibis for all three instances of wrongdoing in this case.",
  ui_story_5043_50431302_134_dialog_content = "And yet you refuse to withdraw your pointless accusation?",
  ui_story_5043_50431302_135_dialog_content = "That's correct, sir, because the culprit had no need to be present at the crime scenes.",
  ui_story_5043_50431302_136_dialog_content = "May I call upon a new witness?",
  ui_story_5043_50431302_137_dialog_content = "A witness?",
  ui_story_5043_50431302_138_dialog_content = "Please approach the stand and prepare to swear under oath.",
  ui_story_5043_50431302_139_dialog_content = "(When did he find a witness for this?)",
  ui_story_5043_50431302_140_dialog_content = "(I wonder who it is...)",
  ui_story_5043_50431302_141_dialog_content = "C-Can I...",
  ui_story_5043_50431302_142_dialog_content = "Can I talk now?",
  ui_story_5043_50431302_143_dialog_content = "An Eclipsite! And one that can speak, no less!",
  ui_story_5043_50431302_144_dialog_content = "T-Toto?!?",
  ui_story_5043_50431302_145_dialog_content = "Huh? What's he doing here?!",
  ui_story_5043_50431302_146_dialog_content = "Having an Eclipsite serve as a witness... What was he thinking?",
  ui_story_5043_50431302_147_dialog_content = "Have you lost your mind?! How dare you bring that filthy creature into a hallowed court of the Hall of Justice!",
  ui_story_5043_50431302_148_dialog_content = "Do you seek to undermine all that we have established?!",
  ui_story_5043_50431302_149_dialog_content = "There's no reason to worry. We've confirmed, without a doubt, that this Eclipsite is perfectly harmless.",
  ui_story_5043_50431302_150_dialog_content = "No one here is in danger. He's only here to help us uncover the truth with his testimony, nothing more.",
  ui_story_5043_50431302_151_dialog_content = "I believe we are all here for the very same reason, yes?",
  ui_story_5043_50431302_152_dialog_content = "Hmmm... Well, if his testimony furthers the trial, I suppose it's acceptable.",
  ui_story_5043_50431302_153_dialog_content = "Toto looks even skinnier than last time...",
  ui_story_5043_50431302_154_dialog_content = "This is probably unprecedented in the Hall of Justice's entire history... I wonder what kind of testimony he's going to give?",
  ui_story_5043_50431302_155_dialog_content = "A-Allow me to introduce m-myself.",
  ui_story_5043_50431302_156_dialog_content = "P-Please don't be afraid of me!",
  ui_story_5043_50431302_157_dialog_content = "I'm nothing more than an average, low-level Eclipsite.",
  ui_story_5043_50431302_158_dialog_content = "I-I accidentally ate an experimental object in Gannon City...",
  ui_story_5043_50431302_159_dialog_content = "I have no idea what it was, but...",
  ui_story_5043_50431302_160_dialog_content = "My body began to transform, and at the same time, I gained a certain level of sentience!",
  ui_story_5043_50431302_161_dialog_content = "Hmph! How typical of the Illumina Federation to dabble in such unspeakable research!",
  ui_story_5043_50431302_162_dialog_content = "Wow... His Universese has gotten a lot smoother since the last time we spoke?",
  ui_story_5043_50431302_163_dialog_content = "From that moment on, m-my connection to other Eclipsites grew weaker...",
  ui_story_5043_50431302_164_dialog_content = "I couldn't control them anymore but they couldn't control me either!",
  ui_story_5043_50431302_165_dialog_content = "Living among the other Eclipsites got harder and harder... There was no way for me to finish my work without constant complications...",
  ui_story_5043_50431302_166_dialog_content = "The leader couldn't tolerate it, and eventually forced me to leave...",
  ui_story_5043_50431302_167_dialog_content = "She said, if you want to cause trouble, go cause trouble for the Aurorians...",
  ui_story_5043_50431302_168_dialog_content = "Emm, so there are Eclipsites even the Eclipsites can't stand.",
  ui_story_5043_50431302_169_dialog_content = "Don't feel sorry for it. The enemy of your enemy might not necessarily be your friend.",
  ui_story_5043_50431302_170_dialog_content = "Not long afterward, I started learning everything I could about Aurorians. Their language, their cultures...",
  ui_story_5043_50431302_171_dialog_content = "I-I traveled all over the land, looking for work wherever I could. But no matter where I went, I kept getting fired...",
  ui_story_5043_50431302_172_dialog_content = "Life has been hard, but I'm much happier than I've ever been!",
  ui_story_5043_50431302_173_dialog_content = "I would never hurt anyone.",
  ui_story_5043_50431302_174_dialog_content = "B-Because I like living as an Aurorian!",
  ui_story_5043_50431302_X174_dialog_content = "I don't want to be hated anymore!",
  ui_story_5043_50431302_175_dialog_content = "He's right! Toto would never hurt a fly!",
  ui_story_5043_50431302_176_dialog_content = "He's even sweeter than most Aurorians! Please don't feel threatened by him!",
  ui_story_5043_50431302_177_dialog_content = "Tsk, Eclipsite that lives like an Aurorian...",
  ui_story_5043_50431302_178_dialog_content = "The times have changed, it seems!",
  ui_story_5043_50431302_179_dialog_content = "Thank you, Toto. That will do for an introduction.",
  ui_story_5043_50431302_180_dialog_content = "Please tell the court your reason for coming here and serving as a witness in today's trial.",
  ui_story_5043_50431302_181_dialog_content = "I-I came to report an Aurorian for unlawful behavior!",
  ui_story_5043_50431302_182_dialog_content = "And who would that be?",
  ui_story_5043_50431302_183_dialog_content = "That man there! The one sitting above everyone else. The man called Schwab!",
  ui_story_5043_50431302_184_dialog_content = "You...",
  ui_story_5043_50431302_185_dialog_content = "What crime did he commit?",
  ui_story_5043_50431302_186_dialog_content = "H-He was the one who broke the statues!",
  ui_story_5043_50431302_187_dialog_content = "He has alibis that prove he was never at the crime scenes, so what makes you so certain that he was the culprit?",
  ui_story_5043_50431302_188_dialog_content = "He didn't need to be there to destroy them! That's because he can... he can...",
  ui_story_5043_50431302_189_dialog_content = "He can what?",
  ui_story_5043_50431302_190_dialog_content = "He can control Eclipsites!!!",
  ui_story_5043_50431401_1_dialog_content = "Control Eclipsites?!",
  ui_story_5043_50431401_2_dialog_content = "My heavens! Do you know have any idea what you are implying?",
  ui_story_5043_50431401_3_dialog_content = "To consort with Eclipsites is a crime most grievous here in Lumopolis!",
  ui_story_5043_50431401_4_dialog_content = "Tsk! What a ridiculous testimony!",
  ui_story_5043_50431401_5_dialog_content = "Did you really think that you could accuse me of conspiring with Eclipsites by using the testimony of one of their kind?!",
  ui_story_5043_50431401_6_dialog_content = "What a mockery of justice! A drunkard's testimony would hold more water than that of a foul Eclipsite!",
  ui_story_5043_50431401_7_dialog_content = "When it comes to framing others, your skills are still sorely lacking, Leyn!",
  ui_story_5043_50431401_8_dialog_content = "Is that so? Then perhaps I should take a page or two out of your book, Judge Schwab?",
  ui_story_5043_50431401_9_dialog_content = "You...!",
  ui_story_5043_50431401_10_dialog_content = "I don't need to frame you to prove your guilt.",
  ui_story_5043_50431401_11_dialog_content = "It's just as you say, the testimony of a single Eclipsite isn't nearly enough to implicate you for these crimes.",
  ui_story_5043_50431401_12_dialog_content = "But what if that Eclipsite played a special role in the case?",
  ui_story_5043_50431401_13_dialog_content = "A special role...?",
  ui_story_5043_50431401_14_dialog_content = "If you would be so kind, Toto?",
  ui_story_5043_50431401_15_dialog_content = "I-I'm sorry!!!",
  ui_story_5043_50431401_16_dialog_content = "I made a mistake... I'll accept my punishment, here and now!!!",
  ui_story_5043_50431401_17_dialog_content = "Huh?",
  ui_story_5043_50431401_18_dialog_content = "What do you mean, Toto? What mistake are you talking about?",
  ui_story_5043_50431401_19_dialog_content = "Honestly, one moment it's accusing the chief judge, and the next, it's admitting its own guilt...",
  ui_story_5043_50431401_20_dialog_content = "Stop wasting our time and speak clearly, I say!",
  ui_story_5043_50431401_21_dialog_content = "S-Sorry! Th-The truth is...",
  ui_story_5043_50431401_22_dialog_content = "I was the one who destroyed the statues!",
  ui_story_5043_50431401_23_dialog_content = "What?!",
  ui_story_5043_50431401_24_dialog_content = "Hah? So it was you?!",
  ui_story_5043_50431401_25_dialog_content = "You're the one who destroyed my wife and my lover?!",
  ui_story_5043_50431401_26_dialog_content = "Yes, it was me.",
  ui_story_5043_50431401_27_dialog_content = "Why, you rotten, little...!",
  ui_story_5043_50431401_28_dialog_content = "W-Wait! I didn't do it on purpose! I was forced to!",
  ui_story_5043_50431401_29_dialog_content = "Schwab was the one who made me do it every single time!",
  ui_story_5043_50431401_30_dialog_content = "Please, everyone. Have mercy on me—!",
  ui_story_5043_50431401_31_dialog_content = "<size=45>What?!?</size>",
  ui_story_5043_50431401_32_dialog_content = "...",
  ui_story_5043_50431401_33_dialog_content = "Is this really what happened...?",
  ui_story_5043_50431401_34_dialog_content = "I-It all started about two weeks ago...",
  ui_story_5043_50431401_35_dialog_content = "I had just arrived in Lumopolis, and I was getting ready to look for a job.",
  ui_story_5043_50431401_36_dialog_content = "But Lumopolis is so big, and I didn't know the roads very well... Before I knew it, it was already night.",
  ui_story_5043_50431401_37_dialog_content = "After that, I... I ran into a group of Eclipsites in Lumopolis Courtyard.",
  ui_story_5043_50431401_38_dialog_content = "Well, there have been multiple sightings of Eclipsite activity in the city lately.",
  ui_story_5043_50431401_39_dialog_content = "This much is true, at least.",
  ui_story_5043_50431401_40_dialog_content = "I-I didn't expect to find more of my kind in the city. It felt strange.",
  ui_story_5043_50431401_41_dialog_content = "As I stood there trying to understand things, they assumed I was just another lost Eclipsite.",
  ui_story_5043_50431401_42_dialog_content = "They were very insistent on making me join their ranks.",
  ui_story_5043_50431401_43_dialog_content = "Despite my confusion, I followed them until finally...",
  ui_story_5043_50431401_44_dialog_content = "We arrived at the Salar Manor.",
  ui_story_5043_50431401_45_dialog_content = "Hey! That's Schwab's home!",
  ui_story_5043_50431401_46_dialog_content = "That's right, and that was where I saw him for the first time.",
  ui_story_5043_50431401_47_dialog_content = "It was the most shocking thing I had ever seen...",
  ui_story_5043_50431401_48_dialog_content = "He was ordering the Eclipsites around as if they were slaves.",
  ui_story_5043_50431401_49_dialog_content = "And the Eclipsites... They obeyed his every command!",
  ui_story_5043_50431401_50_dialog_content = "I-I had no way of escaping... So I had to pretend to be one of them.",
  ui_story_5043_50431401_51_dialog_content = "That's when he locked us all in the Salar Manor's cellar!",
  ui_story_5043_50431401_52_dialog_content = "The cellar?!",
  ui_story_5043_50431401_53_dialog_content = "So he was holding those Eclipsites captive in there all along! No wonder...",
  ui_story_5043_50431401_54_dialog_content = "Have you been there before?",
  ui_story_5043_50431401_55_dialog_content = "Er, I don't think this is the right time or place to tell you...",
  ui_story_5043_50431401_56_dialog_content = "I'll talk to you about it after the trial!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>Cease this nonsense right now!</size>",
  ui_story_5043_50431401_58_dialog_content = "Can you believe the absolute codswallop being spewed from this foul creature's mouth?",
  ui_story_5043_50431401_59_dialog_content = "I have no reason to endure this ludicrous slander any longer!!!",
  ui_story_5043_50431401_60_dialog_content = "We'll see if it's slander soon enough, Judge Schwab.",
  ui_story_5043_50431401_61_dialog_content = "Please tell us what happened afterward, Toto.",
  ui_story_5043_50431401_62_dialog_content = "While this part of your testimony is shocking, indeed, it has little to do with the serial statue decapitations.",
  ui_story_5043_50431401_63_dialog_content = "Oh, right! Let me tie it back to the case!",
  ui_story_5043_50431401_64_dialog_content = "Once in a while, Schwab would pull some of us out of the cellar to carry out his orders.",
  ui_story_5043_50431401_65_dialog_content = "I-I was desperate for a chance to escape, so I acted even more restless than my brethren.",
  ui_story_5043_50431401_66_dialog_content = "And eventually... He picked me for one of his tasks.",
  ui_story_5043_50431401_67_dialog_content = "Specifically... He told me to wait until the Moon Balloon rose into the sky, and then d-destroy the statues below it!",
  ui_story_5043_50431401_68_dialog_content = "Oh! That matches the knowledge we have on the case perfectly!",
  ui_story_5043_50431401_69_dialog_content = "The first two times were the statues in front of the Hall of Justice and Meadow Square.",
  ui_story_5043_50431401_70_dialog_content = "In front of the Hall of Justice?!",
  ui_story_5043_50431401_71_dialog_content = "That was... My lover!",
  ui_story_5043_50431401_72_dialog_content = "I'm deeply sorry for your loss, Mr. Byron.",
  ui_story_5043_50431401_73_dialog_content = "Perhaps it was because the first two times went so smoothly... But Schwab asked more of me for the third time.",
  ui_story_5043_50431401_74_dialog_content = "H-He told me... To put on a strange glove before breaking the third statue...",
  ui_story_5043_50431401_75_dialog_content = "That explains the glove!!!",
  ui_story_5043_50431401_76_dialog_content = "And once I finished, I was to leave the glove at the crime scene.",
  ui_story_5043_50431401_77_dialog_content = "That's when I went to the Stairway to the Skies with a group of Eclipsites...",
  ui_story_5043_50431401_78_dialog_content = "But just after I shattered the statue's head, Judge Leyn managed to grab my right hand... I barely avoided capture that day.",
  ui_story_5043_50431401_79_dialog_content = "Thankfully, I was able to wriggle my hand out of the glove and run away... With that, my \"task\" was a success.",
  ui_story_5043_50431401_80_dialog_content = "Is this the glove you left behind?",
  ui_story_5043_50431401_81_dialog_content = "Yes! That's the one!",
  ui_story_5043_50431401_82_dialog_content = "It adds up! It all adds up now!",
  ui_story_5043_50431401_83_dialog_content = "It appears Toto's testimony lines up with the evidence provided in this trial.",
  ui_story_5043_50431401_84_dialog_content = "Next, let us...",
  ui_story_5043_50431401_85_dialog_content = "Hmph! \"Lines up,\" you say?",
  ui_story_5043_50431401_86_dialog_content = "This \"testimony\" of his sounds entirely rehearsed! An utterly-falsified narrative!",
  ui_story_5043_50431401_87_dialog_content = "Is there any evidence, any at all, that proves even one sentence of what he spoke is the truth?!",
  ui_story_5043_50431401_88_dialog_content = "So despite his willingness to plead guilty, you still don't find his testimony reliable enough, Judge Schwab?",
  ui_story_5043_50431401_89_dialog_content = "Of course not! Just because a witness pleads guilty doesn't mean they are the culprit!",
  ui_story_5043_50431401_90_dialog_content = "I have more than enough reason to suspect that someone bought this Eclipsite in order to frame me with it.",
  ui_story_5043_50431401_91_dialog_content = "After all, using an inferior life form to incriminate a high-ranking judge would be quite a bargain, wouldn't you agree?",
  ui_story_5043_50431401_92_dialog_content = "Wh-What's that supposed to mean?! B-Besides, y-you're the one incriminating me!!",
  ui_story_5043_50431401_93_dialog_content = "I-I just came to Lumopolis to find work... I never wanted to get captured and bossed around because of your scheming!",
  ui_story_5043_50431401_94_dialog_content = "If someone hadn't left the cellar door open yesterday, I never would've found my freedom again!",
  ui_story_5043_50431401_95_dialog_content = "I see... It seems this cellar is quite the area of interest.",
  ui_story_5043_50431401_96_dialog_content = "Nonsense! It's spewing nonsense again!",
  ui_story_5043_50431401_97_dialog_content = "My home has no cellar of any kind!",
  ui_story_5043_50431401_98_dialog_content = "Oh, yeah? Why don't we send someone to search it and hear what they have to say?!",
  ui_story_5043_50431401_99_dialog_content = "Search my home? That would be illegal, you foolish monster!",
  ui_story_5043_50431401_100_dialog_content = "The privacy of the Salar Family is entitled to the fullest protection of the law!",
  ui_story_5043_50431401_101_dialog_content = "But how could that be...?",
  ui_story_5043_50431401_102_dialog_content = "Judge Schwab is perfectly correct. We have no right to launch an investigation into the Salar Family's private residence.",
  ui_story_5043_50431401_103_dialog_content = "...",
  ui_story_5043_50431401_104_dialog_content = "Unless, of course, you have proven yourself guilty.",
  ui_story_5043_50431401_105_dialog_content = "What?!?",
  ui_story_5043_50431401_106_dialog_content = "Tch...",
  ui_story_5043_50431401_107_dialog_content = "I'm sure you've realized it too, Judge Schwab. After all, the words came from your own mouth...",
  ui_story_5043_50431401_108_dialog_content = "\"Just because a witness pleads guilty doesn't mean they are the culprit.\"",
  ui_story_5043_50431401_109_dialog_content = "...",
  ui_story_5043_50431401_110_dialog_content = "You spoke those words because you know everything hinges on them.",
  ui_story_5043_50431401_111_dialog_content = "The moment the Hall of Justice finds him guilty, everything he said will be subjected to the highest level of scrutiny.",
  ui_story_5043_50431401_112_dialog_content = "That's because his testimony was also an admission of guilt.",
  ui_story_5043_50431401_113_dialog_content = "And if the court accepts this Eclipsite's testimony, it also accepts the fact that he rebelled against someone who was pulling the strings from behind the scenes.",
  ui_story_5043_50431401_114_dialog_content = "The Hall of Justice would then be granted every authority to investigate the elements of Toto's testimony to the fullest extent of the law.",
  ui_story_5043_50431401_115_dialog_content = "If that were to happen, the question of whether or not the Salar Manor has a cellar would be answered sooner rather than later.",
  ui_story_5043_50431401_116_dialog_content = "Spare me your contrivances, Leyn. I know full well what you are planning.",
  ui_story_5043_50431401_117_dialog_content = "You're simply using an insignificant case and an even more insignificant Eclipsite to violate the Salar Family's privacy.",
  ui_story_5043_50431401_118_dialog_content = "Mark my words, Leyn. You will not succeed!",
  ui_story_5043_50431401_119_dialog_content = "Hey! Whose case are you calling \"insignificant\"?!",
  ui_story_5043_50431401_120_dialog_content = "Shut your mouth, wretch!",
  ui_story_5043_50431401_121_dialog_content = "Wh-What was that...?!",
  ui_story_5043_50431401_122_dialog_content = "I've had just about enough of this farce of a trial!",
  ui_story_5043_50431401_123_dialog_content = "As the chief judge, I declare that the Eclipsite's testimony has no bearing on the case whatsoever!",
  ui_story_5043_50431401_124_dialog_content = "As stated previously, this case's trial must be postponed due to a present lack of compelling evidence.",
  ui_story_5043_50431401_125_dialog_content = "Court is adjourned until such a day that conclusive evidence is brought to light—",
  ui_story_5043_50431401_126_dialog_content = "W-Wait! I have proof of my guilt!",
  ui_story_5043_50431401_127_dialog_content = "!!!",
  ui_story_5043_50431401_128_dialog_content = "It's right here! Right in this courtroom!",
  ui_story_5043_50431401_129_dialog_content = "Let me guess, another pointless story meant to implicate me?",
  ui_story_5043_50431401_130_dialog_content = "I have proof! Really!",
  ui_story_5043_50431401_131_dialog_content = "And what exactly is this proof, Toto?",
  ui_story_5043_50431401_132_dialog_content = "It's the glove that was left at the crime scene!",
  ui_story_5043_50431401_133_dialog_content = "The glove...?",
  ui_story_5043_50431401_134_dialog_content = "I-I'm positive that Schwab has already cleaned the glove to get rid of any trace of Eclipsites...",
  ui_story_5043_50431401_135_dialog_content = "But before I broke the statue, I used my fingernails to scratch a hole in the glove!",
  ui_story_5043_50431401_136_dialog_content = "Th-That's not something he can just wash away!",
  ui_story_5043_50431401_137_dialog_content = "What?!?",
  ui_story_5043_50431401_138_dialog_content = "I see. So if we can find that hole in the glove, it proves that you were the one wearing it.",
  ui_story_5043_50431401_139_dialog_content = "Which, in turn, would prove that you are the culprit in the crime.",
  ui_story_5043_50431401_140_dialog_content = "That's right!",
  ui_story_5043_50431401_141_dialog_content = "Judge Schwab, may we please inspect that piece of evidence once again?",
  ui_story_5043_50431401_142_dialog_content = "...",
  ui_story_5043_50431401_143_dialog_content = "Please hand it over for the court to see.",
  ui_story_5043_50431401_144_dialog_content = "If the court is to be adjourned shortly, I promise it won't take long. This will be our last order of business for today.",
  ui_story_5043_50431401_145_dialog_content = "...",
  ui_story_5043_50431401_146_dialog_content = "Judge Schwab?",
  ui_story_5043_50431401_147_dialog_content = "... Ugh.",
  ui_story_5043_50431401_148_dialog_content = "This is precisely why I think <color=#FFB400>love is disgusting</color>.",
  ui_story_5043_50431401_149_dialog_content = "What?!",
  ui_story_5043_50431401_150_dialog_content = "Wait, does that mean he...?",
  ui_story_5043_50431401_151_dialog_content = "I find it disgusting, to be surrounded by so many adoring commoners.",
  ui_story_5043_50431401_152_dialog_content = "Constantly approaching me, constantly trying to pry into my private life. Presumptuous fools!",
  ui_story_5043_50431401_153_dialog_content = "And yes, you people remind me so much of them.",
  ui_story_5043_50431401_154_dialog_content = "You say you find love \"disgusting\"?",
  ui_story_5043_50431401_155_dialog_content = "Of course I do! What you people call love is nothing more than an inescapable nightmare!",
  ui_story_5043_50431401_156_dialog_content = "To be surrounded by my peers every single day, to have to endure their excessive flattery at every turn.",
  ui_story_5043_50431401_157_dialog_content = "As a student, my desk was piled high with love letters, and my home was filled with gifts during the holidays just for me.",
  ui_story_5043_50431401_158_dialog_content = "Do you people have any idea how painful it is to be loved by everyone?!?",
  ui_story_5043_50431401_159_dialog_content = "...",
  ui_story_5043_50431401_160_dialog_content = "... What the heck is he talking about?",
  ui_story_5043_50431401_161_dialog_content = "Your guess is as good as mine.",
  ui_story_5043_50431401_162_dialog_content = "At first, I thought things would get better after I started working.",
  ui_story_5043_50431401_163_dialog_content = "I would never have expected a wave of vomit-inducing love would sweep across the entire city like this!",
  ui_story_5043_50431401_164_dialog_content = "And as if to compound my suffering, they made me the chief judge of this humiliating Romance Division within the Hall of Justice!",
  ui_story_5043_50431401_165_dialog_content = "That's right. I couldn't stand it anymore, so I plotted the destruction of those statues!!!",
  ui_story_5043_50431401_166_dialog_content = "I knew those shallow event organizers were planning to use them as the centerpieces of their vile celebration, and I swore to stop them at all costs!",
  ui_story_5043_50431401_167_dialog_content = "You...",
  ui_story_5043_50431401_168_dialog_content = "You're the shallow one for using violence to send your message of hatred!",
  ui_story_5043_50431401_169_dialog_content = "So that's why you ordered the Eclipsites to destroy those statues?",
  ui_story_5043_50431401_170_dialog_content = "Yes... I was the one who sent them. Their filthy natures are perfect for defiling a so-called \"celebration of love.\"",
  ui_story_5043_50431401_171_dialog_content = "Does this mean I can take everything you just said as an admission of guilt?",
  ui_story_5043_50431401_172_dialog_content = "You can dispense with the false formalities now, Leyn.",
  ui_story_5043_50431401_173_dialog_content = "You've already gotten all the proof you need. You won.",
  ui_story_5043_50431401_174_dialog_content = "My only mistake was that I forgot to destroy the \"tool\" that I used for the crime... I never thought it would come back to testify against me like this.",
  ui_story_5043_50431401_175_dialog_content = "...",
  ui_story_5043_50431401_176_dialog_content = "No, Schwab. The reason you lost isn't nearly that complicated.",
  ui_story_5043_50431401_177_dialog_content = "The reason you lost is that you didn't show us the glove.",
  ui_story_5043_50431401_178_dialog_content = "<size=45>What?!?</size>",
  ui_story_5043_50431401_179_dialog_content = "Wait a minute! Isn't the glove the piece of evidence we needed to win?!",
  ui_story_5043_50431401_180_dialog_content = "Could it be that... it was all a bluff?",
  ui_story_5043_50431401_181_dialog_content = "Whew, thank goodness that's over! I can finally breathe normally now.",
  ui_story_5043_50431401_182_dialog_content = "I must say, Leyn, you really are a master of misdirection!",
  ui_story_5043_50431401_183_dialog_content = "You people... You tricked me?!",
  ui_story_5043_50431401_184_dialog_content = "Th-That accursed Eclipsite never left any kind of hole in it!!!",
  ui_story_5043_50431401_185_dialog_content = "Heheh... But wait, there's more!",
  ui_story_5043_50431401_186_dialog_content = "Don't you think you find it a little too coincidental?",
  ui_story_5043_50431401_187_dialog_content = "That the only Eclipsite who managed to escape your home, is the same one who you ordered to destroy the statues?",
  ui_story_5043_50431401_188_dialog_content = "Don't tell me you...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>Yesterday...</color>",
  ui_story_5043_50431401_190_dialog_content = "Ready for a little overtime, then?",
  ui_story_5043_50431401_191_dialog_content = "Of course. With the case as unclear as ever, it's my job to collect as much information as possible before the trial.",
  ui_story_5043_50431401_192_dialog_content = "Still, I didn't expect you would choose to tag along with me.",
  ui_story_5043_50431401_193_dialog_content = "Tch! Tell me, commoner, was that an insult to my work ethic or my friendship with Tina just now?",
  ui_story_5043_50431401_194_dialog_content = "It matters not, I suppose. Let's just set aside our differences for now, and focus on the case...",
  ui_story_5043_50431401_195_dialog_content = "S-Sorry to bother, but is the Hall of Justice still open?",
  ui_story_5043_50431401_196_dialog_content = "What's this? An Eclipsite?",
  ui_story_5043_50431401_197_dialog_content = "And on the doorstep of the Hall of Justice, no less! Prepare to die, fiend!",
  ui_story_5043_50431401_198_dialog_content = "W-Wait, don't hurt me! I'm here to report a crime!!!",
  ui_story_5043_50431401_199_dialog_content = "I beg your pardon? An Eclipsite reporting a crime?",
  ui_story_5043_50431401_200_dialog_content = "Let's listen to what he has to say. Besides, if he causes any trouble, exterminating him won't be an issue.",
  ui_story_5043_50431401_201_dialog_content = "Fine. Tell us about this crime then. And make it quick!",
  ui_story_5043_50431401_202_dialog_content = "O-Okay!",
  ui_story_5043_50431401_203_dialog_content = "A-Allow me to introduce m-myself...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>Ten minutes later...</color>",
  ui_story_5043_50431401_205_dialog_content = "... And that's when he rounded us all up and locked us in the Salar Manor's cellar!",
  ui_story_5043_50431401_206_dialog_content = "But how could this be? I mean, it does explain why we encountered Eclipsites in the cellar...",
  ui_story_5043_50431401_207_dialog_content = "Y-Yeah! That's when I escaped with the r-rest of them!",
  ui_story_5043_50431401_208_dialog_content = "What?!",
  ui_story_5043_50431401_209_dialog_content = "Then that means... We're the ones who rescued you!",
  ui_story_5043_50431401_210_dialog_content = "A-And I couldn't be more grateful! You guys are m-my heroes!",
  ui_story_5043_50431401_211_dialog_content = "So you want to accuse Schwab of harboring Eclipsites against their will?",
  ui_story_5043_50431401_212_dialog_content = "Y-Yes! I know that L-Lumopolis law would never protect an E-Eclipsite, but I know he must be up to something even worse!",
  ui_story_5043_50431401_213_dialog_content = "A simple enough task. Just come to the courthouse tomorrow, and tell everyone what you just told us.",
  ui_story_5043_50431401_214_dialog_content = "Soon, everyone will know exactly what Schwab has been doing in the shadows!",
  ui_story_5043_50431401_215_dialog_content = "S-Sure! I can do that!",
  ui_story_5043_50431401_216_dialog_content = "... Do you have any proof?",
  ui_story_5043_50431401_217_dialog_content = "P-Proof?",
  ui_story_5043_50431401_218_dialog_content = "Remember, you're an Eclipsite.",
  ui_story_5043_50431401_219_dialog_content = "We've been to the Salar Family's cellar, so we can trust your words, but what about the others?",
  ui_story_5043_50431401_220_dialog_content = "Without any evidence, all Schwab has to do is deny your testimony, and you will be thrown out.",
  ui_story_5043_50431401_221_dialog_content = "Not only that, he may even come after you once the trial is over.",
  ui_story_5043_50431401_222_dialog_content = "Going forward with this would be an extremely dangerous decision.",
  ui_story_5043_50431401_223_dialog_content = "I-I'm sorry, but I don't have any evidence...",
  ui_story_5043_50431401_224_dialog_content = "I-It took all I had just to escape from his cellar...",
  ui_story_5043_50431401_225_dialog_content = "Hey! We can't afford to surrender simply because we have no evidence!",
  ui_story_5043_50431401_226_dialog_content = "Why don't we try paying another visit to Salar Manor?",
  ui_story_5043_50431401_227_dialog_content = "Wait, I don't think we need to go that far. I have an idea...",
  ui_story_5043_50431401_228_dialog_content = "Go on?",
  ui_story_5043_50431401_229_dialog_content = "Since we don't have proof, all we have to do is get him to admit to the crimes!",
  ui_story_5043_50431401_230_dialog_content = "... You're joking, right?",
  ui_story_5043_50431401_231_dialog_content = "How could we get him to admit to them without any proof?!",
  ui_story_5043_50431401_232_dialog_content = "Tell me, why do you think he was keeping Eclipsites captive in the first place?",
  ui_story_5043_50431401_233_dialog_content = "Hmm... Well, for him to do something so dangerous, it would have to be for a very important reason.",
  ui_story_5043_50431401_234_dialog_content = "I think he somehow ordered them to destroy the statues.",
  ui_story_5043_50431401_235_dialog_content = "Oh? What makes you say that?",
  ui_story_5043_50431401_236_dialog_content = "Remember when I grabbed the culprit's hand back at the Stairway to the Skies?",
  ui_story_5043_50431401_237_dialog_content = "After you and the others wiped out the rest of the Eclipsites, there was no one else around.",
  ui_story_5043_50431401_238_dialog_content = "The top of the Stairway to the Skies is a huge, open space. There's no way anyone could disappear from our sight that quickly.",
  ui_story_5043_50431401_239_dialog_content = "Unless, of course, the culprit was an Eclipsite.",
  ui_story_5043_50431401_240_dialog_content = "Oh, I see now! If the culprit was an Eclipsite, we would have gotten rid of it along with the others!",
  ui_story_5043_50431401_241_dialog_content = "That would explain why we never found them!",
  ui_story_5043_50431401_242_dialog_content = "This is the most likely reason, yes.",
  ui_story_5043_50431401_243_dialog_content = "So how are you planning to use this information?",
  ui_story_5043_50431401_244_dialog_content = "First, we're going to make Toto out to be the culprit.",
  ui_story_5043_50431401_245_dialog_content = "Next, we're going to have him give our version of the truth as his testimony.",
  ui_story_5043_50431401_246_dialog_content = "So long as our hunch is close enough to the truth, Schwab will believe that Toto was the Eclipsite who he ordered to destroy the statues.",
  ui_story_5043_50431401_247_dialog_content = "It's perfect! So your goal is to make him believe we have incriminating evidence on him. And then once he acknowledges defeat, he'll confess to his crimes out of frustration!",
  ui_story_5043_50431401_248_dialog_content = "That's right. We have to beat him in a battle of wits.",
  ui_story_5043_50431401_249_dialog_content = "So what do you say, Toto? Are you willing to lie under oath?",
  ui_story_5043_50431401_250_dialog_content = "A-As long as it exposes Schwab, I'll do it!",
  ui_story_5043_50431401_251_dialog_content = "Good. We'll spend the rest of the day rehearsing your lines, then.",
  ui_story_5043_50431401_252_dialog_content = "If we want to maximize our chances of success, we'll need to come up with something convincing.",
  ui_story_5043_50431401_253_dialog_content = "Something that will make Schwab doubt himself enough to believe we're telling the truth.",
  ui_story_5043_50431401_254_dialog_content = "You... You miserable charlatans!",
  ui_story_5043_50431401_255_dialog_content = "All we did was fight fire with fire, Judge Schwab.",
  ui_story_5043_50431401_256_dialog_content = "To think that the culprit was the chief judge all along.",
  ui_story_5043_50431401_257_dialog_content = "This is unbelievable. How could any of you stoop so low? You call yourselves members of the Hall of Justice?!",
  ui_story_5043_50431401_258_dialog_content = "Even so, the court was ultimately able to bring the truth to light, wasn't it?",
  ui_story_5043_50431401_259_dialog_content = "Sometimes, the only way to defeat the darkness is with darkness itself!",
  ui_story_5043_50431401_260_dialog_content = "It's over, Judge Schwab. Come along peaceably, and take responsibility for your actions.",
  ui_story_5043_50431401_261_dialog_content = "Hmph. It's over, you say?",
  ui_story_5043_50431401_262_dialog_content = "It seems you, too, have made a single, crucial mistake, Leyn. Would you like to guess what it is?",
  ui_story_5043_50431401_263_dialog_content = "What do you mean...?",
  ui_story_5043_50431401_264_dialog_content = "Your mistake was assuming that things would come to an end once you uncovered the truth.",
  ui_story_5043_50431401_265_dialog_content = "As the chief judge, I hereby declare that Judge Leyn, Judge Tina, and Judge Matthieu are all complicit in the crimes brought before the court!",
  ui_story_5043_50431401_266_dialog_content = "The three perpetrators shall be immediately arrested upon the adjournment of this trial!",
  ui_story_5043_50431401_267_dialog_content = "What madness is this, Schwab?!",
  ui_story_5043_50431401_268_dialog_content = "Everyone here just heard you confess! You're the real culprit, not us!",
  ui_story_5043_50431401_269_dialog_content = "Oh my, it appears we have yet to reach a consensus on this case.",
  ui_story_5043_50431401_270_dialog_content = "Very well, then! We shall have the jury vote on it instead!",
  ui_story_5043_50431401_271_dialog_content = "The jury?!",
  ui_story_5043_50431401_272_dialog_content = "Wait a minute, are those...?",
  ui_story_5043_50431401_273_dialog_content = "E-Eclipsites?! But how?!",
  ui_story_5043_50431401_274_dialog_content = "Please deliver your closing statement, Judge Leyn.",
  ui_story_5043_50431401_275_dialog_content = "... In light of all that has happened, I conclude that Schwab Salar is the true culprit in this case.",
  ui_story_5043_50431401_276_dialog_content = "Good, good... Those who agree with his accusation, raise your hands.",
  ui_story_5043_50431401_277_dialog_content = "Let's see... Leyn, Matthieu, Tina, and Judge Jr.",
  ui_story_5043_50431401_278_dialog_content = "Four votes in total. It seems your words have swayed quite a number of hearts, Leyn.",
  ui_story_5043_50431401_279_dialog_content = "That's because I speak the truth!",
  ui_story_5043_50431401_280_dialog_content = "On the other hand, I conclude that Judges Leyn, Tina, and Matthieu are the true culprits in the case.",
  ui_story_5043_50431401_281_dialog_content = "Those who agree with my conclusion, please knock once on the table.",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431401_286_dialog_content = "But they're...",
  ui_story_5043_50431401_287_dialog_content = "Four votes.",
  ui_story_5043_50431401_288_dialog_content = "Including my own vote, which makes five.",
  ui_story_5043_50431401_289_dialog_content = "It appears my conclusion was just slightly more compelling than your own.",
  ui_story_5043_50431401_290_dialog_content = "You... You replaced everyone on the jury with your own henchmen!!",
  ui_story_5043_50431401_291_dialog_content = "Your henchmen? They must all be Eclipsites beneath those masks!",
  ui_story_5043_50431401_292_dialog_content = "The votes have been cast, and a clear decision has been made!",
  ui_story_5043_50431401_293_dialog_content = "The court finds Leyn, Matthieu, and Tina—",
  ui_story_5043_50431401_294_dialog_content = "Guilty!",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431401_296_dialog_content = "There's something wrong with those jurors!",
  ui_story_5043_50431401_X296_dialog_content = "Such intense Darkflow! They really are Eclipsites!",
  ui_story_5043_50431401_X297_dialog_content = "Wh-What did you say!?",
  ui_story_5043_50431401_X298_dialog_content = "You've got to be kidding—all these people sitting here with me are Eclipsites!?",
  ui_story_5043_50431401_297_dialog_content = "Respected members of the jury, I thank you for your assistance.",
  ui_story_5043_50431401_298_dialog_content = "You served not only as witnesses today but as my knights in the execution of justice.",
  ui_story_5043_50431401_299_dialog_content = "By the power vested in the Hall of Justice—",
  ui_story_5043_50431401_300_dialog_content = "Arrest those criminals!",
  ui_story_5043_50431401_301_dialog_content = "Graah...",
  ui_story_5043_50431401_302_dialog_content = "Drat, I think those are Eclipsites hiding beneath those masks!",
  ui_story_5043_50431401_303_dialog_content = "Indeed. If this is Schwab's trump card, they won't be easy to deal with.",
  ui_story_5043_50431401_304_dialog_content = "Resorting to violence, all because you lost in court? How petty!",
  ui_story_5043_50431401_305_dialog_content = "This isn't good, the Hall of Justice suits their fighting style better. We'll be surrounded in no time!",
  ui_story_5043_50431401_306_dialog_content = "We were right... We were right, Schwab! How could you let evil triumph in the house of justice?!",
  ui_story_5043_50431401_307_dialog_content = "Let it go, Leyn! Justice always sides with the winner, and we're fighting an uphill battle here!",
  ui_story_5043_50431401_308_dialog_content = "We need to escape while we can!",
  ui_story_5043_50431401_309_dialog_content = "She's right, now get moving!",
  ui_story_5043_50431401_310_dialog_content = "This way, hurry!",
  ui_story_5043_50431402_1_dialog_content = "High above our heads, our love floats like a cloud! ♪",
  ui_story_5043_50431402_2_dialog_content = "Hidden just behind a veil, our love is so proud! ♪",
  ui_story_5043_50431402_3_dialog_content = "From afar, we wonder what beauty lies inside ♪",
  ui_story_5043_50431402_4_dialog_content = "To see our love bloom is a wish we cannot hide! ♪",
  ui_story_5043_50431402_5_dialog_content = "I hear they're going to pop the moon balloon today. Do you think it's true?",
  ui_story_5043_50431402_6_dialog_content = "Of course they are! That's the whole reason we're gathered here today!",
  ui_story_5043_50431402_7_dialog_content = "They say the balloon is filled with all kinds of things, like flowers, paper crafts, and even different-colored bubbles!",
  ui_story_5043_50431402_8_dialog_content = "That sounds even better than fireworks! A perfect tribute to the power of love!",
  ui_story_5043_50431402_9_dialog_content = "Huh? It looks like a crowd of people is running out of the Hall of Justice.",
  ui_story_5043_50431402_10_dialog_content = "Wonder what they're doing?",
  ui_story_5043_50431402_11_dialog_content = "Phew, we finally managed to escape.",
  ui_story_5043_50431402_12_dialog_content = "We can't relax just yet! They're gonna catch up any second now!",
  ui_story_5043_50431402_13_dialog_content = "...",
  ui_story_5043_50431402_14_dialog_content = "Persistent monsters, aren't they?",
  ui_story_5043_50431402_15_dialog_content = "Do they intend to chase us all the way to Umbraton?!",
  ui_story_5043_50431402_16_dialog_content = "Wait, it looks like a parade is heading this way!",
  ui_story_5043_50431402_17_dialog_content = "Now, of all times...",
  ui_story_5043_50431402_18_dialog_content = "We can't just run away now! The Eclipsites will attack those people if we do!",
  ui_story_5043_50431402_19_dialog_content = "That's right. We'll have to defeat them, here and now.",
  ui_story_5043_50431402_20_dialog_content = "PlayerName, can you warn the parade and have them evacuate the area?",
  ui_story_5043_50431402_21_dialog_content = "Sure, leave it to me!",
  ui_story_5043_50431402_22_dialog_content = "They came to see a show, the likes of which they had never before witnessed.",
  ui_story_5043_50431402_23_dialog_content = "Do you really have the heart to rob them of such a highly-anticipated experience?",
  ui_story_5043_50431402_24_dialog_content = "You... How dare you make jokes at a time like this!",
  ui_story_5043_50431402_25_dialog_content = "I was being entirely serious, Matthieu. All I want is to give the people the show they've been dying to see.",
  ui_story_5043_50431402_26_dialog_content = "A grandiose finale to this farce of a celebration!",
  ui_story_5043_50431402_27_dialog_content = "<size=45>This way, everyone! Quickly, now!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>The show is just about to start!</size>",
  ui_story_5043_50431402_29_dialog_content = "Schwab, what's the meaning of this?!",
  ui_story_5043_50431402_30_dialog_content = "He's trying to ruin the celebration! Those people are in danger!",
  ui_story_5043_50431402_31_dialog_content = "They're rushing over! Don't let them get near the Eclipsites!",
  ui_story_5043_50431402_32_dialog_content = "Don't worry, I'll protect them!",
  ui_story_5043_50431402_33_dialog_content = "Why so serious? It's nothing more than a show after all.",
  ui_story_5043_50431402_34_dialog_content = "Now that I recall, isn't the moon balloon supposed to explode today?",
  ui_story_5043_50431402_35_dialog_content = "I wonder what we'll find hiding inside that ridiculous, floating monument to love when it does.",
  ui_story_5043_50431402_36_dialog_content = "Don't tell me you...",
  ui_story_5043_50431402_37_dialog_content = "Behold the fruits of your ludicrous beliefs!",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>Pop—!!!</color>",
  ui_story_5043_50431402_39_dialog_content = "Wooooooow!!!",
  ui_story_5043_50431402_40_dialog_content = "Watch out, everyone!",
  ui_story_5043_50431402_41_dialog_content = "Hey, what's this floating down on us...?",
  ui_story_5043_50431402_42_dialog_content = "The gifts from ancient festivals—my clover bouquets—what are these?",
  ui_story_5043_50431402_43_dialog_content = "Are these dead flowers?",
  ui_story_5043_50431402_44_dialog_content = "Yes, dead roses, to be exact...",
  ui_story_5043_50431402_45_dialog_content = "The sky is full of dead flowers...",
  ui_story_5043_50431402_46_dialog_content = "What an ugly sight, I feel awful just seeing it.",
  ui_story_5043_50431402_47_dialog_content = "Is this really how the Moon Balloon's bursting was supposed to go?",
  ui_story_5043_50431402_48_dialog_content = "Indeed, it is!",
  ui_story_5043_50431402_49_dialog_content = "Not another step, Schwab!",
  ui_story_5043_50431402_50_dialog_content = "What's the matter, Judge Tina? Is this not the very picture of love?",
  ui_story_5043_50431402_51_dialog_content = "A beauty we can only imagine when we turn our eyes away from what lies within.",
  ui_story_5043_50431402_52_dialog_content = "Like the moon in the night sky, it captivates us with its mysterious, distant beauty.",
  ui_story_5043_50431402_53_dialog_content = "Its allure draws strength from the unknown, from the people's ignorance of its true nature.",
  ui_story_5043_50431402_54_dialog_content = "And now, everyone has witnessed it for themselves.",
  ui_story_5043_50431402_55_dialog_content = "This is the true meaning of your so-called love.",
  ui_story_5043_50431402_56_dialog_content = "All that remains after the excitement and absurdity die down is a world left in shambles.",
  ui_story_5043_50431402_57_dialog_content = "And from this day onwards, no one will see the moon for its beauty ever again.",
  ui_story_5043_50431402_58_dialog_content = "Well, he's right about one thing, I never want to see that stupid balloon again.",
  ui_story_5043_50431402_59_dialog_content = "No kidding, whose idea was to fill it with dead flowers? It was basically just a floating bag of garbage...",
  ui_story_5043_50431402_60_dialog_content = "Enough of your fallacious rhetoric! You were the one who changed the contents of the balloon, weren't you?!",
  ui_story_5043_50431402_61_dialog_content = "I never touched the contents of the balloon. All I did was remove the Luminatics surrounding it.",
  ui_story_5043_50431402_62_dialog_content = "You...!",
  ui_story_5043_50431402_63_dialog_content = "Don't look at me like that. You were the one who wanted to lie to the masses by preserving those flowers with Lumina.",
  ui_story_5043_50431402_64_dialog_content = "All I did was uncover the truth.",
  ui_story_5043_50431402_65_dialog_content = "Beauty is only appreciated when someone bears responsibility for ugliness.",
  ui_story_5043_50431402_66_dialog_content = "Just like those starry-eyed maidens who chase after me with their promises of love, they have no idea how much I suffer because of their flights of fancy.",
  ui_story_5043_50431402_67_dialog_content = "Is this really what love is...?",
  ui_story_5043_50431402_68_dialog_content = "Something so overwhelming that it creates burdens for others...",
  ui_story_5043_50431402_69_dialog_content = "It seems you are finally beginning to understand my message.",
  ui_story_5043_50431402_70_dialog_content = "...",
  ui_story_5043_50431402_71_dialog_content = "(Could it be that... I made the same kind of mistake?)",
  ui_story_5043_50431402_72_dialog_content = "That's not it at all, Tina! Don't let Schwab's misconceptions fool you!",
  ui_story_5043_50431402_73_dialog_content = "Huh?",
  ui_story_5043_50431402_74_dialog_content = "How could his \"truth\" possibly take precedence over other people's experiences?",
  ui_story_5043_50431402_75_dialog_content = "Just like any other emotion, we all feel love in our own ways.",
  ui_story_5043_50431402_76_dialog_content = "I may not know the \"truth\" behind the concept of love... But just seeing how happy everyone is during events like these is enough for me!",
  ui_story_5043_50431402_77_dialog_content = "And besides, I don't think Schwab has ever felt truly experienced love for himself!",
  ui_story_5043_50431402_78_dialog_content = "What right does he have to tell everyone else how to feel about it?!",
  ui_story_5043_50431402_79_dialog_content = "You...",
  ui_story_5043_50431402_80_dialog_content = "Of course I've never felt love before! How could I possibly allow myself to feel such a disgusting emotion?!",
  ui_story_5043_50431402_81_dialog_content = "Yeah, you're right, PlayerName!",
  ui_story_5043_50431402_82_dialog_content = "There's no truth to what he's saying at all. He's just fixated on the worst possible outcome!",
  ui_story_5043_50431402_83_dialog_content = "What's more, there's nothing wrong with imagining the beauty of love either!",
  ui_story_5043_50431402_84_dialog_content = "Love isn't something that can be decided in court. So who are we to pass judgment on it?",
  ui_story_5043_50431402_85_dialog_content = "Whether it's a confession of love or loving someone from afar, coming together, or parting ways, all these experiences are valid expressions of love!",
  ui_story_5043_50431402_86_dialog_content = "Schwab, you have no idea what love truly means!",
  ui_story_5043_50431402_87_dialog_content = "Hmph, you may be right in saying that I don't understand the meaning of love.",
  ui_story_5043_50431402_88_dialog_content = "Nor do I understand why you people would go to such lengths to pursue it.",
  ui_story_5043_50431402_89_dialog_content = "To me, love is nothing more than a hindrance, a parasitic emotion that shatters my peace and invites others to meddle in my life.",
  ui_story_5043_50431402_90_dialog_content = "No, its foul influence extends far beyond just my life! It threatens my career and ability to carry out my duties, it threatens the very balance of all Lumopolis!",
  ui_story_5043_50431402_91_dialog_content = "What makes you say that?",
  ui_story_5043_50431402_92_dialog_content = "Just look at the people around us. Even the slightest hint of emotion can make them abandon all reason.",
  ui_story_5043_50431402_93_dialog_content = "Those self-same emotions lead to the establishment of this mockery known as the Romance Division!",
  ui_story_5043_50431402_94_dialog_content = "What has love truly done for us, hmm? Aside from giving criminals a chance to escape punishment, it leads us to charge innocent people with crimes they never committed.",
  ui_story_5043_50431402_95_dialog_content = "It desecrates the centuries-old laws that have held Lumopolis together throughout its glorious history!",
  ui_story_5043_50431402_96_dialog_content = "For this reason, I chose to wield the full strength of the law against this accursed wave of \"love\" that plagues our fair city...",
  ui_story_5043_50431402_97_dialog_content = "All that I've done, I did with the sole purpose of eliminating love as a factor in the execution of justice!",
  ui_story_5043_50431402_98_dialog_content = "I needed jurors whose views aligned with my own, whose judgment wouldn't be poisoned by any unnecessary emotions.",
  ui_story_5043_50431402_99_dialog_content = "Thankfully, these hideous monsters were more than capable of filling those roles.",
  ui_story_5043_50431402_100_dialog_content = "...",
  ui_story_5043_50431402_101_dialog_content = "So that's what he was thinking all along...",
  ui_story_5043_50431402_102_dialog_content = "To justify one's own paranoia in such a way.",
  ui_story_5043_50431402_103_dialog_content = "This kind of person is far more terrifying than any infamy-seeking criminal.",
  ui_story_5043_50431402_104_dialog_content = "But let us bring this pointless conversation about love to a close.",
  ui_story_5043_50431402_105_dialog_content = "Instead, let us direct our attention to the case at hand.",
  ui_story_5043_50431402_106_dialog_content = "After all, you're all <color=#FFB400>guilty</color> in the eyes of the court!",
  ui_story_5043_50431402_107_dialog_content = "Hey, look over there!",
  ui_story_5043_50431402_108_dialog_content = "Eclipsites are pouring out from inside the Hall of Justice!",
  ui_story_5043_50431402_109_dialog_content = "This day can't get any crazier! Run away!!!",
  ui_story_5043_50431402_110_dialog_content = "Looks like Schwab is taking the offensive again.",
  ui_story_5043_50431402_111_dialog_content = "He's insane if he thinks he can summon Eclipsites in front of the public. The guards will have him in shackles soon enough.",
  ui_story_5043_50431402_112_dialog_content = "For now, we still need to take control of the situation and ensure no civilians are harmed by his actions.",
  ui_story_5043_50431402_113_dialog_content = "You say that, but those masked Eclipsites won't be easy to deal with...",
  ui_story_5043_50431402_114_dialog_content = "Let me handle them.",
  ui_story_5043_50431402_115_dialog_content = "On my honor, and the honor of the Campbell Family—",
  ui_story_5043_50431402_116_dialog_content = "Behold the power of the Divine Hand!",
  ui_story_5043_50431402_117_dialog_content = "Whoa! What's with this Lumina?!",
  ui_story_5043_50431402_118_dialog_content = "An attack like this might be enough to—",
  ui_story_5043_50431402_119_dialog_content = "Yaaaawn—",
  ui_story_5043_50431402_120_dialog_content = "Huh? H-Hey! Why are you yawning at a time like this?!",
  ui_story_5043_50431402_121_dialog_content = "Sorry... but I'm already... past my limit... for today...",
  ui_story_5043_50431402_122_dialog_content = "Hmph. Take them, Four Knights.",
  ui_story_5043_50431402_123_dialog_content = "W-Wait, time out! This isn't fair!!",
  ui_story_5043_50431402_124_dialog_content = "Snap out of it, Tina! Hey! Hey!!!",
  ui_story_5043_50431402_125_dialog_content = "Nnng... behold the power... of the Divine Hand...!",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>Slump—</color>",
  ui_story_5043_50431402_127_dialog_content = "Sh-She fell asleep before the fight even started!!!",
  ui_story_5043_50431402_128_dialog_content = "What should we do?! This is no place to take a nap!!!",
  ui_story_5043_50431402_129_dialog_content = "Wake up, Tina! The enemy is about to attack!",
  ui_story_5043_50431402_130_dialog_content = "Stars... I see stars... on your head... Leyn...",
  ui_story_5043_50431402_131_dialog_content = "This is no time for star-gazing! Get ready for battle!",
  ui_story_5043_50431402_132_dialog_content = "Sorry... but I can't...",
  ui_story_5043_50431402_133_dialog_content = "Here, just eat this.",
  ui_story_5043_50431402_134_dialog_content = "Is that chocolate?! This isn't the time for snacks either, Leyn!!!",
  ui_story_5043_50431402_135_dialog_content = "I'm... I'm...",
  ui_story_5043_50431402_136_dialog_content = "What do we do? They're right in front of us now...",
  ui_story_5043_50431402_137_dialog_content = "I'm perfectly awake now!!!",
  ui_story_5043_50431402_138_dialog_content = "Huh?!",
  ui_story_5043_50431402_139_dialog_content = "Talk about a power nap!!!",
  ui_story_5043_50431402_140_dialog_content = "Heh! When it comes to winning someone's heart, you have to rely on more than just one strategy!",
  ui_story_5043_50431402_141_dialog_content = "Let me show you how it's done!",
  ui_story_5043_50431402_142_dialog_content = "Uhh? What's that?",
  ui_story_5043_50431402_143_dialog_content = "Did you already forget? You and the others are the ones who showed me in the first place!",
  ui_story_5043_50431402_144_dialog_content = "There are lots of ways to pursue a romantic interest, including... <color=#FFB400>a confession</color>!",
  ui_story_5043_50431402_145_dialog_content = "You were right all along, Leyn! Getting the other person's full attention is the first step and one of the most important!",
  ui_story_5043_50431402_X145_dialog_content = "Draw the monsters away from the crowd!",
  ui_story_5043_50431402_146_dialog_content = "I'm sorry, what...?",
  ui_story_5043_50431402_147_dialog_content = "Alright, you masked monsters, take this!",
  ui_story_5043_50431402_148_dialog_content = "Graah...",
  ui_story_5043_50431402_149_dialog_content = "I believe the Divine Hand managed to get your undivided attention, yes?",
  ui_story_5043_50431402_X149_dialog_content = "Graagh!!!",
  ui_story_5043_50431402_X150_dialog_content = "You won't even leave a scratch on my knights with this level of power! Don't stop attacking!",
  ui_story_5043_50431402_150_dialog_content = "Judge Matthieu was the one who showed me what to do next. You still remember, right?",
  ui_story_5043_50431402_151_dialog_content = "People can't rely solely on taking the initiative. They also need to learn... <color=#FFB400>the art of concealment</color>!",
  ui_story_5043_50431402_152_dialog_content = "And justly so! I'll cover you, Tina!",
  ui_story_5043_50431402_153_dialog_content = "Quickly, let's take cover behind that wall!",
  ui_story_5043_50431402_154_dialog_content = "Hmph. Ready to give up after such a minor setback? Your love truly is fragile.",
  ui_story_5043_50431402_155_dialog_content = "Weren't you saying just now that you wanted to protect people?",
  ui_story_5043_50431402_156_dialog_content = "Graaaaah...",
  ui_story_5043_50431402_157_dialog_content = "Grah?",
  ui_story_5043_50431402_158_dialog_content = "I knew it! They can't find us!",
  ui_story_5043_50431402_159_dialog_content = "I think those masks they're wearing might be their weak points!",
  ui_story_5043_50431402_160_dialog_content = "You may be right. Let's take a look at what lies beneath their disguises!",
  ui_story_5043_50431402_161_dialog_content = "This is where the third method comes into play!",
  ui_story_5043_50431402_162_dialog_content = "To find the right balance between pressing forward and stepping back... <color=#FFB400>reconnaissance</color>!",
  ui_story_5043_50431402_163_dialog_content = "We need to understand the other person as much as possible before taking that final step.",
  ui_story_5043_50431402_X163_dialog_content = "We just need to find their weakness and deal the decisive blow to end all this!",
  ui_story_5043_50431402_164_dialog_content = "So let's start by attacking their masks!",
  ui_story_5043_50431402_165_dialog_content = "Now's our chance! Attack!",
  ui_story_5043_50431402_166_dialog_content = "Graaaah!!!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>Wham, wham, wham!!!</color>",
  ui_story_5043_50431402_168_dialog_content = "Argh, What are those things made of?!",
  ui_story_5043_50431402_169_dialog_content = "Looks like breaking those masks won't be as easy as we thought.",
  ui_story_5043_50431402_170_dialog_content = "Hahaha! Oh, if only you could see the stupid looks on your faces!",
  ui_story_5043_50431402_171_dialog_content = "Did you honestly believe you could harm my knights with such a pathetic attack?",
  ui_story_5043_50431402_172_dialog_content = "Hmph, even when it all seems hopeless, there's still a chance for love to prevail!",
  ui_story_5043_50431402_173_dialog_content = "At this point, tricks and strategies are out of the question. All that's left to do—",
  ui_story_5043_50431402_174_dialog_content = "Now, Tina!",
  ui_story_5043_50431402_175_dialog_content = "Show the world what's in your heart!!!",
  ui_story_5043_50431402_176_dialog_content = "That's right! I'll take every ounce of my sincerity!",
  ui_story_5043_50431402_177_dialog_content = "And use it to land the final blow!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>Divine Splendor</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "Phew, did she make it?",
  ui_story_5043_50431402_180_dialog_content = "She did! She blew the masks right off of those Eclipsites!",
  ui_story_5043_50431402_181_dialog_content = "H-How could this be?! My knights...",
  ui_story_5043_50431402_182_dialog_content = "Push forward, my knights!",
  ui_story_5043_50431402_183_dialog_content = "You cannot fail me now! Not when justice has yet to be served!",
  ui_story_5043_50431402_184_dialog_content = "It's over, Schwab.",
  ui_story_5043_50431402_185_dialog_content = "Just like you, they don't feel things like love or loyalty, all they can do is mindlessly follow orders.",
  ui_story_5043_50431402_186_dialog_content = "As you are now, you could never hope to overcome the raw power of our emotions.",
  ui_story_5043_50431402_187_dialog_content = "Even now, you insist on spouting on about your feelings?!",
  ui_story_5043_50431402_188_dialog_content = "She's right, you know? As for justice not being served... You don't have to worry about that anymore.",
  ui_story_5043_50431402_189_dialog_content = "With how things have turned out, the Hall of Justice will definitely take this case much more seriously.",
  ui_story_5043_50431402_190_dialog_content = "In fact, I wouldn't be surprised if Chief Judge Irridon presides over the entire thing.",
  ui_story_5043_50431402_191_dialog_content = "I'm sure she'll serve you the justice you want so badly, Schwab.",
  ui_story_5043_50431402_192_dialog_content = "Serve me? No... No! This can't be!",
  ui_story_5043_50431402_193_dialog_content = "I'm innocent, I tell you! None can pass judgment on me!!!",
  ui_story_5043_50431402_194_dialog_content = "That's not for you to decide.",
  ui_story_5043_50431402_195_dialog_content = "Of course it is, you fool! I'm the chief judge!!!",
  ui_story_5043_50431402_196_dialog_content = "That status isn't for you to decide anymore, either.",
  ui_story_5043_50431402_197_dialog_content = "Rotten! This city and its laws are rotten to the core now!",
  ui_story_5043_50431402_198_dialog_content = "Out of my way! My father will hear about this!",
  ui_story_5043_50431402_199_dialog_content = "Mark my words, the Salar Family will not rest until true justice is meted out!",
  ui_story_5043_50431402_200_dialog_content = "How shameful of you, Schwab. Running home to daddy when things don't go your way?",
  ui_story_5043_50431402_201_dialog_content = "What a disgrace.",
  ui_story_5043_50431402_202_dialog_content = "I said out of my way!!!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5043_50431402_204_dialog_content = "Urgh...!",
  ui_story_5043_50431402_205_dialog_content = "Wh-Who was it? Who struck me just now?!",
  ui_story_5043_50431402_206_dialog_content = "It was me, and unless you come with us peacefully to the Hall of Justice... There will be more where that came from.",
  ui_story_5043_50431402_207_dialog_content = "Leyn! You fool!",
  ui_story_5043_50431402_208_dialog_content = "Do you have any idea what you've just done, you wretched commoner?!",
  ui_story_5043_50431402_209_dialog_content = "It was for your own good.",
  ui_story_5043_50431402_210_dialog_content = "You might not have made it to your trial if Tina had hit you instead.",
  ui_story_5043_50431402_211_dialog_content = "It's true!",
  ui_story_5043_50431402_212_dialog_content = "Y-You all...",
  ui_story_5043_50431402_213_dialog_content = "That will do, everyone. The Romance Division's employees are still on the clock!",
  ui_story_5043_50431402_214_dialog_content = "Come, come! It's time to return to our duties!",
  ui_story_5043_50431402_215_dialog_content = "I guess we still have a lot of work for today, huh?",
  ui_story_5043_50431402_216_dialog_content = "Yaaaawn... Oh, thank goodness, a sofa...",
  ui_story_5043_50431402_217_dialog_content = "Hey! Keep your filthy hands off me!",
  ui_story_5043_50431402_218_dialog_content = "I will not be shoved about like some common criminal!",
  ui_story_5043_50431402_219_dialog_content = "Whoa! They're finally taking Schwab into custody!",
  ui_story_5043_50431402_220_dialog_content = "Looks like everything worked out in the end, huh?",
  ui_story_5043_50431402_221_dialog_content = "Indeed. Schwab has much to answer for. His punishment won’t be a light one.",
  ui_story_5043_50431402_222_dialog_content = "While his actions did not result in any real damage, they were still in direct violation of Lumopolis' laws.",
  ui_story_5043_50431402_223_dialog_content = "Should he ever choose to manipulate Eclipsites like this again... I don't dare imagine the consequences.",
  ui_story_5043_50431402_224_dialog_content = "I don't think he will. After all, his real enemy was love all along! Hahahaha!",
  ui_story_5043_50431402_225_dialog_content = "That's true. His hatred for the concept of love drove him to such extremes, not anyone or anything else, in particular.",
  ui_story_5043_50431402_226_dialog_content = "At the very least, he was able to deliver his misguided message, thanks to that sham of a trial and this stunt with the Moon Balloon.",
  ui_story_5043_50431402_227_dialog_content = "Yeah, I'd say this case is as good as closed!",
  ui_story_5043_50431402_228_dialog_content = "I never would've guessed that such a small incident would end in such a crazy way...",
  ui_story_5043_50431402_229_dialog_content = "Neither would I, but it's finally over.",
  ui_story_5043_50431402_230_dialog_content = "All that remains is to hear one final verdict.",
  ui_story_5043_50431402_231_dialog_content = "Yep! Let's go find some good seats!",
  ui_story_5043_50431402_232_dialog_content = "I can't wait to hear what the judge has to say about this.",
  ui_story_5043_50431402_233_dialog_content = "Huh? Is something the matter, Sister?",
  ui_story_5043_50431402_234_dialog_content = "It's over...",
  ui_story_5043_50431402_235_dialog_content = "Wh-Why are you crying?",
  ui_story_5043_50431402_236_dialog_content = "The people are gone, and so is the balloon.",
  ui_story_5043_50431402_237_dialog_content = "My flowers and clovers, it's all over...",
  ui_story_5043_50431402_238_dialog_content = "I'm sorry, Sister... But it wasn't your fault, it was Schwab's!",
  ui_story_5043_50431402_239_dialog_content = "Even so, it's all over now.",
  ui_story_5043_50431402_240_dialog_content = "Lumopolis' wave of love has finally receded...",
  ui_story_5043_50431501_1_dialog_content = "After a thorough investigation, the truth behind the crimes was exactly as Leyn had surmised.",
  ui_story_5043_50431501_2_dialog_content = "Schwab was declared the culprit behind the serial statue decapitations and was also found guilty of manipulating Eclipsites to do his bidding.",
  ui_story_5043_50431501_3_dialog_content = "Thankfully, no Aurorians were harmed due to his twisted actions, and the only damages incurred were to those three statues.",
  ui_story_5043_50431501_4_dialog_content = "I guess he still had some sense of justice in his heart after all, haha...",
  ui_story_5043_50431501_5_dialog_content = "I need to hand it to those three judges though. They managed to deduce the truth behind the crimes with hardly any evidence to help them!",
  ui_story_5043_50431501_6_dialog_content = "Indeed. After this case, I'm certain the Hall of Justice will look upon their talents with keener interest.",
  ui_story_5043_50431501_7_dialog_content = "There's still one thing I don't understand though.",
  ui_story_5043_50431501_8_dialog_content = "How exactly did Schwab manage to control those Eclipsites, to begin with?",
  ui_story_5043_50431501_9_dialog_content = "I didn't see him use any kind of special equipment during our battle...",
  ui_story_5043_50431501_10_dialog_content = "Oh, the investigation has a theory about that, as well.",
  ui_story_5043_50431501_11_dialog_content = "After acquiring the necessary warrants, the Hall of Justice searched the Salar Manor and found the cellar where Schwab hid his Eclipsites.",
  ui_story_5043_50431501_12_dialog_content = "Outside his cellar, however, the investigators found nothing that could have been used to control them.",
  ui_story_5043_50431501_13_dialog_content = "After a lengthy interrogation, as well as a complete search of the cellar, the Hall of Justice came to an unexpected conclusion.",
  ui_story_5043_50431501_14_dialog_content = "Schwab managed to tame the Eclipsites with methods unlike those used for animal training.",
  ui_story_5043_50431501_15_dialog_content = "He tamed them?!?",
  ui_story_5043_50431501_16_dialog_content = "Can Eclipsites really be trained like that?!",
  ui_story_5043_50431501_17_dialog_content = "If you think about it, the notion isn't completely outside of the realm of possibility.",
  ui_story_5043_50431501_18_dialog_content = "We Aurorians have seen the Eclipsites as our mortal enemies for generations. Naturally, we have an intense bias against them.",
  ui_story_5043_50431501_19_dialog_content = "But once you set aside the history between our species, you can see that Eclipsites are just creatures of lower intelligence.",
  ui_story_5043_50431501_20_dialog_content = "They have their own needs and behaviors and are no different than any other animal.",
  ui_story_5043_50431501_21_dialog_content = "By taking into account a creature's habits and characteristics, it can be trained to understand that following orders leads to positive outcomes. That's the logic behind beast-taming, isn't it?",
  ui_story_5043_50431501_22_dialog_content = "All Schwab did was domesticate them to a certain extent, much like our ancestors did with wolves and other animals.",
  ui_story_5043_50431501_23_dialog_content = "I see...",
  ui_story_5043_50431501_24_dialog_content = "It makes sense, but I still think it's kind of unbelievable.",
  ui_story_5043_50431501_25_dialog_content = "Many of the details in the case lend credibility to the conclusion.",
  ui_story_5043_50431501_26_dialog_content = "Schwab has always looked down upon his own kind, but oddly enough, he shows a strong affinity for small animals.",
  ui_story_5043_50431501_27_dialog_content = "For him to go to such incredible lengths for his schemes, it would have also taken an equally-incredible amount of patience.",
  ui_story_5043_50431501_28_dialog_content = "When you put it that way, he doesn't sound all that bad, at least not from an Aurorian's point of view.",
  ui_story_5043_50431501_29_dialog_content = "Oh, wait a minute, I'm not an Aurorian...",
  ui_story_5043_50431501_30_dialog_content = "Alright, I think we can save the rest of this discussion for later.",
  ui_story_5043_50431501_31_dialog_content = "Schwab's trial is about to begin.",
  ui_story_5043_50431501_32_dialog_content = "The defendant, Schwab Salar, stands accused of manipulating Eclipsites in order to carry out the destruction of three statues.",
  ui_story_5043_50431501_33_dialog_content = "The Hall of Justice has thoroughly investigated the matter, and the evidence acquired corroborates the accusation mentioned above.",
  ui_story_5043_50431501_34_dialog_content = "Have you anything to say in your defense, Schwab Salar?",
  ui_story_5043_50431501_35_dialog_content = "...",
  ui_story_5043_50431501_36_dialog_content = "(He used to act so high and mighty before, but now he looks completely ashamed of himself.)",
  ui_story_5043_50431501_37_dialog_content = "The investigation has also concluded that despite the defendant's unlawful behavior, no serious damage has been done to the city of Lumopolis or its people.",
  ui_story_5043_50431501_38_dialog_content = "In addition, considering the defendant's relatively young age, the court believes that he can still correct his ways. As such, the court will not impose a prison sentence on the defendant.",
  ui_story_5043_50431501_39_dialog_content = "Oh? So I won't be going to prison after all.",
  ui_story_5043_50431501_40_dialog_content = "It makes sense. Troublesome as he is, Schwab's actions were nothing more than misguided vandalism.",
  ui_story_5043_50431501_41_dialog_content = "Given the minor extent of the damage, there's no reason to send him to jail for his crimes.",
  ui_story_5043_50431501_42_dialog_content = "Nevertheless, exemption from a prison sentence does not signify a full exemption from all legal repercussions.",
  ui_story_5043_50431501_43_dialog_content = "The defendant, as well as the Salar Family, must bear any and all financial burdens incurred by this case.",
  ui_story_5043_50431501_44_dialog_content = "Your salary as a judge for the Hall of Justice will also be fully deducted.",
  ui_story_5043_50431501_45_dialog_content = "Of course. I accept my punishments without question.",
  ui_story_5043_50431501_46_dialog_content = "Why does he look so calm right now?",
  ui_story_5043_50431501_47_dialog_content = "Money is the least important thing in the world to a man like him.",
  ui_story_5043_50431501_48_dialog_content = "If that's the case, then don't you think his punishment is way too lenient?",
  ui_story_5043_50431501_49_dialog_content = "Naturally, this is only half of your sentence.",
  ui_story_5043_50431501_50_dialog_content = "After analyzing the events leading up to this incident, the Hall of Justice has concluded that Schwab Salar's extreme behavior resulted from a failure within the aristocracy's educational system.",
  ui_story_5043_50431501_51_dialog_content = "Therefore, in order to rectify this failure, the court sentences Schwab Salar to re-education at his previous place of study.",
  ui_story_5043_50431501_52_dialog_content = "What...? You mean I have to go back to the Dawn Academy and repeat my classes?!",
  ui_story_5043_50431501_53_dialog_content = "Colluding with Eclipsites is a serious crime and must be dealt with severely.",
  ui_story_5043_50431501_X53_dialog_content = "The court has decided that the offender, Schwab, is in need of the God of Light's renewed guidance.",
  ui_story_5043_50431501_54_dialog_content = "To receive this guidance, you have been assigned to the <color=#FFB400>temple in which nuns are trained</color>.",
  ui_story_5043_50431501_55_dialog_content = "N-Nuns?!?",
  ui_story_5043_50431501_56_dialog_content = "This... This goes too far, Your Honor!!!",
  ui_story_5043_50431501_57_dialog_content = "Allow me to introduce your new instructor. May your re-education proceed smoothly, Schwab Salar.",
  ui_story_5043_50431501_58_dialog_content = "We meet again, Mr. Schwab.",
  ui_story_5043_50431501_59_dialog_content = "It's you! That can only mean, this was your idea, wasn't it?!",
  ui_story_5043_50431501_60_dialog_content = "We have an exciting curriculum planned just for you. Apart from your daily theological studies, there will be lessons on sewing, cooking, and serving the less fortunate...",
  ui_story_5043_50431501_61_dialog_content = "I am honored to have the privilege of guiding your studies for the next several years.",
  ui_story_5043_50431501_62_dialog_content = "No, noooo!!! I refuse to be educated in a place run entirely by women!!!",
  ui_story_5043_50431501_63_dialog_content = "It seems your social values are also in need of re-education.",
  ui_story_5043_50431501_64_dialog_content = "Take him to the nunnery, and prepare him for his new life of study and reflection.",
  ui_story_5043_50431501_65_dialog_content = "Aside from Schwab, there are other parties in this case that are in need of reprimanding.",
  ui_story_5043_50431501_66_dialog_content = "Judge Leyn.",
  ui_story_5043_50431501_67_dialog_content = "Yes, Your Honor!",
  ui_story_5043_50431501_68_dialog_content = "You stand accused of breaking into the Salar Manor. Do you admit to this crime?",
  ui_story_5043_50431501_69_dialog_content = "Yes, I do.",
  ui_story_5043_50431501_70_dialog_content = "(I figured he wouldn't lie to the chief judge...)",
  ui_story_5043_50431501_71_dialog_content = "Very well. By authority of the Hall of Justice, and in accordance with Article 127 of the Judge's Code of Conduct...",
  ui_story_5043_50431501_72_dialog_content = "Your monthly performance grade shall be reset to zero, and your wages for this month shall be reduced to the minimum pay grade allowed as a public servant of Lumopolis.",
  ui_story_5043_50431501_73_dialog_content = "I-I understand...",
  ui_story_5043_50431501_74_dialog_content = "(He says that, but I think that was the most painful punishment he could've been given!)",
  ui_story_5043_50431501_75_dialog_content = "Well, now, really... I am just as guilty of this crime, Your Honor!",
  ui_story_5043_50431501_76_dialog_content = "I was with him at the time, so I believe this punishment should be divided between the two of us.",
  ui_story_5043_50431501_77_dialog_content = "Is that so, Judge Matthieu?",
  ui_story_5043_50431501_78_dialog_content = "I-I was there too! Don't forget about me!",
  ui_story_5043_50431501_79_dialog_content = "I must say, your willingness to acknowledge your mistakes is quite refreshing. Very well, then! Aside from Judge Matthieu's wages being docked for the month...",
  ui_story_5043_50431501_80_dialog_content = "I sentence the three of you to sweep the grounds outside the Hall of Justice later.",
  ui_story_5043_50431501_81_dialog_content = "The sight of all those dead flowers is very unpleasant.",
  ui_story_5043_50431501_82_dialog_content = "Wh-What manner of punishment is this??",
  ui_story_5043_50431501_83_dialog_content = "Would you like me to reconsider?",
  ui_story_5043_50431501_84_dialog_content = "N-No thank you, Your Honor! We are more than willing to acquiesce!",
  ui_story_5043_50431501_85_dialog_content = "Good. That just leaves one final verdict to pass.",
  ui_story_5043_50431501_86_dialog_content = "Will the witness, Toto, please approach the stand?",
  ui_story_5043_50431501_87_dialog_content = "I-I'm here, Your Honor!",
  ui_story_5043_50431501_88_dialog_content = "Oh, Toto!",
  ui_story_5043_50431501_89_dialog_content = "(Whoa! When did Toto get his hands on that outfit?)",
  ui_story_5043_50431501_90_dialog_content = "(It looks so refined. He blends in perfectly with the rest of Lumopolis!)",
  ui_story_5043_50431501_91_dialog_content = "As a victim in this case, you were nevertheless willing to assist Aurorians in pursuing justice. For that, I must commend you.",
  ui_story_5043_50431501_92_dialog_content = "However, the crime of perjury is not lightly tolerated here in the Hall of Justice.",
  ui_story_5043_50431501_93_dialog_content = "As an accomplice in Judge Leyn's strategy, you are equally guilty of this offense.",
  ui_story_5043_50431501_94_dialog_content = "I... I understand...",
  ui_story_5043_50431501_95_dialog_content = "As the chief judge, your punishment shall be—",
  ui_story_5043_50431501_96_dialog_content = "... apologize to Schwab.",
  ui_story_5043_50431501_97_dialog_content = "Uh... What?",
  ui_story_5043_50431501_98_dialog_content = "Y-You want us to apologize? That's all?",
  ui_story_5043_50431501_99_dialog_content = "Your act of perjury was also an affront to his honor as a judge of the Hall of Justice, so remember to show at least some modicum of sincerity when you apologize.",
  ui_story_5043_50431501_100_dialog_content = "And with that, all punishments related to this case have been dispensed.",
  ui_story_5043_50431501_101_dialog_content = "The case of the Serial Statue Decapitations is now closed! Court is adjourned!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>A few days later...</color>",
  ui_story_5043_50431501_104_dialog_content = "Ahem, here are the details of my travels in Longzhou from a few months ago.",
  ui_story_5043_50431501_105_dialog_content = "Very good. Thank you, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "While the balance of power shifts in the world around us, Lumopolis' stance will never change.",
  ui_story_5043_50431501_107_dialog_content = "I pray that Eraveil will continue to maintain friendly relations with our fair city.",
  ui_story_5043_50431501_108_dialog_content = "I pray that you feel the same way as well, my young friend.",
  ui_story_5043_50431501_109_dialog_content = "O-Of course, Lord Schwartz! I'm always happy to help when it comes to making peace with others!",
  ui_story_5043_50431501_110_dialog_content = "I'm delighted to hear that.",
  ui_story_5043_50431501_111_dialog_content = "(Phew... Glad that's finally over!)",
  ui_story_5043_50431501_112_dialog_content = "You know, you can be quite the diplomat when you put your mind to it, PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "Heheheh, you think so? To be honest, I still feel a little nervous.",
  ui_story_5043_50431501_114_dialog_content = "This concludes our meeting for today. Are there any further questions?",
  ui_story_5043_50431501_115_dialog_content = "The Hall of Justice has nothing more to report.",
  ui_story_5043_50431501_116_dialog_content = "Duke Otto?",
  ui_story_5043_50431501_117_dialog_content = "Hmph, my legs are starting to get tired from all this sitting.",
  ui_story_5043_50431501_118_dialog_content = "Very well, then. Thank you all again. You are free to leave now.",
  ui_story_5043_50431501_119_dialog_content = "(Not yet, there is one last thing I need to bring up while the Hall of Justice and Elder Council representatives are still here.)",
  ui_story_5043_50431501_120_dialog_content = "(Apart from Eclipsites and uncontrollable mobs of people, another party in Lumopolis has been sowing discord recently.)",
  ui_story_5043_50431501_121_dialog_content = "(As Captain of the Guards of Lumopolis Gardens, I have a duty to tell the Elder Council!)",
  ui_story_5043_50431501_122_dialog_content = "Father, Duke Otto... A moment of your time, please.",
  ui_story_5043_50431501_123_dialog_content = "I must say, Lord Schwartz, the Lumopolis Gardens have been handling all of the recent emergencies quite effectively.",
  ui_story_5043_50431501_124_dialog_content = "I was quite surprised to see how well they work with the people of Lumopolis.",
  ui_story_5043_50431501_125_dialog_content = "Haha, your praise is far too gracious, Duke Otto. Naturally, we owe much of our success to the Elder Council's support.",
  ui_story_5043_50431501_126_dialog_content = "Without your assistance in the fight against the Eclipsites, the Guards of Lumopolis Gardens would not be capable of addressing our city's needs.",
  ui_story_5043_50431501_127_dialog_content = "What is it, Carleen?",
  ui_story_5043_50431501_128_dialog_content = "...",
  ui_story_5043_50431501_129_dialog_content = "Ah, say no more, milady. I do not wish to intrude upon a conversation between father and daughter. Good day.",
  ui_story_5043_50431501_130_dialog_content = "My lord, I presume you are aware of what the Elder Council's guards did during Mooncrown Day, yes?",
  ui_story_5043_50431501_131_dialog_content = "Far more aware than you think, Carleen.",
  ui_story_5043_50431501_132_dialog_content = "In the past year, you have shown yourself to be calmer and more courageous than ever before.",
  ui_story_5043_50431501_133_dialog_content = "However, addressing political matters such as these requires more than just courage.",
  ui_story_5043_50431501_134_dialog_content = "When my current work is complete, I shall arrange for holiday time to be given to everyone in the Lumopolis Gardens.",
  ui_story_5043_50431501_135_dialog_content = "That won't be necessary, but thank you, Father.",
  ui_story_5043_50431501_136_dialog_content = "Let's go, PlayerName.",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50431501_138_dialog_content = "Congratulations on a successful work report, PlayerName!!!",
  ui_story_5043_50431501_139_dialog_content = "We knew it the moment we saw Chief Judge Irridon walk out of the conference room!",
  ui_story_5043_50431501_140_dialog_content = "These firecrackers were left over from when they were given to Byron for his statues.",
  ui_story_5043_50431501_141_dialog_content = "Can't let them go to waste, right?",
  ui_story_5043_50431501_142_dialog_content = "What's the matter? Too surprised to speak?",
  ui_story_5043_50431501_143_dialog_content = "Cheer up, won't you? That goes for you too, Lady Carleen!",
  ui_story_5043_50431501_144_dialog_content = "Congratulations on a job well done, PlayerName.",
  ui_story_5043_50431501_145_dialog_content = "Wow... Thank you, everyone!",
  ui_story_5043_50431501_146_dialog_content = "You're all so...",
  ui_story_5043_50431501_147_dialog_content = "Sigh, what are we supposed to do with you?",
  ui_story_5043_50431501_148_dialog_content = "Forgive me for spoiling the fun, everyone. But the Hall of Justice's work is still not finished.",
  ui_story_5043_50431501_149_dialog_content = "Your assistance would also be greatly appreciated, Lady Carleen.",
  ui_story_5043_50431501_150_dialog_content = "This matter requires the cooperation of someone from the Lumopolis Gardens.",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>The Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431501_152_dialog_content = "I see.",
  ui_story_5043_50431501_153_dialog_content = "So despite the Romance Division's dissolution, numerous cases still have yet to be resolved.",
  ui_story_5043_50431501_154_dialog_content = "The Hall of Justice remains as diligent as ever, Chief Judge.",
  ui_story_5043_50431501_155_dialog_content = "Wow, just look at all these files! We'll be here for weeks just trying to read through them all...",
  ui_story_5043_50431501_156_dialog_content = "Well then, I'm counting on—",
  ui_story_5043_50431501_157_dialog_content = "We know...",
  ui_story_5043_50431501_158_dialog_content = "One last thing, Lady Carleen. While these cases may appear to be simple disputes between lovers at first glance...",
  ui_story_5043_50431501_159_dialog_content = "A deeper probe into their contents quickly reveals a myriad of problems that affect Lumopolis on a fundamental and social level.",
  ui_story_5043_50431501_160_dialog_content = "By reading through them, I gained tremendous insight into the thoughts and motives of those living in the Lumopolis Courtyard and Lower Lumopolis. It was an unprecedented experience for me.",
  ui_story_5043_50431501_161_dialog_content = "Their various interpretations of love and faith... Gave me much to think about.",
  ui_story_5043_50431501_162_dialog_content = "I believe that understanding these cases is key to revising our laws to benefit Lumopolis as a whole.",
  ui_story_5043_50431501_163_dialog_content = "When that time comes, I pray that the Hall of Justice will have the support of the City Lord, as well as your own.",
  ui_story_5043_50431501_164_dialog_content = "To summarize, I believe this work is essential for ensuring a bright and prosperous future for Lumopolis.",
  ui_story_5043_50431501_165_dialog_content = "Very well, I agree with your request.",
  ui_story_5043_50431501_166_dialog_content = "After all, Irridon... You are not the only one who feels this way.",
  ui_story_5043_50431501_167_dialog_content = "You must feel a lot happier now, right Carleen?",
  ui_story_5043_50431501_168_dialog_content = "Oh? Is it that obvious to you?",
  ui_story_5043_50431501_169_dialog_content = "Honestly, I'm kind of shocked at how quickly the streets have gone back to normal.",
  ui_story_5043_50431501_170_dialog_content = "Just like that, the stalls and parades are all gone, and the moon isn't floating overhead anymore.",
  ui_story_5043_50431501_171_dialog_content = "Is it really that surprising to you, Leyn? We are nobles, after all.",
  ui_story_5043_50431501_172_dialog_content = "Times and trends are always changing in Lumopolis. How could we possibly let ourselves fall behind on the latest things?",
  ui_story_5043_50431501_173_dialog_content = "See for yourselves!",
  ui_story_5043_50431501_174_dialog_content = "Huh? Aren't those gloves the same as mine?",
  ui_story_5043_50431501_175_dialog_content = "Yes, but they've recently become the hottest fashion item on the market. Members of the nobility have already been seen wearing them to various social occasions.",
  ui_story_5043_50431501_176_dialog_content = "They are a bit too thick for my taste, but that didn't stop me from buying seven pairs of them!",
  ui_story_5043_50431501_177_dialog_content = "How ridiculously frivolous.",
  ui_story_5043_50431501_178_dialog_content = "Exactly what you'd expect from a rich kid...",
  ui_story_5043_50431501_179_dialog_content = "Hmph! Ignore these philistines, Tina. Tell me, how does it feel to be the trendsetter of Lumopolis' latest fashion craze?",
  ui_story_5043_50431501_180_dialog_content = "Oh, and how are things going with Toto? Have you found a way to keep him yet?",
  ui_story_5043_50431501_181_dialog_content = "Something like that would be taboo here in Lumopolis... But that's what makes it all the more exciting, no?",
  ui_story_5043_50431501_182_dialog_content = "A-Actually, everyone... I asked Toto to meet me here today.",
  ui_story_5043_50431501_183_dialog_content = "That way, I could say <color=#FFB400>goodbye</color> to him.",
  ui_story_5043_50431501_184_dialog_content = "What?!",
  ui_story_5043_50431501_185_dialog_content = "But why so soon? I had no idea your kindness towards him could be so short-lived!",
  ui_story_5043_50431501_186_dialog_content = "Th-That's not it! If anything, it's precisely because I care so much for the sweet little guy!",
  ui_story_5043_50431501_187_dialog_content = "Eclipsites have been feared and hated for as long as anyone can remember, but Toto isn't like the others!",
  ui_story_5043_50431501_188_dialog_content = "Even so, not everyone would be willing to see things this way, much less accept them.",
  ui_story_5043_50431501_189_dialog_content = "If I insisted on staying here in Lumopolis with him, it would make life much harder for him.",
  ui_story_5043_50431501_190_dialog_content = "I'm sure he's been more scared than happy in his last month of living here.",
  ui_story_5043_50431501_191_dialog_content = "... Hmm?",
  ui_story_5043_50431501_192_dialog_content = "Um...",
  ui_story_5043_50431501_193_dialog_content = "Why are you hiding over there, Toto? Come over here!",
  ui_story_5043_50431501_194_dialog_content = "Y-You guys are all here...",
  ui_story_5043_50431501_X194_dialog_content = "You changed your clothes!?",
  ui_story_5043_50431501_X195_dialog_content = "You look so refined, perfectly blend in with the rest of Lumopolis!",
  ui_story_5043_50431501_X196_dialog_content = "Right... Today is an important day, after all, so I wanted to dress for the occasion.",
  ui_story_5043_50431501_195_dialog_content = "Actually, I came to say goodbye too.",
  ui_story_5043_50431501_196_dialog_content = "So you plan on hitting the road again, huh?",
  ui_story_5043_50431501_197_dialog_content = "Th-That's right, but not in the way you might be thinking.",
  ui_story_5043_50431501_198_dialog_content = "My last few days in Lumopolis have been full of danger and terror.",
  ui_story_5043_50431501_199_dialog_content = "But they've also been some of the happiest days of my life too.",
  ui_story_5043_50431501_200_dialog_content = "That's because I met all of you.",
  ui_story_5043_50431501_201_dialog_content = "E-Especially you, Tina.",
  ui_story_5043_50431501_202_dialog_content = "Thank you, Toto.",
  ui_story_5043_50431501_203_dialog_content = "Y-You were the first Aurorian to ever show me unconditional kindness.",
  ui_story_5043_50431501_204_dialog_content = "I-It's something I will cherish for the rest of my life.",
  ui_story_5043_50431501_205_dialog_content = "(Unconditional kindness, huh...)",
  ui_story_5043_50431501_206_dialog_content = "(I know how he feels. It really is something precious.)",
  ui_story_5043_50431501_207_dialog_content = "... Best of luck on your travels, Toto.",
  ui_story_5043_50431501_208_dialog_content = "I hope that we have a chance to meet again someday, my friend.",
  ui_story_5043_50431501_209_dialog_content = "Oh, wait! Before you go, I have something I've always wanted to give you.",
  ui_story_5043_50431501_210_dialog_content = "Here, it's a batch of freshly-baked cookies. The road ahead of you will be a long one for sure. So hopefully these make your journey a little easier!",
  ui_story_5043_50431501_211_dialog_content = "Sniff... Th-Thank you... Thank you so much, Tina...",
  ui_story_5043_50431501_212_dialog_content = "I-I'll treasure every single one of them!!!",
  ui_story_5043_50431501_213_dialog_content = "Hahahaha! Just don't treasure them too much, okay? They're meant for eating, after all!",
  ui_story_5043_50431501_214_dialog_content = "You should get going now.",
  ui_story_5043_50431501_215_dialog_content = "The sun may never set on Lumopolis, but that's not necessarily the case for the rest of the world.",
  ui_story_5043_50431501_216_dialog_content = "R-Right, then... I'll be going now!",
  ui_story_5043_50431501_217_dialog_content = "Goodbye, everyone!!!",
  ui_story_5043_50431501_218_dialog_content = "Goodbye, Toto!!!",
  ui_story_5043_50431501_219_dialog_content = "And so, our little hero departs once again! ♪",
  ui_story_5043_50431501_220_dialog_content = "But this time, he leaves with a gift from his friends! ♪",
  ui_story_5043_50431501_221_dialog_content = "The scent of baked treats floats behind him as he leaves ♪",
  ui_story_5043_50431501_222_dialog_content = "And into the Lumopolis skies on a morning breeze! ♪"
}
return config
